def inspect_import_source_plugin(
    conn,
    plugin: dict[str, Any],
    payload: dict[str, Any] | None = None,
    actor: dict[str, Any] | None = None,
) -> tuple[dict[str, Any], dict[str, Any]]:
    config = plugin_config_from_db(conn, str(plugin.get("id")))
    context = plugin_execution_context(conn, plugin, config, actor)
    execution = run_plugin_entrypoint(str(plugin.get("id")), "inspect_source", payload or {}, context)
    return normalize_import_source_result(plugin, execution), execution


def import_source_item_identifiers(item: dict[str, Any]) -> dict[str, str]:
    identifiers: dict[str, str] = {}
    if not isinstance(item, dict):
        return identifiers
    tmdb_id = clean_text(item.get("tmdbId") or item.get("tmdb_id"))
    imdb_id = clean_text(item.get("imdbId") or item.get("imdb_id"))
    if tmdb_id:
        identifiers["tmdb"] = tmdb_id
    if imdb_id:
        identifiers["imdb"] = imdb_id
    raw_identifiers = item.get("identifiers")
    if isinstance(raw_identifiers, dict):
        for provider, identifier in raw_identifiers.items():
            provider_id = clean_text(provider).lower()
            value = clean_text(identifier)
            if provider_id and value:
                identifiers[provider_id] = value
    return identifiers


def box_set_member_dedupe_keys(member: dict[str, Any]) -> set[tuple[str, str]]:
    if not isinstance(member, dict):
        return set()
    keys: set[tuple[str, str]] = set()
    tmdb_id = clean_text(member.get("tmdbId") or member.get("tmdb_id"))
    imdb_id = clean_text(member.get("imdbId") or member.get("imdb_id"))
    if tmdb_id:
        keys.add(("tmdb", tmdb_id.casefold()))
    if imdb_id:
        keys.add(("imdb", imdb_id.casefold()))
    title = clean_text(member.get("title") or member.get("name") or member.get("originalTitle") or member.get("original_title"))
    if title:
        normalized_title = re.sub(r"[^a-z0-9]+", " ", title.casefold()).strip()
        year = clean_text(member.get("year") or member.get("releaseYear") or member.get("release_year"))
        year = year[:4] if year and re.match(r"^\d{4}", year) else ""
        if normalized_title and year:
            keys.add(("title_year", f"{normalized_title}:{year}"))
        elif normalized_title:
            keys.add(("title", normalized_title))
    return keys


def dedupe_box_set_members(members: list[dict[str, Any]]) -> list[dict[str, Any]]:
    deduped: list[dict[str, Any]] = []
    seen: set[tuple[str, str]] = set()
    for member in members:
        keys = box_set_member_dedupe_keys(member)
        if keys and seen.intersection(keys):
            continue
        if keys:
            seen.update(keys)
        deduped.append(member)
    return deduped


def box_set_proposal_member_list(proposal: dict[str, Any]) -> list[dict[str, Any]]:
    if not isinstance(proposal, dict):
        return []
    for key in ("members", "movies", "boxSetMovies", "box_set_movies", "items", "releases"):
        value = proposal.get(key)
        if not isinstance(value, list):
            continue
        members = [
            item
            for item in value
            if isinstance(item, dict) and clean_text(item.get("title") or item.get("name"))
        ]
        if members:
            return dedupe_box_set_members(members)
    return []


def box_set_proposal_provider_text(proposal: dict[str, Any]) -> str:
    if not isinstance(proposal, dict):
        return ""
    return " ".join(
        clean_text(value) or ""
        for value in (
            proposal.get("provider"),
            proposal.get("pluginId"),
            proposal.get("plugin_id"),
            proposal.get("source"),
            proposal.get("memberSource"),
            proposal.get("member_source"),
        )
    ).casefold()


def box_set_proposal_evidence(proposal: dict[str, Any]) -> dict[str, Any]:
    if not isinstance(proposal, dict):
        return {}
    evidence = proposal.get("boxSetEvidence") or proposal.get("box_set_evidence") or {}
    return evidence if isinstance(evidence, dict) else {}


def box_set_evidence_bool(evidence: dict[str, Any], *keys: str) -> bool:
    for key in keys:
        value = evidence.get(key)
        if isinstance(value, bool):
            return value
        text = clean_text(value)
        if text:
            return text.casefold() in {"1", "true", "yes", "y", "on"}
    return False


def box_set_proposal_has_explicit_members(proposal: dict[str, Any]) -> bool:
    members = box_set_proposal_member_list(proposal)
    if len(members) < 2:
        return False
    evidence = box_set_proposal_evidence(proposal)
    if evidence:
        return box_set_evidence_bool(evidence, "membersAreExplicit", "members_are_explicit")
    confidence = (clean_text(proposal.get("memberConfidence") or proposal.get("member_confidence")) or "").casefold()
    return confidence not in {"candidate", "fallback", "metadata_candidates"}


def box_set_proposal_has_exact_barcode_match(proposal: dict[str, Any]) -> bool:
    evidence = box_set_proposal_evidence(proposal)
    return box_set_evidence_bool(evidence, "barcodeMatch", "barcode_match")


def box_set_proposal_is_upcitemdb(proposal: dict[str, Any]) -> bool:
    return "upcitemdb" in box_set_proposal_provider_text(proposal)


def box_set_proposal_is_candidate_only(proposal: dict[str, Any]) -> bool:
    if not isinstance(proposal, dict):
        return True
    evidence = box_set_proposal_evidence(proposal)
    confidence = (
        clean_text(
            evidence.get("memberConfidence")
            or evidence.get("member_confidence")
            or proposal.get("memberConfidence")
            or proposal.get("member_confidence")
        ) or ""
    ).casefold()
    source = (
        clean_text(
            evidence.get("memberSource")
            or evidence.get("member_source")
            or proposal.get("memberSource")
            or proposal.get("member_source")
        ) or ""
    ).casefold()
    return (
        box_set_proposal_is_upcitemdb(proposal)
        or proposal.get("detectedWithoutMembers") is True
        or proposal.get("detected_without_members") is True
        or evidence.get("detectedWithoutMembers") is True
        or evidence.get("detected_without_members") is True
        or confidence == "candidate"
        or source == "metadata_candidates"
    )


def box_set_proposal_sort_key(proposal: dict[str, Any]) -> tuple[int, int, int, int, int]:
    provider = box_set_proposal_provider_text(proposal)
    member_count = len(box_set_proposal_member_list(proposal))
    explicit_members = box_set_proposal_has_explicit_members(proposal)
    exact_barcode = box_set_proposal_has_exact_barcode_match(proposal)
    candidate_only = box_set_proposal_is_candidate_only(proposal)
    if "upcitemdb" in provider:
        provider_rank = 9
    elif ("movievault_26" in provider or "movievault 26" in provider) and exact_barcode and explicit_members:
        provider_rank = 0
    elif "movievault" in provider:
        provider_rank = 1
    elif ("bluray" in provider or "blu-ray" in provider) and explicit_members:
        provider_rank = 2
    elif "tmdb" in provider:
        provider_rank = 3
    elif "bluray" in provider or "blu-ray" in provider:
        provider_rank = 4
    else:
        provider_rank = 5
    exact_rank = 0 if exact_barcode and explicit_members else 1
    candidate_rank = 1 if candidate_only else 0
    without_members_rank = 1 if (
        proposal.get("detectedWithoutMembers") is True
        or proposal.get("detected_without_members") is True
        or box_set_proposal_evidence(proposal).get("detectedWithoutMembers") is True
    ) else 0
    return (exact_rank, provider_rank, candidate_rank, without_members_rank, -member_count)


def box_set_proposal_auto_importable(proposal: dict[str, Any]) -> bool:
    return (
        not box_set_proposal_is_candidate_only(proposal)
        and box_set_proposal_has_exact_barcode_match(proposal)
        and box_set_proposal_has_explicit_members(proposal)
    )


def box_set_proposal_audit_summary(proposal: dict[str, Any]) -> dict[str, Any]:
    if not isinstance(proposal, dict):
        return {}
    members = box_set_proposal_member_list(proposal)
    evidence = box_set_proposal_evidence(proposal)
    return {
        "proposalKey": clean_text(proposal.get("_proposalKey") or proposal.get("proposalKey")),
        "provider": clean_text(
            proposal.get("provider")
            or proposal.get("pluginId")
            or proposal.get("plugin_id")
            or proposal.get("source")
        ),
        "title": clean_text(proposal.get("title") or proposal.get("name")),
        "barcode": clean_text(proposal.get("barcode")),
        "format": clean_text(proposal.get("format")),
        "memberSource": clean_text(proposal.get("memberSource") or proposal.get("member_source") or proposal.get("source")),
        "memberConfidence": clean_text(proposal.get("memberConfidence") or proposal.get("member_confidence")),
        "memberCount": len(members),
        "candidateOnly": box_set_proposal_is_candidate_only(proposal),
        "autoImportable": box_set_proposal_auto_importable(proposal),
        "membersAreExplicit": box_set_proposal_has_explicit_members(proposal),
        "barcodeMatch": box_set_proposal_has_exact_barcode_match(proposal),
        "detectedWithoutMembers": bool(
            proposal.get("detectedWithoutMembers") is True
            or proposal.get("detected_without_members") is True
            or evidence.get("detectedWithoutMembers") is True
        ),
        "boxSetEvidence": evidence,
        "rank": list(box_set_proposal_sort_key(proposal)),
        "members": [
            {
                "title": clean_text(member.get("title") or member.get("name")),
                "year": clean_text(member.get("year") or member.get("releaseYear") or member.get("release_year")),
                "format": clean_text(member.get("format")),
                "source": clean_text(member.get("source") or member.get("provider")),
                "tmdbId": clean_text(member.get("tmdbId") or member.get("tmdb_id")),
                "imdbId": clean_text(member.get("imdbId") or member.get("imdb_id")),
            }
            for member in members[:12]
            if isinstance(member, dict)
        ],
    }


def selected_import_movie_candidate_from_body(body: dict[str, Any]) -> dict[str, Any]:
    raw = body.get("selectedMovieCandidate") or body.get("selected_movie_candidate") or {}
    if not isinstance(raw, dict):
        return {}
    candidate = raw.get("candidate") if isinstance(raw.get("candidate"), dict) else raw
    movie_updates = candidate.get("movieUpdates") if isinstance(candidate.get("movieUpdates"), dict) else {}
    metadata_updates = candidate.get("metadataUpdates") if isinstance(candidate.get("metadataUpdates"), dict) else {}
    media_updates = candidate.get("mediaUpdates") if isinstance(candidate.get("mediaUpdates"), dict) else {}
    poster_update = media_updates.get("poster") if isinstance(media_updates.get("poster"), dict) else {}
    backdrop_update = media_updates.get("backdrop") if isinstance(media_updates.get("backdrop"), dict) else {}

    def first_value(*values: Any) -> str:
        for value in values:
            text = clean_text(value)
            if text:
                return text
        return ""

    identifiers = import_source_item_identifiers(candidate)
    provider = first_value(
        candidate.get("provider"),
        candidate.get("pluginId"),
        candidate.get("providerId"),
        candidate.get("source"),
    )
    source_label = first_value(candidate.get("sourceLabel"), candidate.get("providerLabel"), provider)
    title = first_value(
        candidate.get("title"),
        candidate.get("originalTitle"),
        candidate.get("original_title"),
        candidate.get("name"),
        movie_updates.get("title"),
        movie_updates.get("original_title"),
    )
    if not title:
        return {}
    return {
        "provider": provider or "selected_import_candidate",
        "sourceLabel": source_label or provider or "Selected import candidate",
        "sourceRef": first_value(
            candidate.get("sourceRef"),
            candidate.get("sourceUrl"),
            candidate.get("source_url"),
            candidate.get("detailUrl"),
            candidate.get("detail_url"),
        ),
        "title": title,
        "releaseTitle": first_value(
            candidate.get("releaseTitle"),
            candidate.get("release_title"),
            movie_updates.get("release_title"),
        ),
        "year": first_value(
            candidate.get("year"),
            candidate.get("releaseYear"),
            candidate.get("release_year"),
            movie_updates.get("year"),
        ),
        "format": first_value(
            candidate.get("format"),
            candidate.get("mediaFormat"),
            candidate.get("media_format"),
            candidate.get("releaseFormat"),
            candidate.get("release_format"),
            movie_updates.get("format"),
        ),
        "barcode": first_value(
            candidate.get("barcode"),
            candidate.get("externalBarcode"),
            candidate.get("external_barcode"),
            candidate.get("ean"),
            candidate.get("upc"),
        ),
        "poster_url": first_value(
            candidate.get("posterUrl"),
            candidate.get("poster_url"),
            candidate.get("poster"),
            candidate.get("coverUrl"),
            candidate.get("cover_url"),
            metadata_updates.get("poster_url"),
            metadata_updates.get("posterUrl"),
            metadata_updates.get("poster"),
            poster_update.get("sourceUrl"),
            poster_update.get("source_url"),
        ),
        "backdrop_url": first_value(
            candidate.get("backdropUrl"),
            candidate.get("backdrop_url"),
            candidate.get("backdrop"),
            metadata_updates.get("backdrop_url"),
            metadata_updates.get("backdropUrl"),
            backdrop_update.get("sourceUrl"),
            backdrop_update.get("source_url"),
        ),
        "overview": first_value(
            candidate.get("overview"),
            candidate.get("plot"),
            candidate.get("description"),
            movie_updates.get("overview"),
            metadata_updates.get("overview"),
        ),
        "identifiers": identifiers,
    }


def selected_import_movie_candidate_proposal(candidate: dict[str, Any]) -> dict[str, Any]:
    if not isinstance(candidate, dict) or not clean_text(candidate.get("title")):
        return {}
    provider = clean_text(candidate.get("provider")) or "selected_import_candidate"
    source_label = clean_text(candidate.get("sourceLabel")) or provider
    source_ref = clean_text(candidate.get("sourceRef"))

    # Split the clean film title from the raw scanned/packaging title so the saved
    # Title field holds only the movie title while the full packaging string
    # (e.g. "John Wick (4K Ultra HD + Blu-ray) (UK Import)") is preserved as the
    # release title. This mirrors canonicalize_plugin_result, so a candidate
    # selected during a barcode scan honours the same contract no matter which
    # metadata source (or plugin order) produced it.
    raw_candidate_title = clean_text(candidate.get("title"))
    raw_release_title = clean_text(candidate.get("releaseTitle") or candidate.get("release_title"))
    if not raw_release_title and raw_candidate_title and _SCANNED_TITLE_NOISE_RE.search(raw_candidate_title):
        raw_release_title = raw_candidate_title
    clean_title = _clean_scanned_title(raw_release_title) if raw_release_title else raw_candidate_title
    movie_updates: dict[str, Any] = {"title": clean_title or raw_candidate_title}
    technical_updates: dict[str, Any] = {}
    if raw_release_title:
        movie_updates["release_title"] = raw_release_title
        import_country, import_region = _parse_import_country(raw_release_title)
        if import_country:
            movie_updates.setdefault("country", import_country)
        if import_region:
            technical_updates["regions"] = normalize_list_field("regions", import_region)
    if clean_text(candidate.get("year")):
        movie_updates["year"] = clean_text(candidate.get("year"))
    if clean_text(candidate.get("format")):
        movie_updates["format"] = clean_text(candidate.get("format"))
    if clean_text(candidate.get("overview")):
        movie_updates["overview"] = clean_text(candidate.get("overview"))

    metadata_updates: dict[str, Any] = {}
    media_updates: dict[str, dict[str, Any]] = {}
    poster_url = clean_text(candidate.get("poster_url"))
    if poster_url:
        metadata_updates["poster_url"] = poster_url
        media_updates["poster"] = {
            "kind": "poster",
            "field": "poster_url",
            "sourceUrl": poster_url,
            "options": [poster_url],
            "providerId": provider,
            "sourceLabel": source_label,
            "sourceRef": source_ref,
        }
    backdrop_url = clean_text(candidate.get("backdrop_url"))
    if backdrop_url:
        metadata_updates["backdrop_url"] = backdrop_url
        media_updates["backdrop"] = {
            "kind": "backdrop",
            "field": "backdrop_url",
            "sourceUrl": backdrop_url,
            "options": [backdrop_url],
            "providerId": provider,
            "sourceLabel": source_label,
            "sourceRef": source_ref,
        }

    provenance = []
    for field in movie_updates:
        provenance.append(
            {
                "field": field,
                "target": "movie",
                "pluginId": provider,
                "entrypoint": "selected_import_candidate",
                "reason": "selected import match",
                "sourceLabel": source_label,
                "sourceRef": source_ref,
            }
        )
    for field in metadata_updates:
        provenance.append(
            {
                "field": field,
                "target": "metadata",
                "pluginId": provider,
                "entrypoint": "selected_import_candidate",
                "reason": "selected import match",
                "sourceLabel": source_label,
                "sourceRef": source_ref,
            }
        )
    for field in technical_updates:
        provenance.append(
            {
                "field": field,
                "target": "technical",
                "pluginId": provider,
                "entrypoint": "selected_import_candidate",
                "reason": "selected import match",
                "sourceLabel": source_label,
                "sourceRef": source_ref,
            }
        )
    for field in media_updates:
        provenance.append(
            {
                "field": field,
                "target": "media",
                "pluginId": provider,
                "entrypoint": "selected_import_candidate",
                "reason": "selected provider image",
                "sourceLabel": source_label,
                "sourceRef": source_ref,
            }
        )

    return {
        "movieUpdates": movie_updates,
        "metadataUpdates": metadata_updates,
        "technicalUpdates": technical_updates,
        "mediaUpdates": media_updates,
        "identifiers": candidate.get("identifiers") if isinstance(candidate.get("identifiers"), dict) else {},
        "provenance": provenance,
        "skipped": [],
    }


def merge_selected_import_movie_candidate(
    proposal: dict[str, Any],
    candidate: dict[str, Any],
) -> dict[str, Any]:
    selected = selected_import_movie_candidate_proposal(candidate)
    if not selected:
        return proposal if isinstance(proposal, dict) else {}
    merged = dict(proposal) if isinstance(proposal, dict) else {}
    for key in ("movieUpdates", "metadataUpdates", "technicalUpdates", "mediaUpdates", "identifiers"):
        existing = merged.get(key) if isinstance(merged.get(key), dict) else {}
        incoming = selected.get(key) if isinstance(selected.get(key), dict) else {}
        merged[key] = {**existing, **incoming}
    merged["provenance"] = [
        *(merged.get("provenance") if isinstance(merged.get("provenance"), list) else []),
        *(selected.get("provenance") if isinstance(selected.get("provenance"), list) else []),
    ]
    if "skipped" not in merged:
        merged["skipped"] = []
    return merged


def import_source_conflicts(conn, items: list[dict[str, Any]], *, limit: int = 50) -> list[dict[str, Any]]:
    if not table_exists(conn, "movies"):
        return []
    conflicts: list[dict[str, Any]] = []
    for index, item in enumerate(items[:limit], start=1):
        if not isinstance(item, dict):
            continue
        title = clean_text(item.get("title") or item.get("name"))
        year = clean_text(item.get("year") or item.get("releaseYear") or item.get("release_year"))
        barcode = clean_text(item.get("barcode"))
        match: dict[str, Any] | None = None
        with conn.cursor() as cur:
            if barcode:
                cur.execute(
                    "SELECT id, title, year, barcode FROM movies WHERE barcode=%s LIMIT 1",
                    (barcode,),
                )
                row = cur.fetchone()
                if row:
                    match = {
                        "id": str(row["id"]),
                        "title": row.get("title"),
                        "year": row.get("year"),
                        "barcode": row.get("barcode"),
                        "reason": "barcode",
                    }
            if not match and table_exists(conn, "movie_identifiers"):
                for provider, identifier in import_source_item_identifiers(item).items():
                    cur.execute(
                        """
                        SELECT m.id, m.title, m.year, m.barcode
                        FROM movie_identifiers mi
                        JOIN movies m ON m.id=mi.movie_id
                        WHERE mi.provider_id=%s AND mi.identifier_type='movie_id' AND mi.identifier=%s
                        LIMIT 1
                        """,
                        (provider, identifier),
                    )
                    row = cur.fetchone()
                    if row:
                        match = {
                            "id": str(row["id"]),
                            "title": row.get("title"),
                            "year": row.get("year"),
                            "barcode": row.get("barcode"),
                            "reason": provider,
                        }
                        break
            if not match and title and year:
                cur.execute(
                    """
                    SELECT id, title, year, barcode
                    FROM movies
                    WHERE lower(title)=lower(%s) AND year=%s
                    LIMIT 1
                    """,
                    (title, year),
                )
                row = cur.fetchone()
                if row:
                    match = {
                        "id": str(row["id"]),
                        "title": row.get("title"),
                        "year": row.get("year"),
                        "barcode": row.get("barcode"),
                        "reason": "title_year",
                    }
        conflicts.append(
            {
                "index": index,
                "title": title,
                "year": year,
                "barcode": barcode,
                "state": "existing" if match else "new",
                "match": match,
            }
        )
    return conflicts


def import_source_item_is_box_set(item: dict[str, Any]) -> bool:
    if not isinstance(item, dict):
        return False
    item_type = clean_text(item.get("itemType") or item.get("item_type") or item.get("entityType") or item.get("entity_type"))
    return item_type == "box_set" or item.get("isBoxSet") is True or item.get("is_box_set") is True


def import_source_item_container_specs(item: dict[str, Any]) -> list[dict[str, Any]]:
    if not isinstance(item, dict):
        return []
    specs: list[dict[str, Any]] = []
    is_box_set_item = import_source_item_is_box_set(item)
    field_specs = (
        ("collection", item.get("collectionTitle") or item.get("collection") or item.get("collection_title")),
        ("box_set", item.get("boxSetTitle") or item.get("boxSet") or item.get("box_set") or item.get("box_set_title")),
        ("vault", item.get("vaultTitle") or item.get("vault") or item.get("vault_title")),
    )
    for container_type, title in field_specs:
        clean_title = clean_text(title)
        if clean_title:
            spec: dict[str, Any] = {"containerType": container_type, "title": clean_title}
            if container_type == "box_set" and is_box_set_item:
                spec.update(
                    {
                        "barcode": clean_text(item.get("barcode")),
                        "format": import_source_item_format(item),
                        "memberCount": len(item.get("boxSetMembers") or []),
                        "membersAreExplicit": bool(item.get("boxSetMembers")),
                        "boxSetProposal": item.get("boxSetProposal") if isinstance(item.get("boxSetProposal"), dict) else {},
                    }
                )
            specs.append(spec)
    for raw in item.get("containers") or []:
        if not isinstance(raw, dict):
            continue
        container_type = clean_text(raw.get("containerType") or raw.get("type") or raw.get("container_type"))
        if container_type in {"boxset", "box-set"}:
            container_type = "box_set"
        if container_type not in {"collection", "box_set", "vault"}:
            continue
        title = clean_text(raw.get("title") or raw.get("name"))
        if title:
            specs.append(
                {
                    "containerType": container_type,
                    "title": title,
                    "barcode": clean_text(raw.get("barcode")),
                    "format": clean_text(raw.get("format")),
                    "memberCount": raw.get("memberCount") or raw.get("member_count"),
                    "membersAreExplicit": raw.get("membersAreExplicit") or raw.get("members_are_explicit"),
                    "boxSetProposal": raw.get("boxSetProposal") if isinstance(raw.get("boxSetProposal"), dict) else {},
                }
            )
    seen: set[tuple[str, str, str]] = set()
    unique: list[dict[str, Any]] = []
    for spec in specs:
        key = import_container_preview_key(
            spec["containerType"],
            spec["title"],
            barcode=spec.get("barcode"),
            media_format=spec.get("format"),
        )
        if key in seen:
            continue
        seen.add(key)
        unique.append(spec)
    return unique


def import_source_item_title(item: dict[str, Any]) -> str:
    return clean_text(item.get("title") or item.get("name") or item.get("originalTitle") or item.get("original_title"))


def import_source_item_year(item: dict[str, Any]) -> str:
    return clean_text(item.get("year") or item.get("releaseYear") or item.get("release_year"))


def import_source_item_format(item: dict[str, Any]) -> str:
    return clean_text(item.get("format") or item.get("mediaFormat") or item.get("media_format") or item.get("type"))


def import_source_item_provider(item: dict[str, Any], plugin_id: str) -> str:
    return clean_text(
        item.get("sourceProvider")
        or item.get("source_provider")
        or item.get("provider")
        or item.get("pluginId")
        or plugin_id
    ) or plugin_id


def import_source_item_confidence(item: dict[str, Any]) -> dict[str, Any]:
    score = 0
    evidence: list[str] = []
    title = import_source_item_title(item)
    year = import_source_item_year(item)
    barcode = clean_text(item.get("barcode"))
    identifiers = import_source_item_identifiers(item)
    if title:
        score += 22
        evidence.append("title")
    if year:
        score += 12
        evidence.append("year")
    if barcode:
        score += 24
        evidence.append("barcode")
    if identifiers:
        score += 22
        evidence.extend(sorted(identifiers.keys()))
    if import_source_item_format(item):
        score += 8
        evidence.append("format")
    if clean_text(item.get("sourceUrl") or item.get("source_url")):
        score += 6
        evidence.append("source")
    if clean_text(item.get("posterUrl") or item.get("poster_url") or item.get("poster")):
        score += 4
        evidence.append("poster")
    if clean_text(item.get("backdropUrl") or item.get("backdrop_url") or item.get("backdrop")):
        score += 2
        evidence.append("backdrop")
    if title and year and (barcode or identifiers):
        score = 100
        if "exact_identity" not in evidence:
            evidence.append("exact_identity")
    score = max(0, min(score, 100))
    label = "high" if score >= 74 else "medium" if score >= 48 else "low"
    return {"score": score, "label": label, "evidence": evidence}


def import_source_review_queue(
    *,
    plugin_id: str,
    items: list[dict[str, Any]],
    conflict_by_index: dict[int, dict[str, Any]],
    limit: int,
) -> list[dict[str, Any]]:
    queue: list[dict[str, Any]] = []
    for index, item in enumerate(items, start=1):
        title = import_source_item_title(item)
        match = (conflict_by_index.get(index) or {}).get("match")
        action = "skip" if not title else "update" if match else "create"
        confidence = import_source_item_confidence(item)
        match_state = "missing_title" if not title else "existing" if match else "new"
        if len(queue) < limit:
            queue.append(
                {
                    "index": index,
                    "reviewId": hashlib.sha256(
                        f"{plugin_id}:{index}:{title}:{clean_text(item.get('barcode'))}".encode("utf-8")
                    ).hexdigest()[:16],
                    "action": action,
                    "matchState": match_state,
                    "title": title,
                    "year": import_source_item_year(item),
                    "barcode": clean_text(item.get("barcode")),
                    "format": import_source_item_format(item),
                    "provider": import_source_item_provider(item, plugin_id),
                    "sourceFile": clean_text(item.get("sourceFile") or item.get("source_file")),
                    "sourceUrl": clean_text(item.get("sourceUrl") or item.get("source_url")),
                    "identifiers": import_source_item_identifiers(item),
                    "confidence": confidence,
                    "match": match,
                    "containers": import_source_item_container_specs(item),
                    "itemType": clean_text(item.get("itemType") or item.get("entityType")),
                    "boxSetProposal": item.get("boxSetProposal") if isinstance(item.get("boxSetProposal"), dict) else {},
                    "personal": item.get("personal") if isinstance(item.get("personal"), dict) else {},
                }
            )
    return queue


def import_source_provider_summary(review_queue: list[dict[str, Any]]) -> list[dict[str, Any]]:
    providers: dict[str, dict[str, Any]] = {}
    for row in review_queue:
        provider_id = clean_text(row.get("provider")) or "unknown"
        entry = providers.setdefault(
            provider_id,
            {
                "provider": provider_id,
                "total": 0,
                "create": 0,
                "update": 0,
                "skip": 0,
                "highConfidence": 0,
                "mediumConfidence": 0,
                "lowConfidence": 0,
                "confidenceTotal": 0,
            },
        )
        action = clean_text(row.get("action")) or "create"
        label = clean_text((row.get("confidence") or {}).get("label")) or "low"
        score = int((row.get("confidence") or {}).get("score") or 0)
        entry["total"] += 1
        entry[action] = int(entry.get(action) or 0) + 1
        entry[f"{label}Confidence"] = int(entry.get(f"{label}Confidence") or 0) + 1
        entry["confidenceTotal"] += score
    result = []
    for entry in providers.values():
        total = int(entry.get("total") or 0)
        entry["averageConfidence"] = round((int(entry.get("confidenceTotal") or 0) / total), 1) if total else 0
        entry.pop("confidenceTotal", None)
        result.append(entry)
    result.sort(key=lambda item: (-int(item.get("total") or 0), str(item.get("provider") or "")))
    return result


def import_source_title_release_risk(title: Any, confidence: dict[str, Any] | None = None) -> bool:
    text = clean_text(title)
    if not text:
        return False
    evidence = set((confidence or {}).get("evidence") or [])
    if "exact_identity" in evidence:
        return False
    return bool(
        re.search(
            r"\b(4k|uhd|ultra\s*hd|blu[- ]?ray|dvd|steelbook|limited edition|collector|france|germany|italy|spain|uk)\b",
            text,
            flags=re.IGNORECASE,
        )
    )


def import_source_review_summary(
    review_queue: list[dict[str, Any]],
    *,
    actions: list[dict[str, Any]],
    containers: list[dict[str, Any]],
    provider_summary: list[dict[str, Any]],
) -> dict[str, Any]:
    rows = review_queue or actions
    confidence = {"high": 0, "medium": 0, "low": 0}
    actions_count = {"create": 0, "update": 0, "skip": 0}
    missing_title = 0
    release_title_risks = 0
    metadata_suggestions = 0
    existing = 0
    new = 0
    for row in rows:
        action = clean_text(row.get("action")) or "create"
        if action in actions_count:
            actions_count[action] += 1
        label = clean_text((row.get("confidence") or {}).get("label")) or "low"
        if label in confidence:
            confidence[label] += 1
        if row.get("matchState") == "missing_title" or not clean_text(row.get("title")):
            missing_title += 1
        if row.get("matchState") == "existing" or row.get("match"):
            existing += 1
        else:
            new += 1
        if import_source_title_release_risk(row.get("title"), row.get("confidence") if isinstance(row.get("confidence"), dict) else {}):
            release_title_risks += 1
        suggestions = row.get("metadataSuggestions")
        if isinstance(suggestions, dict) and (suggestions.get("items") or suggestions.get("boxSetProposals") or suggestions.get("error")):
            metadata_suggestions += 1
    needs_review = missing_title + confidence["low"] + release_title_risks
    recommended_action = "review" if needs_review or metadata_suggestions else "ready"
    if not rows:
        recommended_action = "inspect"
    return {
        "total": len(rows),
        "actions": actions_count,
        "confidence": confidence,
        "needsReview": needs_review,
        "missingTitle": missing_title,
        "releaseTitleRisks": release_title_risks,
        "metadataSuggestionRows": metadata_suggestions,
        "existingMatches": existing,
        "newItems": new,
        "containers": len(containers),
        "boxSets": sum(1 for container in containers if container.get("containerType") == "box_set"),
        "providers": len(provider_summary),
        "recommendedAction": recommended_action,
    }


def import_source_item_needs_metadata_suggestion(item: dict[str, Any], confidence: dict[str, Any]) -> bool:
    if not import_source_item_title(item):
        return False
    if import_source_item_is_box_set(item):
        return True
    if clean_text(item.get("barcode")):
        return True
    if "exact_identity" in set(confidence.get("evidence") or []):
        return False
    score = int(confidence.get("score") or 0)
    return score < 74 or (not clean_text(item.get("barcode")) and not import_source_item_identifiers(item))


def import_source_metadata_suggestions(
    conn,
    *,
    item: dict[str, Any],
    actor: dict[str, Any],
    limit: int = 3,
) -> dict[str, Any] | None:
    title = import_source_item_title(item)
    if not title:
        return None
    barcode = clean_text(item.get("barcode"))
    query: dict[str, Any] = {
        "title": title,
        "year": import_source_item_year(item),
        "format": import_source_item_format(item),
        "detectBoxSets": bool(import_source_item_is_box_set(item) or barcode),
        "previewMode": True,
    }
    identifiers = import_source_item_identifiers(item)
    if barcode:
        query["barcode"] = barcode
    if identifiers.get("imdb"):
        query["imdbId"] = identifiers["imdb"]
    if identifiers.get("tmdb"):
        query["tmdbId"] = identifiers["tmdb"]
    try:
        metadata = lookup_metadata_sources(conn, query, actor)
    except Exception as exc:
        return {"query": query, "status": "error", "error": str(exc), "items": [], "sources": []}

    suggestions: list[dict[str, Any]] = []
    box_set_proposals: list[dict[str, Any]] = []
    seen: set[tuple[str, str, str]] = set()
    seen_box_sets: set[str] = set()

    def append_suggestion(provider: str, source_label: str, candidate: dict[str, Any]) -> None:
        candidate_title = clean_text(candidate.get("title") or candidate.get("name") or candidate.get("originalTitle"))
        candidate_year = clean_text(candidate.get("year") or candidate.get("releaseYear") or candidate.get("release_year"))
        candidate_identifiers = {
            key: value
            for key, value in {
                "tmdb": clean_text(candidate.get("tmdbId") or candidate.get("tmdb_id")),
                "imdb": clean_text(candidate.get("imdbId") or candidate.get("imdb_id")),
            }.items()
            if value
        }
        if not candidate_title:
            return
        identifier_key = "|".join(f"{key}:{value}" for key, value in sorted(candidate_identifiers.items()))
        key = (candidate_title.casefold(), candidate_year, identifier_key)
        if key in seen:
            return
        seen.add(key)
        suggestions.append(
            {
                "provider": provider,
                "sourceLabel": source_label or provider,
                "title": candidate_title,
                "year": candidate_year,
                "posterUrl": clean_text(candidate.get("posterUrl") or candidate.get("poster_url") or candidate.get("poster")),
                "overview": clean_text(candidate.get("overview") or candidate.get("plot"))[:500],
                "identifiers": candidate_identifiers,
            }
        )

    for result_item in metadata.get("results") or []:
        if not isinstance(result_item, dict):
            continue
        provider = clean_text(result_item.get("pluginId")) or clean_text(result_item.get("provider")) or "metadata"
        source_label = clean_text(result_item.get("sourceLabel")) or provider
        raw = result_item.get("raw") if isinstance(result_item.get("raw"), dict) else {}
        proposal_candidates = []
        for value in (
            result_item.get("boxSetProposal"),
            result_item.get("box_set_proposal"),
            raw.get("boxSetProposal"),
            raw.get("box_set_proposal"),
        ):
            if isinstance(value, dict):
                proposal_candidates.append(value)
        for key in ("boxSetProposals", "box_set_proposals"):
            for value in result_item.get(key) or []:
                if isinstance(value, dict):
                    proposal_candidates.append(value)
            for value in raw.get(key) or []:
                if isinstance(value, dict):
                    proposal_candidates.append(value)
        for proposal in proposal_candidates:
            if not box_set_proposal_member_list(proposal):
                continue
            key = json.dumps(
                {
                    "provider": provider,
                    "title": clean_text(proposal.get("title") or proposal.get("name")).casefold(),
                    "barcode": clean_text(proposal.get("barcode")),
                    "members": len(box_set_proposal_member_list(proposal)),
                },
                sort_keys=True,
            )
            if key in seen_box_sets:
                continue
            seen_box_sets.add(key)
            box_set_proposals.append(
                {
                    **proposal,
                    "provider": clean_text(proposal.get("provider") or provider),
                    "sourceLabel": clean_text(proposal.get("sourceLabel") or source_label),
                    "audit": box_set_proposal_audit_summary({**proposal, "provider": clean_text(proposal.get("provider") or provider)}),
                }
            )
        for candidate in result_item.get("candidates") or []:
            if isinstance(candidate, dict):
                append_suggestion(provider, source_label, candidate)
            if len(suggestions) >= limit:
                break
        if len(suggestions) >= limit:
            break
        movie_updates = result_item.get("movieUpdates") or {}
        if isinstance(movie_updates, dict) and clean_text(movie_updates.get("title")):
            media_updates = result_item.get("mediaUpdates") if isinstance(result_item.get("mediaUpdates"), dict) else {}
            poster = media_updates.get("poster") if isinstance(media_updates.get("poster"), dict) else {}
            result_identifiers = result_item.get("identifiers") if isinstance(result_item.get("identifiers"), dict) else {}
            append_suggestion(
                provider,
                source_label,
                {
                    "title": movie_updates.get("title"),
                    "year": movie_updates.get("year"),
                    "posterUrl": poster.get("sourceUrl"),
                    "tmdbId": result_identifiers.get("tmdb"),
                    "imdbId": result_identifiers.get("imdb"),
                },
            )
    return {
        "query": query,
        "status": "ok",
        "items": suggestions[:limit],
        "boxSetProposals": sorted(box_set_proposals, key=box_set_proposal_sort_key)[:limit],
        "sources": metadata.get("sourceSummary") or [],
    }


def import_source_detected_box_set_proposal(suggestions: dict[str, Any] | None) -> dict[str, Any]:
    if not isinstance(suggestions, dict):
        return {}
    proposals = [
        proposal
        for proposal in (suggestions.get("boxSetProposals") or [])
        if isinstance(proposal, dict) and len(box_set_proposal_member_list(proposal)) >= 2
    ]
    if not proposals:
        return {}
    return sorted(proposals, key=box_set_proposal_sort_key)[0]


def import_source_match_title_key(value: Any) -> str:
    text = (clean_text(value) or "").casefold()
    text = re.sub(
        r"\b(4k|uhd|ultra\s*hd|blu[- ]?ray|dvd|hd\s*dvd|laserdisc|steelbook|limited|collector|edition|france|germany|italy|spain|uk|usa)\b",
        " ",
        text,
    )
    text = re.sub(r"[^a-z0-9]+", " ", text)
    return re.sub(r"\s+", " ", text).strip()


def import_source_match_candidate_score(item: dict[str, Any], candidate: dict[str, Any]) -> dict[str, Any]:
    item_title = import_source_match_title_key(import_source_item_title(item))
    candidate_title = import_source_match_title_key(
        candidate.get("title") or candidate.get("name") or candidate.get("originalTitle")
    )
    evidence: list[str] = []
    score = 0
    if item_title and candidate_title:
        ratio = SequenceMatcher(None, item_title, candidate_title).ratio()
        score += int(round(ratio * 58))
        if item_title == candidate_title:
            score += 24
            evidence.append("exact_title")
        elif item_title in candidate_title or candidate_title in item_title:
            score += 14
            evidence.append("contained_title")
        elif ratio >= 0.82:
            evidence.append("similar_title")
    item_year = clean_text(import_source_item_year(item))
    candidate_year = clean_text(candidate.get("year") or candidate.get("releaseYear") or candidate.get("release_year"))
    if item_year and candidate_year:
        if item_year == candidate_year:
            score += 18
            evidence.append("same_year")
        else:
            try:
                if abs(int(item_year) - int(candidate_year)) <= 1:
                    score += 8
                    evidence.append("near_year")
            except ValueError:
                pass
    identifiers = candidate.get("identifiers") if isinstance(candidate.get("identifiers"), dict) else {}
    item_identifiers = import_source_item_identifiers(item)
    for key in ("tmdb", "imdb"):
        if clean_text(item_identifiers.get(key)) and clean_text(identifiers.get(key)) == clean_text(item_identifiers.get(key)):
            score += 30
            evidence.append(f"{key}_id")
    provider = clean_text(candidate.get("provider"))
    if provider in {"tmdb", "movievault", "bluray_com"}:
        score += 3
    score = max(0, min(100, score))
    if score >= 88:
        label = "high"
    elif score >= 72:
        label = "medium"
    else:
        label = "low"
    return {"score": score, "label": label, "evidence": evidence}


def import_source_recommended_match(item: dict[str, Any], suggestions: dict[str, Any] | None) -> dict[str, Any] | None:
    if not isinstance(suggestions, dict):
        return None
    candidates = [candidate for candidate in suggestions.get("items") or [] if isinstance(candidate, dict)]
    best: dict[str, Any] | None = None
    for candidate in candidates:
        resolution = import_source_match_candidate_score(item, candidate)
        if not best or int(resolution["score"]) > int(best["resolution"]["score"]):
            best = {"candidate": candidate, "resolution": resolution}
    if not best or int(best["resolution"]["score"]) < 72:
        return None
    return {
        **best["candidate"],
        "recommended": True,
        "resolution": best["resolution"],
    }


def import_source_box_set_reviews(container_preview: list[dict[str, Any]], review_queue: list[dict[str, Any]]) -> list[dict[str, Any]]:
    rows_by_index = {int(row["index"]): row for row in review_queue if row.get("index")}
    reviews: list[dict[str, Any]] = []
    seen_reviews: set[tuple[str, str]] = set()
    for container in container_preview:
        container_type = clean_text(container.get("containerType") or container.get("type"))
        if container_type != "box_set":
            continue
        proposal = container.get("boxSetProposal") if isinstance(container.get("boxSetProposal"), dict) else {}
        proposal_members = box_set_proposal_member_list(proposal)
        if proposal_members:
            seen_reviews.add((
                clean_text(proposal.get("barcode") or container.get("barcode")),
                clean_text(container.get("title") or proposal.get("title") or proposal.get("name")).casefold(),
            ))
            reviews.append(
                {
                    "containerType": container_type,
                    "title": container.get("title") or proposal.get("title"),
                    "barcode": clean_text(proposal.get("barcode") or container.get("barcode")),
                    "format": clean_text(proposal.get("format") or container.get("format")),
                    "memberCount": len(proposal_members),
                    "boxSetProposal": proposal,
                    "boxSetEvidence": box_set_proposal_evidence(proposal),
                    "members": [
                        {
                            "index": 0,
                            "title": clean_text(member.get("title") or member.get("name")),
                            "year": clean_text(member.get("year") or member.get("releaseYear") or member.get("release_year")),
                            "format": clean_text(member.get("format") or proposal.get("format") or container.get("format")),
                            "barcode": clean_text(member.get("barcode")),
                            "provider": clean_text(member.get("provider") or member.get("sourceProvider") or proposal.get("provider")),
                            "confidence": {"label": clean_text(member.get("memberConfidence") or proposal.get("memberConfidence")) or "needs_member_confirmation"},
                            "matchState": "proposal_member",
                            "action": "review",
                        }
                        for member in proposal_members
                    ],
                }
            )
            continue
        members = []
        for raw_member in container.get("members") or []:
            try:
                index = int(raw_member.get("index"))
            except (TypeError, ValueError, AttributeError):
                index = 0
            row = rows_by_index.get(index, {})
            members.append(
                {
                    "index": index,
                    "title": row.get("title") or (raw_member.get("title") if isinstance(raw_member, dict) else ""),
                    "year": row.get("year") or (raw_member.get("year") if isinstance(raw_member, dict) else ""),
                    "format": row.get("format") or (raw_member.get("format") if isinstance(raw_member, dict) else ""),
                    "barcode": row.get("barcode") or (raw_member.get("barcode") if isinstance(raw_member, dict) else ""),
                    "provider": row.get("provider"),
                    "confidence": row.get("confidence") or {},
                    "matchState": row.get("matchState"),
                    "action": row.get("action"),
                }
            )
        reviews.append(
            {
                "containerType": container_type,
                "title": container.get("title"),
                "memberCount": container.get("memberCount") or len(members),
                "members": members,
            }
        )
        seen_reviews.add((clean_text(container.get("barcode")), clean_text(container.get("title")).casefold()))
    for row in review_queue:
        proposal = row.get("detectedBoxSetProposal") if isinstance(row.get("detectedBoxSetProposal"), dict) else {}
        proposal_members = box_set_proposal_member_list(proposal)
        if not proposal_members:
            continue
        key = (
            clean_text(proposal.get("barcode") or row.get("barcode")),
            clean_text(proposal.get("title") or proposal.get("name") or row.get("title")).casefold(),
        )
        if key in seen_reviews:
            continue
        seen_reviews.add(key)
        reviews.append(
            {
                "containerType": "box_set",
                "title": clean_text(proposal.get("title") or proposal.get("name") or row.get("title")),
                "barcode": clean_text(proposal.get("barcode") or row.get("barcode")),
                "format": clean_text(proposal.get("format") or row.get("format")),
                "memberCount": len(proposal_members),
                "boxSetProposal": proposal,
                "boxSetEvidence": box_set_proposal_evidence(proposal),
                "members": [
                    {
                        "index": row.get("index"),
                        "title": clean_text(member.get("title") or member.get("name")),
                        "year": clean_text(member.get("year") or member.get("releaseYear") or member.get("release_year")),
                        "format": clean_text(member.get("format") or proposal.get("format") or row.get("format")),
                        "barcode": clean_text(member.get("barcode")),
                        "provider": clean_text(member.get("provider") or member.get("sourceProvider") or proposal.get("provider")),
                        "confidence": {"label": clean_text(member.get("memberConfidence") or proposal.get("memberConfidence")) or "needs_member_confirmation"},
                        "matchState": "metadata_box_set_candidate",
                        "action": "review",
                    }
                    for member in proposal_members
                ],
            }
        )
    reviews.sort(key=lambda item: str(item.get("title") or "").casefold())
    return reviews


def import_source_action_preview(
    conn,
    *,
    plugin_id: str,
    source: dict[str, Any],
    items: list[dict[str, Any]],
    limit: int = 200,
    actor: dict[str, Any] | None = None,
    include_metadata_suggestions: bool = True,
    metadata_suggestion_limit: int = 200,
) -> dict[str, Any]:
    conflicts = import_source_conflicts(conn, items, limit=min(len(items), 5000))
    conflict_by_index = {item["index"]: item for item in conflicts}
    review_queue = import_source_review_queue(
        plugin_id=plugin_id,
        items=items,
        conflict_by_index=conflict_by_index,
        limit=limit,
    )
    actions: list[dict[str, Any]] = []
    counts = {
        "total": len(items),
        "create": 0,
        "update": 0,
        "skip": 0,
        "linkCollection": 0,
        "linkContainers": 0,
    }
    containers: dict[tuple[str, str, str], dict[str, Any]] = {}
    suggestion_count = 0
    source_title = clean_text(source.get("sourceKind") or plugin_id).replace("_", " ")
    import_collection = {
        "containerType": "collection",
        "title": f"{source_title} import",
        "reason": "source_import_collection",
        "members": len(items),
    }
    for index, item in enumerate(items, start=1):
        title = import_source_item_title(item)
        if not title:
            counts["skip"] += 1
            action = "skip"
        else:
            match = (conflict_by_index.get(index) or {}).get("match")
            action = "update" if match else "create"
            counts[action] += 1
        specs = import_source_item_container_specs(item)
        counts["linkCollection"] += sum(1 for spec in specs if spec.get("containerType") == "collection")
        counts["linkContainers"] += len(specs)
        for spec in specs:
            key = import_container_preview_key(
                spec["containerType"],
                spec["title"],
                barcode=spec.get("barcode"),
                media_format=spec.get("format"),
            )
            entry = containers.setdefault(
                key,
                {
                    "containerType": spec["containerType"],
                    "title": spec["title"],
                    "members": [],
                },
            )
            for optional_key in ("barcode", "format", "memberCount", "membersAreExplicit", "boxSetProposal"):
                if spec.get(optional_key) not in (None, "", [], {}):
                    entry[optional_key] = spec.get(optional_key)
            entry["members"].append(
                {
                    "index": index,
                    "title": title,
                    "year": import_source_item_year(item),
                    "format": import_source_item_format(item),
                    "barcode": clean_text(item.get("barcode")),
                    "provider": import_source_item_provider(item, plugin_id),
                    "confidence": import_source_item_confidence(item),
                }
            )
        confidence = import_source_item_confidence(item)
        metadata_suggestions = None
        if (
            include_metadata_suggestions
            and actor
            and suggestion_count < metadata_suggestion_limit
            and import_source_item_needs_metadata_suggestion(item, confidence)
        ):
            metadata_suggestions = import_source_metadata_suggestions(conn, item=item, actor=actor)
            suggestion_count += 1
        recommended_match = import_source_recommended_match(item, metadata_suggestions)
        detected_box_set = import_source_detected_box_set_proposal(metadata_suggestions)
        detected_box_set_audit = box_set_proposal_audit_summary(detected_box_set) if detected_box_set else {}
        detected_box_set_auto_importable = box_set_proposal_auto_importable(detected_box_set) if detected_box_set else False
        if detected_box_set:
            box_title = clean_text(detected_box_set.get("title") or detected_box_set.get("name") or title)
            if box_title:
                key = import_container_preview_key(
                    "box_set",
                    box_title,
                    barcode=detected_box_set.get("barcode") or item.get("barcode"),
                    media_format=detected_box_set.get("format") or import_source_item_format(item),
                )
                entry = containers.setdefault(
                    key,
                    {
                        "containerType": "box_set",
                        "title": box_title,
                        "members": [],
                    },
                )
                entry["barcode"] = clean_text(detected_box_set.get("barcode") or item.get("barcode"))
                entry["format"] = clean_text(detected_box_set.get("format") or import_source_item_format(item))
                entry["boxSetProposal"] = detected_box_set
                entry["memberCount"] = len(box_set_proposal_member_list(detected_box_set))
                entry["membersAreExplicit"] = box_set_proposal_has_explicit_members(detected_box_set)
        if index <= len(review_queue):
            review_queue[index - 1]["metadataSuggestions"] = metadata_suggestions
            review_queue[index - 1]["recommendedMatch"] = recommended_match
            review_queue[index - 1]["matchResolution"] = (recommended_match or {}).get("resolution") or {
                "score": 0,
                "label": "none",
                "evidence": [],
            }
            if detected_box_set:
                review_queue[index - 1]["boxSetCandidate"] = True
                review_queue[index - 1]["detectedBoxSetProposal"] = detected_box_set
                review_queue[index - 1]["detectedBoxSetAudit"] = detected_box_set_audit
                review_queue[index - 1]["detectedBoxSetAutoImportable"] = detected_box_set_auto_importable
                review_queue[index - 1]["matchState"] = "box_set_candidate"
        if len(actions) < limit:
            actions.append(
                {
                    "index": index,
                    "action": action,
                    "title": title,
                    "year": import_source_item_year(item),
                    "barcode": clean_text(item.get("barcode")),
                    "format": import_source_item_format(item),
                    "provider": import_source_item_provider(item, plugin_id),
                    "confidence": confidence,
                    "metadataSuggestions": metadata_suggestions,
                    "recommendedMatch": recommended_match,
                    "matchResolution": (recommended_match or {}).get("resolution"),
                    "boxSetCandidate": bool(detected_box_set),
                    "detectedBoxSetProposal": detected_box_set,
                    "detectedBoxSetAudit": detected_box_set_audit,
                    "detectedBoxSetAutoImportable": detected_box_set_auto_importable,
                    "match": (conflict_by_index.get(index) or {}).get("match"),
                    "containers": specs,
                }
            )
    container_preview = [
        {**value, "memberCount": len(value["members"]), "members": value["members"][:8]}
        for value in containers.values()
    ]
    container_preview.sort(key=lambda item: (item["containerType"], item["title"].casefold()))
    provider_summary = import_source_provider_summary(review_queue)
    box_set_reviews = import_source_box_set_reviews(container_preview, review_queue)
    review_summary = import_source_review_summary(
        review_queue,
        actions=actions,
        containers=container_preview,
        provider_summary=provider_summary,
    )
    return {
        "counts": counts,
        "actions": actions,
        "reviewQueue": review_queue,
        "providerSummary": provider_summary,
        "reviewSummary": review_summary,
        "boxSetReviews": box_set_reviews,
        "containers": container_preview,
        "importCollection": import_collection,
        "truncated": len(items) > limit,
    }


def inspect_import_source_selection(
    conn,
    *,
    plugin_id: str,
    payload: dict[str, Any],
    actor: dict[str, Any],
    include_metadata_suggestions: bool = True,
) -> dict[str, Any]:
    plugin = import_source_plugin_by_id(conn, plugin_id)
    if not plugin:
        raise NextApiError(f"Import source plugin is not available: {plugin_id}", 409)
    source, execution = inspect_import_source_plugin(conn, plugin, payload, actor)
    if execution.get("status") != "ok":
        raise NextApiError(
            f"Import source inspection failed: {execution.get('error') or execution.get('state')}",
            502,
        )
    sample = source.get("sample") or []
    conflicts = import_source_conflicts(conn, sample) if isinstance(sample, list) else []
    plan: dict[str, Any] | None = None
    action_preview = None
    context = None
    if source.get("readable") and (
        "plan_import" in plugin_runtime_entrypoints(plugin)
        or "import_source" in plugin_runtime_entrypoints(plugin)
    ):
        config = plugin_config_from_db(conn, plugin_id)
        context = plugin_execution_context(conn, plugin, config, actor)
    if source.get("readable") and "plan_import" in plugin_runtime_entrypoints(plugin) and context:
        plan_execution = run_plugin_entrypoint(plugin_id, "plan_import", payload, context)
        if plan_execution.get("status") == "ok" and isinstance(plan_execution.get("result"), dict):
            plan = plan_execution["result"]
        else:
            plan = {
                "status": plan_execution.get("state") or "error",
                "canStart": False,
                "error": plan_execution.get("error"),
            }
    if source.get("readable") and "import_source" in plugin_runtime_entrypoints(plugin) and context:
        preview_payload = dict(payload)
        if source.get("sourcePath") and not preview_payload.get("sourcePath"):
            preview_payload["sourcePath"] = source.get("sourcePath")
        if source.get("sourceDatabaseHash"):
            preview_payload["sourceDatabaseHash"] = source.get("sourceDatabaseHash")
        import_execution = run_plugin_entrypoint(plugin_id, "import_source", preview_payload, context)
        result = import_execution.get("result") if import_execution.get("status") == "ok" else {}
        items = result.get("items") if isinstance(result, dict) else []
        if isinstance(items, list):
            action_preview = import_source_action_preview(
                conn,
                plugin_id=plugin_id,
                source=source,
                items=[item for item in items if isinstance(item, dict)],
                actor=actor,
                include_metadata_suggestions=include_metadata_suggestions,
            )
    return {
        "source": source,
        "execution": {
            "status": execution.get("status"),
            "state": execution.get("state"),
            "error": execution.get("error"),
        },
        "conflicts": conflicts,
        "actionPreview": action_preview,
        "plan": plan,
    }


def import_source_readiness_probe(conn) -> dict[str, Any]:
    probe = empty_import_source_probe()
    warnings: list[str] = []
    selected: dict[str, Any] | None = None
    import_sources: list[dict[str, Any]] = []
    plugins = import_source_plugins(conn)
    if not plugins:
        warnings.append("No enabled import source plugin is available.")
        probe["warnings"] = warnings
        return probe

    for plugin in plugins:
        source, execution = inspect_import_source_plugin(conn, plugin)
        import_sources.append(import_source_summary(source, execution))
        for warning in source.get("warnings") or []:
            warnings.append(f"{plugin.get('name') or plugin.get('id')}: {warning}")
        if execution.get("status") != "ok":
            warnings.append(
                f"{plugin.get('name') or plugin.get('id')}: {execution.get('error') or execution.get('state')}"
            )
        if selected is None and source.get("found") and source.get("readable"):
            selected = source
        elif selected is None and source.get("found"):
            selected = source
        elif selected is None:
            selected = source

    probe["source"] = selected or probe["source"]
    probe["warnings"] = warnings
    probe["importSources"] = import_sources
    return probe


def import_source_plugin_by_id(conn, plugin_id: str | None) -> dict[str, Any] | None:
    if not plugin_id:
        return None
    for plugin in import_source_plugins(conn):
        if plugin.get("id") == plugin_id:
            return plugin
    return None


def normalize_import_column_mapping(value: Any) -> dict[str, str]:
    if not isinstance(value, dict):
        return {}
    mapping: dict[str, str] = {}
    allowed = {
        "externalId",
        "title",
        "originalTitle",
        "year",
        "releaseDate",
        "barcode",
        "format",
        "edition",
        "country",
        "language",
        "overview",
        "runtime",
        "rating",
        "director",
        "actor",
        "genre",
        "imdbId",
        "tmdbId",
        "poster",
        "backdrop",
        "sourceUrl",
        "collectionTitle",
        "boxSetTitle",
        "vaultTitle",
        "watchedAt",
        "watchlisted",
        "tags",
    }
    for key, raw in value.items():
        field = clean_text(key)
        column = clean_text(raw)
        if field in allowed and column:
            mapping[field] = column
    return mapping


def normalize_import_review(value: Any) -> dict[str, Any]:
    if not isinstance(value, dict):
        return {}
    allowed_match_fields = {
        "provider",
        "sourceLabel",
        "title",
        "year",
        "posterUrl",
        "backdropUrl",
        "overview",
        "format",
    }
    allowed_manual_fields = {"title", "year", "tmdbId", "imdbId", "posterUrl", "backdropUrl", "overview", "format"}

    def normalize_match(raw_value: Any) -> dict[str, Any] | None:
        if not isinstance(raw_value, dict):
            return None
        match = {
            key: clean_text(raw_value.get(key))
            for key in allowed_match_fields
            if clean_text(raw_value.get(key))
        }
        identifiers = raw_value.get("identifiers")
        if isinstance(identifiers, dict):
            clean_ids = {
                clean_text(key).lower(): clean_text(item)
                for key, item in identifiers.items()
                if clean_text(key) and clean_text(item)
            }
            if clean_ids:
                match["identifiers"] = clean_ids
        for provider_key in ("tmdbId", "tmdb_id", "imdbId", "imdb_id"):
            value = clean_text(raw_value.get(provider_key))
            if value:
                match[provider_key] = value
        return match or None

    def normalize_manual(raw_value: Any) -> dict[str, Any] | None:
        if not isinstance(raw_value, dict):
            return None
        manual = {
            key: clean_text(raw_value.get(key))
            for key in allowed_manual_fields
            if clean_text(raw_value.get(key))
        }
        return manual or None

    def normalize_box_set_proposal(raw_value: Any, *, fallback_format: str = "") -> dict[str, Any] | None:
        if not isinstance(raw_value, dict):
            return None
        allowed_proposal_fields = {
            "title",
            "name",
            "provider",
            "source",
            "sourceLabel",
            "sourceRef",
            "barcode",
            "format",
            "year",
            "year_range",
            "description",
            "movievault_id",
            "proposalKey",
            "_proposalKey",
            "memberSource",
            "member_source",
            "memberConfidence",
            "member_confidence",
            "memberCount",
            "member_count",
            "membersAreExplicit",
            "members_are_explicit",
            "detectedWithoutMembers",
            "detected_without_members",
            "poster",
            "posterUrl",
            "poster_url",
            "backdrop",
            "backdropUrl",
            "backdrop_url",
            "backdropUrls",
            "backdrop_urls",
        }
        proposal = {
            key: raw_value.get(key)
            for key in allowed_proposal_fields
            if raw_value.get(key) not in (None, "", [], {})
        }
        for key in ("boxSetEvidence", "box_set_evidence", "metadata_plugin_fallbacks"):
            value = raw_value.get(key)
            if value not in (None, "", [], {}) and isinstance(value, (dict, list)):
                proposal[key] = value
        title = clean_text(proposal.get("title") or proposal.get("name"))
        if title:
            proposal["title"] = title
            proposal["name"] = title
        proposal_format = clean_text(proposal.get("format") or fallback_format)
        if proposal_format:
            proposal["format"] = proposal_format
        members = []
        for index, raw_member in enumerate(box_set_proposal_member_list(raw_value)[:50], start=1):
            member_title = clean_text(raw_member.get("title") or raw_member.get("name") or raw_member.get("originalTitle") or raw_member.get("original_title"))
            if not member_title:
                continue
            member = dict(raw_member)
            member["title"] = member_title
            member["year"] = clean_text(member.get("year") or member.get("releaseYear") or member.get("release_year"))
            member_format = clean_text(member.get("format"))
            if proposal_format and (not member_format or not physical_media_formats_compatible(member_format, proposal_format)):
                member["format"] = proposal_format
            else:
                member["format"] = member_format
            member["sortOrder"] = int(member.get("sortOrder") or member.get("sort_order") or index)
            members.append({key: value for key, value in member.items() if value not in (None, "", [], {})})
        if members:
            proposal["members"] = members
            proposal["movies"] = members
            proposal["boxSetMovies"] = members
            proposal["box_set_movies"] = members
            proposal["memberCount"] = len(members)
            proposal["member_count"] = len(members)
            proposal["membersAreExplicit"] = True
            proposal["members_are_explicit"] = True
        return proposal or None

    decisions: list[dict[str, Any]] = []
    for raw in value.get("decisions") or []:
        if not isinstance(raw, dict):
            continue
        try:
            index = int(raw.get("index"))
        except (TypeError, ValueError):
            index = None
        action = clean_text(raw.get("action"))
        if not index or index < 1 or action not in {"import", "update", "create", "skip"}:
            continue
        decision = {
            "index": index,
            "action": action,
            "note": clean_text(raw.get("note")),
        }
        metadata_match = normalize_match(raw.get("metadataMatch"))
        manual_override = normalize_manual(raw.get("manualOverride"))
        if metadata_match:
            decision["metadataMatch"] = metadata_match
        if manual_override:
            decision["manualOverride"] = manual_override
        if action != "skip":
            fallback_format = clean_text(
                (manual_override or {}).get("format")
                or (metadata_match or {}).get("format")
            )
            box_set_proposal = normalize_box_set_proposal(
                raw.get("boxSetProposal") or raw.get("box_set_proposal"),
                fallback_format=fallback_format,
            )
            if box_set_proposal:
                decision["boxSetProposal"] = box_set_proposal
                if "boxSetReviewAccepted" in raw or "box_set_review_accepted" in raw:
                    decision["boxSetReviewAccepted"] = parse_bool_value(
                        raw.get("boxSetReviewAccepted", raw.get("box_set_review_accepted")),
                        default=False,
                    )
        decisions.append(decision)
    return {"decisions": decisions} if decisions else {}


def import_source_payload_for_path(
    plugin_id: str,
    source_path: str,
    column_mapping: dict[str, str] | None = None,
) -> dict[str, Any]:
    column_mapping = column_mapping or {}
    if not source_path:
        return {"columnMapping": column_mapping} if column_mapping else {}
    if plugin_id == "discvault_legacy_import":
        path = Path(source_path)
        if path.suffix.lower() in {".db", ".sqlite", ".sqlite3"}:
            return {"sqliteDb": source_path, "dataDir": str(path.parent)}
        return {"dataDir": source_path}
    payload = {"sourcePath": source_path}
    if column_mapping:
        payload["columnMapping"] = column_mapping
    return payload


def import_upload_root() -> Path:
    return Path(legacy_data_dir()) / "import" / "uploads"


def safe_import_upload_filename(filename: str | None) -> str:
    name = Path(filename or "collection-import").name.strip()
    name = re.sub(r"[^A-Za-z0-9._ -]+", "_", name).strip(" ._")
    return name or f"collection-import-{uuid.uuid4().hex}"


def store_import_upload(destination_dir: Path) -> tuple[Path, str, int]:
    uploaded = request.files.get("file") or request.files.get("import") or request.files.get("source")
    if not uploaded or not uploaded.filename:
        raise NextApiError("Import file is required", 400)
    suffix = Path(uploaded.filename).suffix.lower()
    if suffix not in IMPORT_UPLOAD_EXTENSIONS:
        allowed = ", ".join(sorted(IMPORT_UPLOAD_EXTENSIONS))
        raise NextApiError(f"Unsupported import file type. Supported: {allowed}", 400)
    destination_dir.mkdir(parents=True, exist_ok=True)
    filename = safe_import_upload_filename(uploaded.filename)
    target = destination_dir / filename
    if target.exists():
        target = destination_dir / f"{target.stem}-{uuid.uuid4().hex[:8]}{target.suffix}"
        filename = target.name
    uploaded.save(target)
    size_bytes = target.stat().st_size
    if size_bytes > MAX_IMPORT_UPLOAD_BYTES:
        try:
            target.unlink()
        except OSError:
            pass
        raise NextApiError("Import file is too large", 413)
    return target, filename, size_bytes


def extract_import_upload_archive(archive_path: Path, destination_dir: Path) -> Path:
    extract_dir = destination_dir / "extracted"
    extract_dir.mkdir(parents=True, exist_ok=True)
    total_size = 0
    try:
        with zipfile.ZipFile(archive_path) as archive:
            for member in archive.infolist():
                if member.is_dir():
                    continue
                member_path = Path(member.filename)
                if member_path.is_absolute() or ".." in member_path.parts:
                    raise NextApiError("Import archive contains an unsafe path", 400)
                suffix = member_path.suffix.lower()
                if suffix not in IMPORT_ARCHIVE_EXTENSIONS:
                    continue
                total_size += int(member.file_size or 0)
                if total_size > MAX_IMPORT_ARCHIVE_BYTES:
                    raise NextApiError("Import archive is too large after extraction", 413)
                target = extract_dir / member_path
                target.parent.mkdir(parents=True, exist_ok=True)
                with archive.open(member) as source, target.open("wb") as output:
                    shutil.copyfileobj(source, output)
    except zipfile.BadZipFile as exc:
        raise NextApiError("Import archive is not a valid ZIP file", 400) from exc
    if not any(path.is_file() for path in extract_dir.rglob("*")):
        raise NextApiError("Import archive does not contain a supported import file", 400)
    return extract_dir


def import_upload_candidates(
    conn,
    *,
    source_path: Path,
    plugins: list[dict[str, Any]],
    actor: dict[str, Any],
) -> tuple[list[dict[str, Any]], dict[str, Any] | None]:
    candidates: list[dict[str, Any]] = []
    best_preview: dict[str, Any] | None = None
    best_plugin_id = ""
    best_payload: dict[str, Any] | None = None
    def safe_int(value: Any) -> int:
        try:
            return int(value or 0)
        except (TypeError, ValueError):
            return 0

    def score(preview: dict[str, Any]) -> int:
        source = preview.get("source") or {}
        recognition = source.get("recognition") if isinstance(source.get("recognition"), dict) else {}
        recognition_score = safe_int(recognition.get("score"))
        counts = ((preview.get("actionPreview") or {}).get("counts") or {})
        if counts.get("total") is not None:
            return recognition_score * 10000 + safe_int(counts.get("total"))
        source_counts = source.get("sourceCounts") or {}
        total = 0
        for value in source_counts.values():
            try:
                total += int(value or 0)
            except (TypeError, ValueError):
                continue
        return recognition_score * 10000 + total

    for plugin in plugins:
        plugin_id = str(plugin.get("id") or "")
        if not plugin_id:
            continue
        payload = import_source_payload_for_path(plugin_id, str(source_path))
        try:
            source, execution = inspect_import_source_plugin(conn, plugin, payload, actor)
            summary = import_source_summary(source, execution)
            candidates.append(summary)
            if not source.get("found") or not source.get("readable"):
                continue
            preview = inspect_import_source_selection(
                conn,
                plugin_id=plugin_id,
                payload=payload,
                actor=actor,
                include_metadata_suggestions=False,
            )
            if best_preview is None:
                best_preview = preview
                best_plugin_id = plugin_id
                best_payload = payload
                continue
            if score(preview) > score(best_preview):
                best_preview = preview
                best_plugin_id = plugin_id
                best_payload = payload
        except NextApiError as exc:
            candidates.append(
                {
                    "pluginId": plugin_id,
                    "pluginName": plugin.get("name") or plugin_id,
                    "status": "error",
                    "found": False,
                    "readable": False,
                    "runtimeStatus": "error",
                    "runtimeState": "error",
                    "sourcePath": str(source_path),
                    "sourceCounts": {},
                    "warnings": [str(exc)],
                }
            )
        except Exception as exc:
            candidates.append(
                {
                    "pluginId": plugin_id,
                    "pluginName": plugin.get("name") or plugin_id,
                    "status": "error",
                    "found": False,
                    "readable": False,
                    "runtimeStatus": "error",
                    "runtimeState": "error",
                    "sourcePath": str(source_path),
                    "sourceCounts": {},
                    "warnings": [str(exc)],
                }
            )
    if best_plugin_id and best_payload:
        try:
            best_preview = inspect_import_source_selection(
                conn,
                plugin_id=best_plugin_id,
                payload=best_payload,
                actor=actor,
                include_metadata_suggestions=True,
            )
        except Exception:
            pass
    candidates.sort(
        key=lambda item: (
            safe_int(((item.get("recognition") or {}).get("score") or 0) if isinstance(item.get("recognition"), dict) else 0),
            safe_int(((item.get("sourceCounts") or {}).get("movies") or 0) if isinstance(item.get("sourceCounts"), dict) else 0),
        ),
        reverse=True,
    )
    return candidates, best_preview


def plan_migration_import_job(
    conn,
    *,
    plugin_id: str | None,
    source: dict[str, Any],
    options: dict[str, Any],
    actor: dict[str, Any],
) -> tuple[str, dict[str, Any], dict[str, Any]]:
    plugin = import_source_plugin_by_id(conn, plugin_id)
    if not plugin:
        raise NextApiError(f"Import source plugin is not available: {plugin_id}", 409)
    if "plan_import" not in plugin_runtime_entrypoints(plugin):
        raise NextApiError(f"Import source plugin cannot plan imports: {plugin_id}", 409)

    config = plugin_config_from_db(conn, plugin_id)
    context = plugin_execution_context(conn, plugin, config, actor)
    payload = {
        "dataDir": source.get("dataDir"),
        "sqliteDb": source.get("sqliteDb"),
        "sourcePath": options.get("sourcePath") or source.get("sourcePath"),
        "sourceDatabaseHash": source.get("sourceDatabaseHash"),
        "columnMapping": options.get("columnMapping") or {},
        "includeSecurity": options.get("includeSecurity"),
        "includePersonal": options.get("includePersonal"),
        "importMediaReferences": options.get("importMediaReferences"),
        "ownerUsername": options.get("ownerUsername"),
    }
    execution = run_plugin_entrypoint(plugin_id, "plan_import", payload, context)
    if execution.get("status") != "ok":
        raise NextApiError(
            f"Import source planning failed: {execution.get('error') or execution.get('state')}",
            502,
        )
    plan = execution.get("result") or {}
    if not isinstance(plan, dict):
        raise NextApiError("Import source plan must return an object", 502)
    if not parse_bool_value(plan.get("canStart"), default=False):
        raise NextApiError(
            f"Import source cannot start: {plan.get('status') or 'blocked'}",
            409,
        )
    job_type = clean_text(plan.get("jobType")) or MIGRATION_JOB_TYPE
    if job_type not in {MIGRATION_JOB_TYPE, "plugin.execute"}:
        raise NextApiError(f"Unsupported import job type from plugin: {job_type}", 409)
    job_payload = plan.get("jobPayload") or {}
    if not isinstance(job_payload, dict):
        raise NextApiError("Import source jobPayload must be an object", 502)
    if job_type == "plugin.execute" and clean_text(job_payload.get("entrypoint")) != "import_source":
        raise NextApiError(f"Unsupported plugin import entrypoint: {job_payload.get('entrypoint')}", 409)
    job_payload = dict(job_payload)
    if job_type == "plugin.execute":
        plugin_payload = dict(job_payload.get("payload") or {})
        if options.get("columnMapping"):
            plugin_payload["columnMapping"] = options.get("columnMapping")
        job_payload["payload"] = plugin_payload
    job_payload["requestedBy"] = actor_job_payload(actor)
    if options.get("importReview"):
        job_payload["importReview"] = options.get("importReview")
    job_payload["importSource"] = {
        "pluginId": plugin_id,
        "pluginName": plugin.get("name"),
        "sourceKind": source.get("sourceKind"),
        "sourcePath": options.get("sourcePath") or source.get("sourcePath"),
    }
    return job_type, job_payload, plan


def migration_readiness(conn) -> dict[str, Any]:
    migrations = migration_overview(conn)
    probe = (
        import_source_readiness_probe(conn)
        if migrations["state"] == "ready"
        else empty_import_source_probe()
    )
    source = probe["source"]
    warnings = list(probe["warnings"])
    import_sources = list(probe.get("importSources") or [])
    target_counts = target_data_counts(conn)
    target_empty = target_database_empty(target_counts)
    source_hash = clean_text(source.get("sourceDatabaseHash"))
    latest_run = latest_migration_run(conn, source_hash)
    fallback_completed_run = (
        latest_completed_migration_run(conn)
        if not latest_run and target_has_legacy_collection_import(conn)
        else None
    )
    latest_run_for_state = latest_run or fallback_completed_run
    source_changed_after_completion = bool(
        fallback_completed_run
        and source_hash
        and clean_text(fallback_completed_run.get("source_database_hash")) != source_hash
    )
    active_job = active_migration_job(conn, source_hash)
    latest = migration_run_row(latest_run_for_state)
    active = job_row(active_job) if active_job else None
    security_backfill_required = migration_security_backfill_required(
        conn,
        source.get("sourceCounts") or {},
        latest,
    )
    required_actions: list[str] = []

    if migrations["state"] != "ready":
        state = "blocked_schema_not_ready"
        required_actions.append("Apply pending PostgreSQL migrations before starting import.")
    elif active:
        state = "running"
        required_actions.append("Wait for the active migration job to finish.")
    elif not source.get("pluginId"):
        state = "not_required"
        required_actions.append("Enable and configure an import source plugin if migration is expected.")
    elif not source["found"]:
        state = "not_required"
        required_actions.append("Configure the selected import source or mount the legacy DiscVault data directory at /data if migration is expected.")
    elif not source["readable"]:
        state = "blocked_source_unreadable"
        required_actions.append("Fix the legacy SQLite database path or file permissions.")
    elif security_backfill_required:
        state = "ready_for_security_backfill"
        required_actions.append("Import legacy users, passkeys and media groups for the completed collection migration.")
    elif latest and latest["status"] == "completed":
        state = "already_completed"
        if source_changed_after_completion:
            warnings.append(
                "Legacy source database changed after the completed migration. "
                "DiscVault Next will keep using the migrated PostgreSQL collection."
            )
            required_actions.append(
                "A completed migration already exists. Use DiscVault Next normally; "
                "a future conflict-aware import can handle later legacy changes."
            )
        else:
            required_actions.append("A completed migration for this source database already exists.")
    elif not target_empty:
        state = "blocked_target_not_empty"
        required_actions.append("Use an empty PostgreSQL target database or start an explicit conflict-aware import later.")
    else:
        state = "ready_for_confirmation"
        required_actions.append("Confirm the migration in the UI or call the migration start endpoint.")

    can_start = state in {"ready_for_confirmation", "ready_for_security_backfill"}
    legacy_auth = {
        "required": legacy_auth_required(source),
        "authenticated": False,
    }
    return {
        "state": state,
        "canStart": can_start,
        "requiresConfirmation": can_start,
        "legacyAuth": legacy_auth,
        "legacyData": source,
        "importSources": import_sources,
        "targetDatabase": {
            "empty": target_empty,
            "counts": target_counts,
        },
        "migrations": migrations,
        "activeJob": active,
        "latestRun": latest,
        "warnings": warnings,
        "requiredActions": required_actions,
    }


def migration_dry_run_diff(readiness: dict[str, Any], imported: dict[str, Any] | None = None) -> dict[str, Any]:
    source_counts = ((readiness.get("legacyData") or {}).get("sourceCounts") or {})
    target_counts = ((readiness.get("targetDatabase") or {}).get("counts") or {})
    imported_counts = imported or {}
    rows = [
        {
            "key": "movies",
            "label": "Movies",
            "source": int(source_counts.get("movies") or 0),
            "target": int(target_counts.get("movies") or 0),
            "imported": int(imported_counts.get("movies") or 0),
        },
        {
            "key": "people",
            "label": "People",
            "source": int(source_counts.get("people") or 0),
            "target": int(target_counts.get("people") or 0),
            "imported": int(imported_counts.get("people") or 0),
        },
        {
            "key": "movie_credits",
            "label": "Movie credits",
            "source": int(source_counts.get("movie_people") or 0),
            "target": int(target_counts.get("movie_credits") or 0),
            "imported": int(imported_counts.get("movie_credits") or 0),
        },
        {
            "key": "containers",
            "label": "Containers",
            "source": int(source_counts.get("box_sets") or 0) + int(source_counts.get("collections") or 0),
            "target": int(target_counts.get("containers") or 0),
            "imported": int(imported_counts.get("containers_box_set") or 0) + int(imported_counts.get("containers_collection") or 0),
        },
        {
            "key": "container_movies",
            "label": "Container movies",
            "source": int(source_counts.get("box_set_movies") or 0),
            "target": int(target_counts.get("container_movies") or 0),
            "imported": int(imported_counts.get("box_set_movies") or 0),
        },
        {
            "key": "collection_items",
            "label": "Collection items",
            "source": int(source_counts.get("collection_items") or 0),
            "target": int(target_counts.get("collection_items") or 0),
            "imported": int(imported_counts.get("collection_items") or 0),
        },
        {
            "key": "media_groups",
            "label": "Media groups",
            "source": int(source_counts.get("media_groups") or source_counts.get("groups") or 0),
            "target": int(target_counts.get("media_groups") or 0),
            "imported": int(imported_counts.get("media_groups") or 0),
        },
        {
            "key": "users",
            "label": "Users",
            "source": int(source_counts.get("users") or 0),
            "target": int(target_counts.get("users") or 0),
            "imported": int(imported_counts.get("users") or 0),
        },
    ]
    for row in rows:
        row["remaining"] = max(0, int(row["source"]) - int(row["target"]))
        row["matched"] = int(row["target"]) >= int(row["source"]) if int(row["source"]) else True
    return {
        "state": readiness.get("state"),
        "rows": rows,
        "sourceTotal": sum(int(row["source"]) for row in rows),
        "targetTotal": sum(int(row["target"]) for row in rows),
        "importedTotal": sum(int(row["imported"]) for row in rows),
    }


def migration_recovery_plan(readiness: dict[str, Any], latest_job: dict[str, Any] | None) -> dict[str, Any]:
    state = readiness.get("state") or "unknown"
    latest_status = (latest_job or {}).get("status")
    latest_error = clean_text((latest_job or {}).get("error"))
    can_retry = bool(readiness.get("canStart")) and state in {"ready_for_confirmation", "ready_for_security_backfill"}
    actions = list(readiness.get("requiredActions") or [])
    if latest_error:
        actions.insert(0, "Review the failed migration job error and retry after correcting the source or plugin configuration.")
    if state == "blocked_target_not_empty":
        actions.append("Use the test reset button only on a disposable beta database, or create a clean PostgreSQL target.")
    if state == "blocked_source_unreadable":
        actions.append("Verify that the legacy data directory is mounted and readable by the DiscVault 26 container.")
    if state == "ready_for_security_backfill":
        actions.append("Run the security backfill to import legacy users, passkeys and sharing groups.")
    return {
        "state": state,
        "latestJobStatus": latest_status,
        "latestJobError": latest_error,
        "canRetry": can_retry,
        "testResetEnabled": test_database_reset_enabled(),
        "actions": actions,
    }


def migration_report(conn) -> dict[str, Any]:
    readiness = migration_readiness(conn)
    latest_run = readiness.get("latestRun")
    latest_job = None
    if latest_run:
        latest_job = migration_job_summary(conn)
    elif readiness.get("activeJob"):
        active_id = UUID(str(readiness["activeJob"]["id"]))
        latest_job = migration_job_summary(conn, active_id)

    latest_result = latest_run.get("result") if latest_run else {}
    source_counts = readiness.get("legacyData", {}).get("sourceCounts") or {}
    imported = latest_result.get("counters") if isinstance(latest_result, dict) else {}
    skipped = latest_result.get("skipped") if isinstance(latest_result, dict) else {}
    warnings = list(readiness.get("warnings") or [])
    if isinstance(latest_result, dict):
        warnings.extend(latest_result.get("warnings") or [])

    return {
        "state": readiness["state"],
        "canStart": readiness["canStart"],
        "requiresConfirmation": readiness["requiresConfirmation"],
        "legacyAuth": readiness.get("legacyAuth") or {},
        "source": {
            "pluginId": readiness["legacyData"].get("pluginId"),
            "pluginName": readiness["legacyData"].get("pluginName"),
            "sourceKind": readiness["legacyData"].get("sourceKind"),
            "status": readiness["legacyData"].get("status"),
            "found": readiness["legacyData"]["found"],
            "readable": readiness["legacyData"]["readable"],
            "dataDir": readiness["legacyData"]["dataDir"],
            "sqliteDb": readiness["legacyData"]["sqliteDb"],
            "sourceDatabaseHash": readiness["legacyData"]["sourceDatabaseHash"],
            "counts": source_counts,
            "mediaExtensions": readiness["legacyData"]["mediaExtensions"],
            "mediaMigrationMode": readiness["legacyData"]["mediaMigrationMode"],
        },
        "target": readiness["targetDatabase"],
        "latestRun": latest_run,
        "latestJob": latest_job,
        "importSources": readiness.get("importSources") or [],
        "summary": {
            "imported": imported or {},
            "skipped": skipped or {},
            "warnings": warnings,
        },
        "metadataPlugins": plugin_summary(conn),
        "dryRunDiff": migration_dry_run_diff(readiness, imported or {}),
        "recovery": migration_recovery_plan(readiness, latest_job),
        "testReset": {
            "enabled": test_database_reset_enabled(),
            "confirmation": TEST_DATABASE_RESET_CONFIRMATION,
        },
        "requiredActions": readiness["requiredActions"],
    }


def startup_status_payload(conn) -> dict[str, Any]:
    readiness = migration_readiness(conn)
    auth_effective = next_auth_effective_enabled(conn, table_exists)
    user_count = count_table(conn, "users")
    credential_count = count_table(conn, "passkey_credentials")
    auth_ready = user_count > 0 and credential_count > 0
    user = next_auth_current_user(conn) if auth_effective else None
    role = next_user_primary_role(conn, user["id"]) if user else None
    permissions = next_user_permission_keys(conn, user["id"]) if user else set()
    migration_blocks_collection = readiness["state"] not in {"already_completed", "not_required"}
    can_manage_migration = (
        not auth_effective
        or (
            bool(user)
            and (role == "owner" or "collection.import" in permissions)
        )
    )

    phase = "ready"
    message = "DiscVault Next is ready."
    legacy_auth_waiting = bool(
        not auth_ready
        and migration_blocks_collection
        and legacy_auth_required(readiness.get("legacyData") or {})
    )
    if readiness["migrations"]["state"] != "ready":
        phase = "schema_blocked"
        message = "PostgreSQL migrations must finish before DiscVault Next can start."
    elif legacy_auth_waiting:
        phase = "migration_required"
        message = "Legacy DiscVault data is ready to migrate."
    elif not auth_ready:
        phase = "owner_setup"
        message = "Create the first owner passkey to finish setup."
    elif migration_blocks_collection:
        if readiness["state"] == "running":
            phase = "migration_running"
            message = "Legacy migration is running."
        elif auth_effective and not user:
            phase = "sign_in_required"
            message = "Sign in with a passkey to continue setup."
        elif auth_effective and user and not can_manage_migration:
            phase = "migration_pending_non_admin"
            message = "DiscVault Next is waiting for an owner or administrator to complete migration."
        else:
            phase = "migration_required"
            message = "Legacy DiscVault data is ready to migrate."
    source_counts = readiness["legacyData"]["sourceCounts"] or {}
    legacy_found = bool(readiness["legacyData"]["found"])
    show_migration_context = phase != "owner_setup" and (
        legacy_found or readiness["state"] not in {"not_required"}
    )
    steps = [
        {
            "key": "auth",
            "label": "Owner passkey",
            "state": "complete" if auth_ready else ("active" if phase == "owner_setup" else "pending"),
            "detail": (
                f"{user_count} user(s), {credential_count} passkey(s)"
                if auth_ready
                else "Use the legacy owner/admin passkey to approve migration."
                if legacy_auth_waiting
                else "Create the first owner passkey for this DiscVault Next environment."
            ),
        },
        {
            "key": "collection",
            "label": "Collection",
            "state": "complete" if phase == "ready" else "pending",
            "detail": "Ready to browse." if phase == "ready" else "Available after setup is complete.",
        },
    ]
    if show_migration_context:
        steps.insert(
            1,
            {
                "key": "source",
                "label": "Legacy data",
                "state": "complete" if legacy_found else "skipped",
                "detail": (
                    f"{source_counts.get('movies', 0)} movies, {source_counts.get('users', 0)} users, "
                    f"{source_counts.get('groups', 0)} groups"
                    if legacy_found
                    else "No legacy SQLite database detected."
                ),
            },
        )
        steps.insert(
            2,
            {
                "key": "migration",
                "label": "Migration",
                "state": (
                    "complete"
                    if readiness["state"] in {"already_completed", "not_required"}
                    else "active"
                    if readiness["state"] in {"running", "ready_for_confirmation", "ready_for_security_backfill"}
                    else "blocked"
                ),
                "detail": readiness["state"],
            },
        )

    migration_payload = {
        "state": readiness["state"],
        "canStart": readiness["canStart"],
        "requiresConfirmation": readiness["requiresConfirmation"],
        "requiredActions": readiness["requiredActions"],
        "activeJob": readiness["activeJob"],
        "latestRun": readiness["latestRun"],
        "legacyData": {
            "pluginId": readiness["legacyData"].get("pluginId"),
            "pluginName": readiness["legacyData"].get("pluginName"),
            "sourceKind": readiness["legacyData"].get("sourceKind"),
            "status": readiness["legacyData"].get("status"),
            "found": readiness["legacyData"]["found"],
            "readable": readiness["legacyData"]["readable"],
            "sourceCounts": readiness["legacyData"]["sourceCounts"],
            "mediaExtensions": readiness["legacyData"]["mediaExtensions"],
        },
        "importSources": readiness.get("importSources") or [],
    }
    if not show_migration_context:
        migration_payload = {
            "state": "",
            "canStart": False,
            "requiresConfirmation": False,
            "requiredActions": [],
            "activeJob": None,
            "latestRun": None,
            "legacyData": {
                "found": False,
                "readable": False,
                "sourceCounts": {},
                "mediaExtensions": {},
            },
            "importSources": [],
        }

    return {
        "phase": phase,
        "ready": phase == "ready",
        "message": message,
        "canUseCollection": phase == "ready",
        "canStartMigration": bool(readiness["canStart"] and can_manage_migration and auth_ready),
        "canCreateOwner": phase == "owner_setup",
        "canSignIn": bool(auth_effective and not user),
        "canSwitchAccount": bool(auth_effective and user and migration_blocks_collection and not can_manage_migration),
        "steps": steps,
        "auth": {
            "effective": auth_effective,
            "ready": auth_ready,
            "setupRequired": not auth_ready,
            "authenticated": bool(user),
            "role": role,
            "username": user.get("username") if user else None,
            "userCount": user_count,
            "credentialCount": credential_count,
        },
        "migration": migration_payload,
    }




def collection_movie_preview_entities(conn, *, limit: int = 200, actor: dict[str, Any] | None = None) -> list[dict[str, Any]]:
    if not table_exists(conn, "movies"):
        return []
    visibility_where, visibility_params = visible_movie_where_sql(conn, actor, "m") if actor else ("TRUE", [])
    if table_exists(conn, "entity_media") and table_exists(conn, "media_assets"):
        with conn.cursor() as cur:
            cur.execute(
                f"""
                SELECT
                    m.id,
                    m.public_id,
                    m.barcode,
                    m.title,
                    m.sort_title,
                    m.original_title,
                    m.year,
                    m.format,
                    m.edition,
                    m.location,
                    m.metadata->>'genre' AS genre,
                    m.metadata->>'audience_rating' AS audience_rating,
                    m.rating,
                    mts.content_ratings,
                    concat_ws(' ',
                        m.metadata->>'actor',
                        m.metadata->>'director',
                        m.metadata->>'producer',
                        m.metadata->>'writer',
                        m.metadata->>'genre',
                        m.metadata->>'studios'
                    ) AS metadata_search,
                    COALESCE(m.metadata->>'poster_url', poster_asset.source_url) AS poster_url,
                    COALESCE(m.metadata->>'backdrop_url', backdrop_asset.source_url) AS backdrop_url,
                    poster_asset.id AS poster_asset_id,
                    poster_asset.storage_backend AS poster_asset_storage_backend,
                    poster_asset.storage_key AS poster_asset_storage_key,
                    poster_asset.source_url AS poster_asset_source_url,
                    backdrop_asset.id AS backdrop_asset_id,
                    backdrop_asset.storage_backend AS backdrop_asset_storage_backend,
                    backdrop_asset.storage_key AS backdrop_asset_storage_key,
                    backdrop_asset.source_url AS backdrop_asset_source_url,
                    m.location_id,
                    m.owner_id,
                    m.created_at,
                    m.updated_at
                FROM movies m
                LEFT JOIN movie_technical_specs mts ON mts.movie_id = m.id
                LEFT JOIN LATERAL (
                    SELECT ma.id, ma.storage_backend, ma.storage_key, ma.source_url
                    FROM entity_media em
                    JOIN media_assets ma ON ma.id = em.media_id
                    WHERE em.entity_type='movie'
                      AND em.entity_id=m.id
                      AND em.deleted_at IS NULL
                      AND ma.kind='poster'
                    ORDER BY em.is_primary DESC, em.sort_order, ma.created_at
                    LIMIT 1
                ) poster_asset ON true
                LEFT JOIN LATERAL (
                    SELECT ma.id, ma.storage_backend, ma.storage_key, ma.source_url
                    FROM entity_media em
                    JOIN media_assets ma ON ma.id = em.media_id
                    WHERE em.entity_type='movie'
                      AND em.entity_id=m.id
                      AND em.deleted_at IS NULL
                      AND ma.kind='backdrop'
                    ORDER BY em.is_primary DESC, em.sort_order, ma.created_at
                    LIMIT 1
                ) backdrop_asset ON true
                WHERE {visibility_where}
                ORDER BY lower(COALESCE(m.sort_title, m.title)), m.year NULLS LAST
                LIMIT %s
                """,
                (*visibility_params, limit),
            )
            return attach_movie_search_credits(
                conn,
                attach_media_group_availability(
                    conn,
                    attach_digital_availability(conn, attach_location_summaries(conn, [with_preview_media_urls(row) for row in cur.fetchall()])),
                ),
            )
    with conn.cursor() as cur:
        cur.execute(
            f"""
            SELECT
                m.id,
                m.public_id,
                m.barcode,
                m.title,
                m.sort_title,
                m.original_title,
                m.year,
                m.format,
                m.edition,
                m.location,
                m.metadata->>'genre' AS genre,
                m.metadata->>'audience_rating' AS audience_rating,
                m.rating,
                NULL::jsonb AS content_ratings,
                concat_ws(' ',
                    m.metadata->>'actor',
                    m.metadata->>'director',
                    m.metadata->>'producer',
                    m.metadata->>'writer',
                    m.metadata->>'genre',
                    m.metadata->>'studios'
                ) AS metadata_search,
                m.metadata->>'poster_url' AS poster_url,
                m.metadata->>'backdrop_url' AS backdrop_url,
                m.location_id,
                m.owner_id,
                m.created_at,
                m.updated_at
            FROM movies m
            WHERE {visibility_where}
            ORDER BY lower(COALESCE(m.sort_title, m.title)), m.year NULLS LAST
            LIMIT %s
            """,
            (*visibility_params, limit),
        )
        return attach_movie_search_credits(
            conn,
            attach_media_group_availability(conn, attach_digital_availability(conn, attach_location_summaries(conn, cur.fetchall()))),
        )


def attach_movie_search_credits(conn, movies: list[dict[str, Any]]) -> list[dict[str, Any]]:
    if not movies or not table_exists(conn, "movie_credits") or not table_exists(conn, "people"):
        return movies
    movie_ids = [movie.get("id") for movie in movies if movie.get("id")]
    if not movie_ids:
        return movies
    credits_by_movie: dict[str, list[str]] = {str(movie_id): [] for movie_id in movie_ids}
    preview_by_movie: dict[str, dict[str, list[dict[str, Any]]]] = {
        str(movie_id): {"directors": [], "actors": []} for movie_id in movie_ids
    }
    with conn.cursor() as cur:
        cur.execute(
            """
            SELECT
                mc.movie_id,
                p.id AS person_id,
                p.public_id AS person_public_id,
                p.name,
                p.known_for,
                mc.credit_type,
                mc.character,
                mc.job,
                mc.sort_order
            FROM movie_credits mc
            JOIN people p ON p.id = mc.person_id
            WHERE mc.movie_id = ANY(%s)
            ORDER BY mc.movie_id, mc.sort_order, p.name
            """,
            (movie_ids,),
        )
        for row in cur.fetchall():
            key = str(row.get("movie_id"))
            values = credits_by_movie.get(key)
            if values is None or len(values) >= 80:
                continue
            values.extend(
                clean_text(row.get(field))
                for field in ("name", "known_for", "credit_type", "character", "job")
                if clean_text(row.get(field))
            )
            preview = preview_by_movie.get(key)
            if preview is None:
                continue
            name = clean_text(row.get("name"))
            if not name:
                continue
            credit = {
                "id": row.get("person_id"),
                "public_id": row.get("person_public_id"),
                "name": name,
                "character": clean_text(row.get("character")),
                "job": clean_text(row.get("job")),
                "sort_order": row.get("sort_order"),
            }
            job = (clean_text(row.get("job")) or "").lower()
            credit_type = (clean_text(row.get("credit_type")) or "").lower()
            if "director" in job and len(preview["directors"]) < 3:
                preview["directors"].append(credit)
            elif credit_type in {"actor", "cast"} and len(preview["actors"]) < 5:
                preview["actors"].append(credit)
    for movie in movies:
        movie["search_credits"] = " ".join(credits_by_movie.get(str(movie.get("id")), []))
        movie["preview_credits"] = preview_by_movie.get(str(movie.get("id")), {"directors": [], "actors": []})
    return movies


def collection_container_preview_entities(conn, *, limit: int = 200, actor: dict[str, Any] | None = None) -> list[dict[str, Any]]:
    if not table_exists(conn, "containers"):
        return []
    visibility_where, visibility_params = visible_container_where_sql(conn, actor, "c") if actor else ("TRUE", [])
    if table_exists(conn, "entity_media") and table_exists(conn, "media_assets"):
        with conn.cursor() as cur:
            cur.execute(
                f"""
                SELECT
                    c.id,
                    c.public_id,
                    c.container_type,
                    c.title,
                    c.barcode,
                    c.badge_label,
                    c.year,
                    c.description,
                    c.metadata,
                    poster_asset.id AS poster_asset_id,
                    poster_asset.storage_backend AS poster_asset_storage_backend,
                    poster_asset.storage_key AS poster_asset_storage_key,
                    poster_asset.source_url AS poster_asset_source_url,
                    backdrop_asset.id AS backdrop_asset_id,
                    backdrop_asset.storage_backend AS backdrop_asset_storage_backend,
                    backdrop_asset.storage_key AS backdrop_asset_storage_key,
                    backdrop_asset.source_url AS backdrop_asset_source_url,
                    c.location_id,
                    c.created_at,
                    c.updated_at
                FROM containers c
                LEFT JOIN LATERAL (
                    SELECT ma.id, ma.storage_backend, ma.storage_key, ma.source_url
                    FROM entity_media em
                    JOIN media_assets ma ON ma.id = em.media_id
                    WHERE em.entity_type='container'
                      AND em.entity_id=c.id
                      AND em.deleted_at IS NULL
                      AND ma.kind='poster'
                    ORDER BY em.is_primary DESC, em.sort_order, ma.created_at
                    LIMIT 1
                ) poster_asset ON true
                LEFT JOIN LATERAL (
                    SELECT ma.id, ma.storage_backend, ma.storage_key, ma.source_url
                    FROM entity_media em
                    JOIN media_assets ma ON ma.id = em.media_id
                    WHERE em.entity_type='container'
                      AND em.entity_id=c.id
                      AND em.deleted_at IS NULL
                      AND ma.kind='backdrop'
                    ORDER BY em.is_primary DESC, em.sort_order, ma.created_at
                    LIMIT 1
                ) backdrop_asset ON true
                WHERE {visibility_where}
                ORDER BY c.container_type, lower(c.title)
                LIMIT %s
                """,
                (*visibility_params, limit),
            )
            return attach_location_summaries(conn, [with_preview_media_urls(row) for row in cur.fetchall()])
    with conn.cursor() as cur:
        cur.execute(
            f"""
            SELECT
                c.id,
                c.public_id,
                c.container_type,
                c.title,
                c.barcode,
                c.badge_label,
                c.year,
                c.description,
                c.metadata,
                c.location_id,
                c.created_at,
                c.updated_at
            FROM containers c
            WHERE {visibility_where}
            ORDER BY c.container_type, lower(c.title)
            LIMIT %s
            """,
            (*visibility_params, limit),
        )
        return attach_location_summaries(conn, cur.fetchall())


def collection_container_membership_entities(conn, *, limit: int = 10000, actor: dict[str, Any] | None = None) -> list[dict[str, Any]]:
    if not table_exists(conn, "containers") or not table_exists(conn, "movies"):
        return []
    links: list[dict[str, Any]] = []
    if table_exists(conn, "container_movies"):
        visibility_where, visibility_params = visible_movie_where_sql(conn, actor, "m") if actor else ("TRUE", [])
        with conn.cursor() as cur:
            cur.execute(
                f"""
                SELECT
                    cm.container_id,
                    cm.movie_id,
                    c.container_type,
                    cm.sort_order,
                    'container_movie' AS relationship,
                    NULL::uuid AS child_container_id
                FROM container_movies cm
                JOIN containers c ON c.id = cm.container_id
                JOIN movies m ON m.id = cm.movie_id
                WHERE {visibility_where}
                ORDER BY c.container_type, lower(c.title), cm.sort_order
                LIMIT %s
                """,
                (*visibility_params, limit),
            )
            links.extend(cur.fetchall())
    remaining = max(limit - len(links), 0)
    if remaining and table_exists(conn, "collection_items"):
        visibility_where, visibility_params = visible_movie_where_sql(conn, actor, "m") if actor else ("TRUE", [])
        with conn.cursor() as cur:
            cur.execute(
                f"""
                SELECT
                    ci.collection_id AS container_id,
                    ci.item_id AS movie_id,
                    c.container_type,
                    ci.sort_order,
                    'collection_movie' AS relationship,
                    NULL::uuid AS child_container_id
                FROM collection_items ci
                JOIN containers c ON c.id = ci.collection_id
                JOIN movies m ON m.id = ci.item_id
                WHERE ci.item_type='movie'
                  AND {visibility_where}
                ORDER BY lower(c.title), ci.sort_order
                LIMIT %s
                """,
                (*visibility_params, remaining),
            )
            links.extend(cur.fetchall())
    remaining = max(limit - len(links), 0)
    if remaining and table_exists(conn, "collection_items"):
        visibility_where, visibility_params = visible_container_where_sql(conn, actor, "child_c") if actor else ("TRUE", [])
        with conn.cursor() as cur:
            cur.execute(
                f"""
                SELECT
                    ci.collection_id AS container_id,
                    NULL::uuid AS movie_id,
                    c.container_type,
                    ci.sort_order,
                    'collection_container' AS relationship,
                    ci.item_id AS child_container_id
                FROM collection_items ci
                JOIN containers c ON c.id = ci.collection_id
                JOIN containers child_c ON child_c.id = ci.item_id
                WHERE ci.item_type <> 'movie'
                  AND {visibility_where}
                ORDER BY lower(c.title), ci.sort_order
                LIMIT %s
                """,
                (*visibility_params, remaining),
            )
            links.extend(cur.fetchall())
    remaining = max(limit - len(links), 0)
    if remaining and table_exists(conn, "collection_items") and table_exists(conn, "container_movies"):
        visibility_where, visibility_params = visible_movie_where_sql(conn, actor, "m") if actor else ("TRUE", [])
        with conn.cursor() as cur:
            cur.execute(
                f"""
                SELECT
                    ci.collection_id AS container_id,
                    cm.movie_id,
                    c.container_type,
                    ci.sort_order,
                    'collection_container_movie' AS relationship,
                    ci.item_id AS child_container_id
                FROM collection_items ci
                JOIN containers c ON c.id = ci.collection_id
                JOIN container_movies cm ON cm.container_id = ci.item_id
                JOIN movies m ON m.id = cm.movie_id
                WHERE ci.item_type <> 'movie'
                  AND {visibility_where}
                ORDER BY lower(c.title), ci.sort_order
                LIMIT %s
                """,
                (*visibility_params, remaining),
            )
            links.extend(cur.fetchall())
    return links[:limit]


def collection_plugin_preview_entities(conn) -> list[dict[str, Any]]:
    if not table_exists(conn, "metadata_plugins"):
        return []
    sync_metadata_plugin_registry(conn)
    with conn.cursor() as cur:
        cur.execute(
            """
            SELECT id, name, enabled, order_index
            FROM metadata_plugins
            ORDER BY order_index, name
            """
        )
        return cur.fetchall()


def collection_dashboard_snapshot(conn, user: dict[str, Any] | None = None) -> dict[str, Any]:
    user_id = user.get("id") if user else None
    counts = {
        "movies": visible_movie_count(conn, user) if user else count_table(conn, "movies"),
        "people": visible_people_count(conn, user) if user else count_table(conn, "people"),
        "movieCredits": visible_movie_credit_count(conn, user) if user else count_table(conn, "movie_credits"),
        "containers": visible_container_count(conn, user) if user else count_table(conn, "containers"),
        "mediaGroups": visible_media_group_count(conn, user) if user else count_table(conn, "media_groups"),
        "mediaAssets": visible_media_asset_count(conn, user) if user else count_table(conn, "media_assets"),
        "metadataPlugins": count_table(conn, "metadata_plugins"),
        "digitalMediaSources": count_table(conn, "digital_media_sources"),
        "digitalMediaItems": count_table(conn, "digital_media_items"),
        "users": count_table(conn, "users"),
    }
    counts["personalLists"] = personal_list_counts(conn, user_id)
    counts["notifications"] = notification_counts(conn, user_id)
    movies = collection_movie_preview_entities(conn, actor=user)
    movies = attach_personal_list_state(conn, movies, user_id)
    return {
        "counts": counts,
        "movies": movies,
        "containers": collection_container_preview_entities(conn, actor=user),
        "containerMembership": collection_container_membership_entities(conn, actor=user),
        "locations": location_list_entities(conn),
        "mediaGroups": media_group_entities(conn, limit=200, actor=user),
        "plugins": collection_plugin_preview_entities(conn),
        "preferences": app_effective_preferences(conn, user_id),
        "instanceSettings": {
            "loansSystemEnabled": loans_system_enabled(conn),
        },
        "user": {
            "id": user.get("id"),
            "username": user.get("username"),
            "displayName": user.get("display_name") or user.get("username"),
            "role": user.get("role"),
            "permissions": sorted(user.get("permissions") or []),
        }
        if user
        else None,
        "build": {
            "version": build_version(),
            "sha": build_sha(),
            "generatedAt": datetime.utcnow().isoformat(timespec="seconds") + "Z",
        },
    }


