def h(value: Any) -> str:
    return html_lib.escape(str(value or ""), quote=True)


def server_usable_image(value: Any) -> str:
    text = str(value or "")
    if text.startswith("http://") or text.startswith("https://"):
        return text
    if text.startswith("/api/next/media/"):
        return text
    return ""


def first_usable_image(*values: Any) -> str:
    for value in values:
        if isinstance(value, list):
            nested = first_usable_image(*value)
            if nested:
                return nested
            continue
        image = server_usable_image(value)
        if image:
            return image
    return ""


def app_href(path: str = "") -> str:
    return f"/api/next/app{path}"


def media_asset_public_url(asset: dict[str, Any] | None) -> str:
    if not asset:
        return ""
    asset_id = asset.get("id")
    storage_backend = str(asset.get("storage_backend") or "")
    storage_key = str(asset.get("storage_key") or "")
    if (
        asset_id
        and storage_backend == "local"
        and storage_key
        and not storage_key.startswith("remote/")
    ):
        return f"/api/next/media/assets/{asset_id}"
    return server_usable_image(asset.get("source_url"))


def legacy_media_relative_path(kind: str, value: Any) -> str | None:
    text = str(value or "").strip().replace("\\", "/")
    if not text or text.startswith(("http://", "https://", "/api/next/media/")):
        return None
    text = text.split("?", 1)[0].split("#", 1)[0].lstrip("/")
    for prefix in ("api/images/", "api/posters/"):
        if text.startswith(prefix):
            text = text[len(prefix):]
    if kind == "poster" and text.startswith("offline/poster/"):
        text = text.removeprefix("offline/poster/")
    if kind == "backdrop" and text.startswith("offline/backdrop/"):
        text = "posters/_variants/backdrop/" + text.removeprefix("offline/backdrop/")
    if kind == "poster" and not text.startswith("posters/"):
        text = "posters/" + text
    elif kind == "backdrop":
        if text.startswith("_variants/backdrop/"):
            text = "posters/" + text
        elif not text.startswith("posters/"):
            text = "posters/_variants/backdrop/" + text
    elif kind == "profile":
        if text.startswith("api/profiles/"):
            text = "profiles/" + text.removeprefix("api/profiles/")
        elif text.startswith("offline/profile/"):
            text = "profiles/" + text
        elif not text.startswith("profiles/"):
            text = "profiles/" + text
    parts = [part for part in text.split("/") if part]
    if not parts or any(part in ("..", ".", "") for part in parts):
        return None
    return "/".join(parts)


def legacy_media_path(kind: str, value: Any) -> Path | None:
    relative = legacy_media_relative_path(kind, value)
    if not relative:
        return None
    data_dir = legacy_data_dir().resolve()
    candidate = (data_dir / Path(*relative.split("/"))).resolve()
    try:
        candidate.relative_to(data_dir)
    except ValueError:
        return None
    if not candidate.exists() or not candidate.is_file():
        return None
    return candidate


def legacy_media_public_url(kind: str, value: Any) -> str:
    existing = server_usable_image(value)
    if existing:
        return existing
    relative = legacy_media_relative_path(kind, value)
    if not relative or not legacy_media_path(kind, relative):
        return ""
    return f"/api/next/media/legacy/{kind}/{quote(relative, safe='/')}"


def legacy_metadata_image_url(metadata: dict[str, Any], kind: str) -> str:
    if kind == "poster":
        return (
            first_usable_image(metadata.get("poster_url"), metadata.get("posterUrl"), metadata.get("poster"))
            or legacy_media_public_url("poster", metadata.get("poster_file"))
            or legacy_media_public_url("poster", metadata.get("poster_url"))
            or legacy_media_public_url("poster", metadata.get("posterUrl"))
            or legacy_media_public_url("poster", metadata.get("poster"))
        )
    return (
        first_usable_image(metadata.get("backdrop_url"), metadata.get("backdropUrl"), metadata.get("backdrop"))
        or legacy_media_public_url("backdrop", metadata.get("backdrop_url"))
        or legacy_media_public_url("backdrop", metadata.get("backdropUrl"))
        or legacy_media_public_url("backdrop", metadata.get("backdrop"))
        or legacy_media_public_url("backdrop", metadata.get("poster_file"))
    )


def profile_metadata_image_url(metadata: dict[str, Any]) -> str:
    return (
        first_usable_image(
            metadata.get("profile_url"),
            metadata.get("profileUrl"),
            metadata.get("photo_url"),
            metadata.get("photoUrl"),
        )
        or legacy_media_public_url("profile", metadata.get("photo_file"))
        or legacy_media_public_url("profile", metadata.get("photoFile"))
    )


def with_legacy_metadata_media_urls(row: dict[str, Any] | None) -> dict[str, Any] | None:
    if not row:
        return row
    data = dict(row)
    metadata = data.get("metadata") if isinstance(data.get("metadata"), dict) else {}
    metadata = dict(metadata)
    poster = legacy_metadata_image_url(metadata, "poster")
    backdrop = legacy_metadata_image_url(metadata, "backdrop")
    if poster:
        metadata["poster_url"] = poster
    if backdrop:
        metadata["backdrop_url"] = backdrop
    data["metadata"] = metadata
    return data


def with_preview_media_urls(row: dict[str, Any]) -> dict[str, Any]:
    data = with_legacy_metadata_media_urls(row) or dict(row)
    for kind in ("poster", "backdrop"):
        asset = {
            "id": data.pop(f"{kind}_asset_id", None),
            "storage_backend": data.pop(f"{kind}_asset_storage_backend", None),
            "storage_key": data.pop(f"{kind}_asset_storage_key", None),
            "source_url": data.pop(f"{kind}_asset_source_url", None),
        }
        url = media_asset_public_url(asset)
        metadata = data.get("metadata") if isinstance(data.get("metadata"), dict) else {}
        if not url:
            url = first_usable_image(metadata.get(f"{kind}_url"), metadata.get(f"{kind}Url"), metadata.get(kind))
        if not url:
            url = legacy_metadata_image_url(metadata, kind)
        if url:
            data[f"{kind}_url"] = url
    return data


def local_media_asset_path(storage_key: Any) -> Path | None:
    text = str(storage_key or "").replace("\\", "/").strip()
    if not text or text.startswith("/") or text.startswith("remote/"):
        return None
    parts = [part for part in text.split("/") if part]
    if any(part == ".." for part in parts):
        return None
    data_dir = legacy_data_dir().resolve()
    candidate = (data_dir / Path(*parts)).resolve()
    try:
        candidate.relative_to(data_dir)
    except ValueError:
        return None
    if not candidate.exists() or not candidate.is_file():
        return None
    return candidate


def container_detail_image(media_assets: list[dict[str, Any]], metadata: dict[str, Any], kind: str) -> str:
    primary_assets = [
        media_asset_public_url(asset)
        for asset in media_assets
        if asset.get("kind") == kind and asset.get("is_primary")
    ]
    other_assets = [
        media_asset_public_url(asset)
        for asset in media_assets
        if asset.get("kind") == kind and not asset.get("is_primary")
    ]
    if kind == "poster":
        metadata_values = [
            metadata.get("poster_url"),
            metadata.get("posterUrl"),
            metadata.get("poster"),
            metadata.get("posters"),
        ]
    else:
        metadata_values = [
            metadata.get("backdrop_url"),
            metadata.get("backdropUrl"),
            metadata.get("backdrop"),
            metadata.get("backdrop_urls"),
            metadata.get("backdropUrls"),
        ]
    return first_usable_image(*primary_assets, *metadata_values, *other_assets) or legacy_metadata_image_url(metadata, kind)


def movie_detail_image(media_assets: list[dict[str, Any]], metadata: dict[str, Any], kind: str) -> str:
    return container_detail_image(media_assets, metadata, kind)


def detail_value(value: Any) -> str:
    if value in (None, ""):
        return ""
    if isinstance(value, list):
        return ", ".join(str(item) for item in value if item not in (None, ""))
    if isinstance(value, dict):
        return json_lib.dumps(json_ready(value), sort_keys=True, ensure_ascii=True)
    return str(value)


def detail_fields(rows: list[tuple[str, Any]]) -> str:
    items = []
    for label, value in rows:
        text = detail_value(value)
        if text:
            items.append(
                f'<div class="field"><span>{h(label)}</span><strong>{h(text)}</strong></div>'
            )
    return "".join(items) or '<div class="empty small">No data imported yet.</div>'


def detail_tags(*values: Any) -> str:
    tags = []
    for value in values:
        text = detail_value(value)
        if text:
            tags.append(f'<span class="tag">{h(text)}</span>')
    return "".join(tags)






def container_detail_media_rows(media_assets: list[dict[str, Any]]) -> str:
    if not media_assets:
        return '<div class="empty small">No media assets linked yet.</div>'
    rows = []
    for asset in media_assets:
        label = " / ".join(
            detail_value(value)
            for value in [asset.get("kind"), asset.get("role"), asset.get("variant")]
            if detail_value(value)
        )
        value = asset.get("source_url") or asset.get("storage_key") or asset.get("sha256")
        display_url = media_asset_public_url(asset)
        if display_url:
            value = display_url
        rows.append(f'<div class="field"><span>{h(label)}</span><strong>{h(value)}</strong></div>')
    return "".join(rows)
























def normalize_media_group_member_role(value: Any) -> str:
    role = str(value or "member").strip().lower().replace(" ", "_")
    if role not in MEDIA_GROUP_MEMBER_ROLES:
        raise NextApiError("Invalid media group role", 400)
    return role


def can_manage_media_group_members(conn, group_id: UUID, actor: dict[str, Any]) -> bool:
    if actor.get("role") in {"owner", "admin"}:
        return True
    actor_id = actor.get("id")
    if not actor_id:
        return True
    if not table_exists(conn, "media_group_members"):
        return False
    with conn.cursor() as cur:
        cur.execute(
            """
            SELECT role
            FROM media_group_members
            WHERE group_id=%s AND user_id=%s
            """,
            (group_id, actor_id),
        )
        member = cur.fetchone()
    return bool(member and member.get("role") in {"owner", "manager"})


def require_existing_movie_ids(conn, movie_ids: list[UUID]) -> None:
    if not movie_ids:
        return
    if not table_exists(conn, "movies"):
        raise NextApiError("Movie table is not available", 503)
    with conn.cursor() as cur:
        cur.execute("SELECT id FROM movies WHERE id = ANY(%s)", (movie_ids,))
        found_ids = {row["id"] for row in cur.fetchall()}
    missing = [str(item) for item in movie_ids if item not in found_ids]
    if missing:
        raise NextApiError(f"Movie not found: {', '.join(missing)}", 404)


def container_type_for_id(conn, container_id: UUID) -> str:
    if not table_exists(conn, "containers"):
        raise NextApiError("Container table is not available", 503)
    with conn.cursor() as cur:
        cur.execute("SELECT container_type FROM containers WHERE id=%s", (container_id,))
        row = cur.fetchone()
    if not row:
        raise NextApiError("Container not found", 404)
    return str(row["container_type"] or "")


def container_types_for_ids(conn, container_ids: list[UUID]) -> dict[UUID, str]:
    if not container_ids:
        return {}
    if not table_exists(conn, "containers"):
        raise NextApiError("Container table is not available", 503)
    with conn.cursor() as cur:
        cur.execute("SELECT id, container_type FROM containers WHERE id = ANY(%s)", (container_ids,))
        rows = cur.fetchall()
    found = {row["id"]: str(row["container_type"] or "") for row in rows}
    missing = [str(item) for item in container_ids if item not in found]
    if missing:
        raise NextApiError(f"Container not found: {', '.join(missing)}", 404)
    return found


def normalize_container_type(value: Any) -> str:
    container_type = str(value or "").strip().lower().replace("-", "_").replace(" ", "_")
    if container_type not in {"box_set", "collection", "vault"}:
        raise NextApiError("containerType must be box_set, collection or vault", 400)
    return container_type


def container_payload(body: dict[str, Any], *, existing: dict[str, Any] | None = None) -> dict[str, Any]:
    existing = existing or {}
    title = clean_text(body.get("title")) if "title" in body else existing.get("title")
    if not title:
        raise NextApiError("Container title is required", 400)
    if len(title) > 240:
        raise NextApiError("Container title must be 240 characters or fewer", 400)
    description = clean_text(body.get("description")) if "description" in body else existing.get("description")
    if description and len(description) > 2000:
        raise NextApiError("Container description must be 2000 characters or fewer", 400)
    year = clean_text(body.get("year")) if "year" in body else existing.get("year")
    if year and len(year) > 40:
        raise NextApiError("Container year must be 40 characters or fewer", 400)
    barcode = clean_text(body.get("barcode")) if "barcode" in body else existing.get("barcode")
    if barcode and len(barcode) > 160:
        raise NextApiError("Container barcode must be 160 characters or fewer", 400)
    if "badgeLabel" in body or "badge_label" in body:
        badge_label = clean_text(body.get("badgeLabel", body.get("badge_label")))
    else:
        badge_label = existing.get("badge_label")
    if badge_label and len(badge_label) > 80:
        raise NextApiError("Container badge must be 80 characters or fewer", 400)
    metadata = body.get("metadata") if isinstance(body.get("metadata"), dict) else existing.get("metadata") or {}
    if "locationId" in body or "location_id" in body:
        raw_location = body.get("locationId", body.get("location_id"))
        location_id = parse_uuid(raw_location, "locationId") if raw_location else None
    else:
        location_id = existing.get("location_id")
    return {
        "title": title,
        "description": description,
        "year": year,
        "barcode": barcode,
        "badge_label": badge_label,
        "metadata": metadata,
        "location_id": location_id,
    }


# ---------------------------------------------------------------------------
# Locations (physical storage: Kast / Lade / Vak / Doos), max 4 levels deep.
# ---------------------------------------------------------------------------

LOCATION_MAX_DEPTH = 4
LOCATION_NAME_LIMIT = 240
LOCATION_DESCRIPTION_LIMIT = 2000
LOCATION_MAX_DEPTH_ERROR = "Locations can be nested at most 4 levels deep"


def location_public_id() -> str:
    return f"next-location-{uuid.uuid4().hex[:12]}"


def location_qr_token() -> str:
    return secrets.token_urlsafe(18)


def location_payload(body: dict[str, Any], *, existing: dict[str, Any] | None = None) -> dict[str, Any]:
    existing = existing or {}
    name = clean_text(body.get("name")) if "name" in body else existing.get("name")
    if not name:
        raise NextApiError("Location name is required", 400)
    if len(name) > LOCATION_NAME_LIMIT:
        raise NextApiError(f"Location name must be {LOCATION_NAME_LIMIT} characters or fewer", 400)
    if "description" in body:
        description = clean_text(body.get("description"))
    else:
        description = existing.get("description")
    if description and len(description) > LOCATION_DESCRIPTION_LIMIT:
        raise NextApiError(f"Location description must be {LOCATION_DESCRIPTION_LIMIT} characters or fewer", 400)
    return {"name": name, "description": description}


