def movie_credit_entities(conn, movie_id: UUID, *, limit: int = 80) -> list[dict[str, Any]]:
    if not table_exists(conn, "movie_credits") or not table_exists(conn, "people"):
        return []
    media_join = table_exists(conn, "media_assets")
    profile_select = (
        """
                ma.storage_backend AS profile_storage_backend,
                ma.storage_key AS profile_storage_key,
                ma.source_url AS profile_source_url
        """
        if media_join
        else """
                NULL AS profile_storage_backend,
                NULL AS profile_storage_key,
                NULL AS profile_source_url
        """
    )
    profile_join = "LEFT JOIN media_assets ma ON ma.id = p.profile_asset_id" if media_join else ""
    with conn.cursor() as cur:
        cur.execute(
            f"""
            SELECT
                mc.id,
                mc.credit_type,
                mc.character,
                mc.job,
                mc.sort_order,
                p.id AS person_id,
                p.public_id AS person_public_id,
                p.name,
                p.known_for,
                p.profile_asset_id,
                p.metadata AS person_metadata,
{profile_select}
            FROM movie_credits mc
            JOIN people p ON p.id = mc.person_id
            {profile_join}
            WHERE mc.movie_id=%s
            ORDER BY mc.sort_order, p.name
            LIMIT %s
            """,
            (movie_id, limit),
        )
        rows = [dict(row) for row in cur.fetchall()]
    for row in rows:
        profile_url = media_asset_public_url(
            {
                "id": row.get("profile_asset_id"),
                "storage_backend": row.pop("profile_storage_backend", None),
                "storage_key": row.pop("profile_storage_key", None),
                "source_url": row.pop("profile_source_url", None),
            }
        )
        metadata = row.get("person_metadata") if isinstance(row.get("person_metadata"), dict) else {}
        if not profile_url:
            profile_url = profile_metadata_image_url(metadata)
        if profile_url:
            row["profile_url"] = profile_url
    return rows


def movie_container_entities(conn, movie_id: UUID) -> list[dict[str, Any]]:
    if not table_exists(conn, "containers"):
        return []
    links: list[dict[str, Any]] = []
    if table_exists(conn, "container_movies"):
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT
                    c.id,
                    c.public_id,
                    c.container_type,
                    c.title,
                    c.barcode,
                    c.badge_label,
                    c.year,
                    c.description,
                    c.metadata,
                    cm.sort_order,
                    'member' AS relationship
                FROM container_movies cm
                JOIN containers c ON c.id = cm.container_id
                WHERE cm.movie_id=%s
                ORDER BY c.container_type, lower(c.title), cm.sort_order
                """,
                (movie_id,),
            )
            links.extend(cur.fetchall())
    if table_exists(conn, "collection_items"):
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT
                    c.id,
                    c.public_id,
                    c.container_type,
                    c.title,
                    c.barcode,
                    c.badge_label,
                    c.year,
                    c.description,
                    c.metadata,
                    ci.sort_order,
                    'collection_item' AS relationship
                FROM collection_items ci
                JOIN containers c ON c.id = ci.collection_id
                WHERE ci.item_type='movie' AND ci.item_id=%s
                ORDER BY lower(c.title), ci.sort_order
                """,
                (movie_id,),
            )
            links.extend(cur.fetchall())
    return links


def movie_media_group_entities(conn, movie_id: UUID) -> list[dict[str, Any]]:
    if not table_exists(conn, "media_group_movies") or not table_exists(conn, "media_groups"):
        return []
    with conn.cursor() as cur:
        cur.execute(
            """
            SELECT
                mg.id,
                mg.public_id,
                mg.name,
                mg.created_by,
                creator.username AS created_by_username,
                creator.display_name AS created_by_display_name,
                mg.hide_digital,
                mg.metadata,
                mgm.metadata AS link_metadata,
                mgm.created_at AS linked_at,
                mg.created_at,
                mg.updated_at,
                (
                    SELECT COUNT(*)::int
                    FROM media_group_members member_count
                    WHERE member_count.group_id = mg.id
                ) AS member_count,
                (
                    SELECT COUNT(*)::int
                    FROM media_group_movies movie_count
                    WHERE movie_count.group_id = mg.id
                ) AS movie_count
            FROM media_group_movies mgm
            JOIN media_groups mg ON mg.id = mgm.group_id
            LEFT JOIN users creator ON creator.id = mg.created_by
            WHERE mgm.movie_id=%s
            ORDER BY lower(mg.name), mgm.created_at
            """,
            (movie_id,),
        )
        return cur.fetchall()


def movie_library_action_targets(conn, movie_id: UUID, actor: dict[str, Any]) -> dict[str, Any]:
    require_existing_movie_ids(conn, [movie_id])
    can_edit_containers = actor_has_effective_permission(actor, "containers.edit")
    can_edit_collections = actor_has_any_effective_permission(actor, ("containers.edit", "collection.bulk_edit"))
    can_view_groups = actor_has_effective_permission(actor, "groups.view")
    can_manage_group_movies = actor_has_effective_permission(actor, "groups.invite")
    container_links: set[UUID] = set()
    collection_links: set[UUID] = set()
    containers_by_type: dict[str, list[dict[str, Any]]] = {"boxSets": [], "vaults": [], "collections": []}

    if table_exists(conn, "container_movies"):
        with conn.cursor() as cur:
            cur.execute("SELECT container_id FROM container_movies WHERE movie_id=%s", (movie_id,))
            container_links = {row["container_id"] for row in cur.fetchall()}
    if table_exists(conn, "collection_items"):
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT collection_id
                FROM collection_items
                WHERE item_type='movie' AND item_id=%s
                """,
                (movie_id,),
            )
            collection_links = {row["collection_id"] for row in cur.fetchall()}
    if table_exists(conn, "containers"):
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT id, public_id, container_type, title, barcode, badge_label, year,
                       description, metadata, created_at, updated_at
                FROM containers
                WHERE container_type IN ('box_set', 'vault', 'collection')
                ORDER BY container_type, lower(title), year NULLS LAST
                """
            )
            containers = cur.fetchall()
        for container in containers:
            container_type = str(container.get("container_type") or "")
            linked = container.get("id") in (collection_links if container_type == "collection" else container_links)
            target = {
                "id": container.get("id"),
                "publicId": container.get("public_id"),
                "containerType": container_type,
                "title": container.get("title"),
                "barcode": container.get("barcode"),
                "badgeLabel": container.get("badge_label"),
                "year": container.get("year"),
                "description": container.get("description"),
                "metadata": container.get("metadata") or {},
                "linked": linked,
                "canAdd": can_edit_collections if container_type == "collection" else can_edit_containers,
                "canRemove": can_edit_collections if container_type == "collection" else can_edit_containers,
                "createdAt": container.get("created_at"),
                "updatedAt": container.get("updated_at"),
            }
            if container_type == "box_set":
                containers_by_type["boxSets"].append(target)
            elif container_type == "vault":
                containers_by_type["vaults"].append(target)
            elif container_type == "collection":
                containers_by_type["collections"].append(target)

    media_groups: list[dict[str, Any]] = []
    linked_group_ids = {group.get("id") for group in movie_media_group_entities(conn, movie_id)}
    if can_view_groups and table_exists(conn, "media_groups"):
        for group in media_group_entities(conn, limit=1000):
            can_manage = can_manage_group_movies and can_manage_media_group_members(conn, group.get("id"), actor)
            media_groups.append(
                {
                    **group,
                    "linked": group.get("id") in linked_group_ids,
                    "canAdd": can_manage,
                    "canRemove": can_manage,
                }
            )

    return {
        "movieId": movie_id,
        "permissions": {
            "canAddToBoxSet": can_edit_containers,
            "canAddToVault": can_edit_containers,
            "canAddToCollection": can_edit_collections,
            "canAddToMediaGroup": can_manage_group_movies,
            "canCreateContainer": can_edit_containers,
            "canCreateMediaGroup": actor_has_effective_permission(actor, "groups.create"),
        },
        "containers": containers_by_type,
        "mediaGroups": media_groups,
    }


def attach_digital_availability(conn, rows: list[dict[str, Any]]) -> list[dict[str, Any]]:
    if not rows or not table_exists(conn, "digital_media_items") or not table_exists(conn, "digital_media_sources"):
        return rows
    ids = [row["id"] for row in rows if row.get("id")]
    if not ids:
        return rows
    with conn.cursor() as cur:
        cur.execute(
            """
            SELECT
                dmi.matched_movie_id AS movie_id,
                COUNT(DISTINCT dms.id)::int AS digital_count,
                jsonb_agg(DISTINCT jsonb_build_object(
                    'pluginId', dms.plugin_id,
                    'name', dms.name,
                    'sourceType', dms.source_type
                )) AS digital_sources
            FROM digital_media_items dmi
            JOIN digital_media_sources dms ON dms.id = dmi.source_id
            WHERE dmi.matched_movie_id = ANY(%s)
            GROUP BY dmi.matched_movie_id
            """,
            (ids,),
        )
        by_movie = {row["movie_id"]: row for row in cur.fetchall()}
    for row in rows:
        summary = by_movie.get(row.get("id")) or {}
        row["digital_count"] = int(summary.get("digital_count") or 0)
        row["digital_sources"] = summary.get("digital_sources") or row.get("digital_sources") or []
    return rows


def attach_media_group_availability(conn, rows: list[dict[str, Any]]) -> list[dict[str, Any]]:
    if not rows or not table_exists(conn, "media_group_movies") or not table_exists(conn, "media_groups"):
        return rows
    ids = [row["id"] for row in rows if row.get("id")]
    if not ids:
        return rows
    with conn.cursor() as cur:
        cur.execute(
            """
            SELECT
                mgm.movie_id,
                COUNT(DISTINCT mg.id)::int AS media_group_count,
                jsonb_agg(DISTINCT jsonb_build_object(
                    'id', mg.id,
                    'publicId', mg.public_id,
                    'name', mg.name,
                    'hideDigital', mg.hide_digital
                )) AS media_groups
            FROM media_group_movies mgm
            JOIN media_groups mg ON mg.id = mgm.group_id
            WHERE mgm.movie_id = ANY(%s)
            GROUP BY mgm.movie_id
            """,
            (ids,),
        )
        by_movie = {row["movie_id"]: row for row in cur.fetchall()}
    for row in rows:
        summary = by_movie.get(row.get("id")) or {}
        row["media_group_count"] = int(summary.get("media_group_count") or 0)
        row["media_groups"] = summary.get("media_groups") or []
    return rows


def attach_personal_list_state(conn, rows: list[dict[str, Any]], user_id: UUID | str | None) -> list[dict[str, Any]]:
    if not rows or not user_id:
        return rows
    ids = [row["id"] for row in rows if row.get("id")]
    if not ids:
        return rows
    watchlist_by_movie: dict[Any, Any] = {}
    watched_by_movie: dict[Any, Any] = {}
    if table_exists(conn, "watchlist_items"):
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT movie_id, added_at
                FROM watchlist_items
                WHERE user_id=%s AND movie_id = ANY(%s)
                """,
                (user_id, ids),
            )
            watchlist_by_movie = {row["movie_id"]: row.get("added_at") for row in cur.fetchall()}
    if table_exists(conn, "watch_history"):
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT movie_id, MAX(watched_at) AS watched_at
                FROM watch_history
                WHERE user_id=%s AND movie_id = ANY(%s)
                GROUP BY movie_id
                """,
                (user_id, ids),
            )
            watched_by_movie = {row["movie_id"]: row.get("watched_at") for row in cur.fetchall()}
    loaned_movies: set[Any] = set()
    if table_exists(conn, "loans"):
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT DISTINCT movie_id
                FROM loans
                WHERE user_id=%s AND movie_id = ANY(%s) AND returned_at IS NULL
                """,
                (user_id, ids),
            )
            loaned_movies = {row["movie_id"] for row in cur.fetchall()}
    tagged_movies: set[Any] = set()
    if table_exists(conn, "movie_tags"):
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT DISTINCT movie_id
                FROM movie_tags
                WHERE user_id=%s AND movie_id = ANY(%s)
                """,
                (user_id, ids),
            )
            tagged_movies = {row["movie_id"] for row in cur.fetchall()}
    for row in rows:
        movie_id = row.get("id")
        row["on_watchlist"] = movie_id in watchlist_by_movie
        row["watchlist_added_at"] = watchlist_by_movie.get(movie_id)
        row["last_watched"] = watched_by_movie.get(movie_id)
        row["on_loan"] = movie_id in loaned_movies
        row["has_tags"] = movie_id in tagged_movies
    return rows


def personal_list_counts(conn, user_id: UUID | str | None) -> dict[str, int]:
    if not user_id:
        return {
            "watchlist": 0,
            "watchHistory": 0,
            "watchedMovies": 0,
            "wishlist": 0,
            "tags": 0,
            "activeLoans": 0,
        }
    counts = {
        "watchlist": 0,
        "watchHistory": 0,
        "watchedMovies": 0,
        "wishlist": 0,
        "tags": 0,
        "activeLoans": 0,
    }
    if table_exists(conn, "watchlist_items"):
        with conn.cursor() as cur:
            cur.execute("SELECT COUNT(*)::int AS count FROM watchlist_items WHERE user_id=%s", (user_id,))
            counts["watchlist"] = int((cur.fetchone() or {}).get("count") or 0)
    if table_exists(conn, "watch_history"):
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT
                    COUNT(*)::int AS count,
                    COUNT(DISTINCT COALESCE(movie_id::text, snapshot->>'movie_id', snapshot->>'movie_title', snapshot->>'title'))::int AS movie_count
                FROM watch_history
                WHERE user_id=%s
                """,
                (user_id,),
            )
            row = cur.fetchone() or {}
            counts["watchHistory"] = int(row.get("count") or 0)
            counts["watchedMovies"] = int(row.get("movie_count") or 0)
    if table_exists(conn, "wishlist_items"):
        with conn.cursor() as cur:
            cur.execute("SELECT COUNT(*)::int AS count FROM wishlist_items WHERE user_id=%s", (user_id,))
            counts["wishlist"] = int((cur.fetchone() or {}).get("count") or 0)
    if table_exists(conn, "tags"):
        with conn.cursor() as cur:
            cur.execute("SELECT COUNT(*)::int AS count FROM tags WHERE user_id=%s", (user_id,))
            counts["tags"] = int((cur.fetchone() or {}).get("count") or 0)
    if table_exists(conn, "loans"):
        with conn.cursor() as cur:
            cur.execute(
                "SELECT COUNT(*)::int AS count FROM loans WHERE user_id=%s AND returned_at IS NULL",
                (user_id,),
            )
            counts["activeLoans"] = int((cur.fetchone() or {}).get("count") or 0)
    return counts


def personal_list_movie_snapshot(conn, movie_id: UUID) -> dict[str, Any]:
    detail = movie_detail_entity(conn, movie_id) or {}
    movie = detail.get("movie") or movie_entity(conn, movie_id) or {}
    metadata = movie.get("metadata") if isinstance(movie.get("metadata"), dict) else {}
    digital_items = detail.get("digitalItems") or []
    identifiers = detail.get("identifiers") or []
    poster_url = (
        movie.get("poster_url")
        or metadata.get("poster_url")
        or metadata.get("posterUrl")
        or metadata.get("poster")
    )
    backdrop_url = (
        movie.get("backdrop_url")
        or metadata.get("backdrop_url")
        or metadata.get("backdropUrl")
        or metadata.get("backdrop")
    )
    return json_ready(
        {
            "movie_id": str(movie.get("id") or movie_id),
            "public_id": movie.get("public_id"),
            "barcode": movie.get("barcode"),
            "title": movie.get("title"),
            "movie_title": movie.get("title"),
            "sort_title": movie.get("sort_title"),
            "original_title": movie.get("original_title"),
            "release_title": movie.get("release_title"),
            "releaseTitle": movie.get("release_title"),
            "year": movie.get("year"),
            "movie_year": movie.get("year"),
            "format": movie.get("format"),
            "movie_format": movie.get("format"),
            "edition": movie.get("edition"),
            "edition_type": movie.get("edition_type"),
            "poster_url": poster_url,
            "poster": poster_url,
            "backdrop_url": backdrop_url,
            "digital_sources": [
                {
                    "source_id": item.get("source_id"),
                    "source_name": item.get("source_name"),
                    "source_type": item.get("source_type"),
                    "library_name": item.get("library_name"),
                    "variant_count": item.get("variant_count"),
                }
                for item in digital_items
            ],
            "identifiers": [
                {
                    "provider_id": item.get("provider_id"),
                    "identifier_type": item.get("identifier_type"),
                    "identifier": item.get("identifier"),
                }
                for item in identifiers
            ],
        }
    )


def personal_list_snapshot_match_movie(conn, snapshot: dict[str, Any]) -> UUID | None:
    if not snapshot or not table_exists(conn, "movies"):
        return None
    barcode = clean_text(snapshot.get("barcode"))
    public_id = clean_text(snapshot.get("public_id"))
    title = clean_text(snapshot.get("title") or snapshot.get("movie_title"))
    year = clean_text(snapshot.get("year") or snapshot.get("movie_year"))
    with conn.cursor() as cur:
        if barcode:
            cur.execute("SELECT id FROM movies WHERE barcode=%s LIMIT 1", (barcode,))
            row = cur.fetchone()
            if row:
                return row["id"]
        if public_id:
            cur.execute("SELECT id FROM movies WHERE public_id=%s LIMIT 1", (public_id,))
            row = cur.fetchone()
            if row:
                return row["id"]
        identifiers = snapshot.get("identifiers") if isinstance(snapshot.get("identifiers"), list) else []
        if identifiers and table_exists(conn, "movie_identifiers"):
            for item in identifiers:
                if not isinstance(item, dict):
                    continue
                provider_id = clean_text(item.get("provider_id") or item.get("provider"))
                identifier = clean_text(item.get("identifier") or item.get("value"))
                identifier_type = clean_text(item.get("identifier_type") or item.get("identifierType")) or "movie_id"
                if not provider_id or not identifier:
                    continue
                cur.execute(
                    """
                    SELECT movie_id AS id
                    FROM movie_identifiers
                    WHERE provider_id=%s AND identifier_type=%s AND identifier=%s
                    LIMIT 1
                    """,
                    (provider_id, identifier_type, identifier),
                )
                row = cur.fetchone()
                if row:
                    return row["id"]
        if title:
            if year:
                cur.execute(
                    """
                    SELECT id
                    FROM movies
                    WHERE lower(title)=lower(%s) AND year=%s
                    ORDER BY updated_at DESC
                    LIMIT 1
                    """,
                    (title, year),
                )
            else:
                cur.execute(
                    """
                    SELECT id
                    FROM movies
                    WHERE lower(title)=lower(%s)
                    ORDER BY updated_at DESC
                    LIMIT 1
                    """,
                    (title,),
                )
            row = cur.fetchone()
            if row:
                return row["id"]
    return None


def apply_personal_list_snapshot_fallback(row: dict[str, Any]) -> dict[str, Any]:
    snapshot = row.get("snapshot") if isinstance(row.get("snapshot"), dict) else {}
    if not snapshot:
        return row
    if not row.get("title"):
        row["title"] = snapshot.get("movie_title") or snapshot.get("title")
    if not row.get("sort_title"):
        row["sort_title"] = snapshot.get("sort_title") or row.get("title")
    if not row.get("original_title"):
        row["original_title"] = snapshot.get("original_title")
    if not row.get("year"):
        row["year"] = snapshot.get("movie_year") or snapshot.get("year")
    if not row.get("format"):
        row["format"] = snapshot.get("movie_format") or snapshot.get("format")
    if not row.get("edition"):
        row["edition"] = snapshot.get("edition")
    if not row.get("edition_type"):
        row["edition_type"] = snapshot.get("edition_type")
    if not row.get("barcode"):
        row["barcode"] = snapshot.get("barcode")
    if not row.get("poster_url"):
        row["poster_url"] = snapshot.get("poster_url") or snapshot.get("poster_file") or snapshot.get("poster")
    if not row.get("backdrop_url"):
        row["backdrop_url"] = snapshot.get("backdrop_url") or snapshot.get("backdrop")
    if not row.get("digital_items") and snapshot.get("digital_sources"):
        row["digital_items"] = snapshot.get("digital_sources")
        row["digital_sources"] = snapshot.get("digital_sources")
    if not row.get("digital_sources") and snapshot.get("digitalSources"):
        row["digital_sources"] = snapshot.get("digitalSources")
    if not row.get("snapshot_format"):
        row["snapshot_format"] = snapshot.get("movie_format") or snapshot.get("format")
    if row.get("movie_exists") is None:
        row["movie_exists"] = bool(row.get("id"))
    return row


def relink_personal_list_snapshot(conn, row: dict[str, Any], *, kind: str) -> dict[str, Any]:
    if row.get("movie_exists") is not False:
        return row
    snapshot = row.get("snapshot") if isinstance(row.get("snapshot"), dict) else {}
    matched_movie_id = personal_list_snapshot_match_movie(conn, snapshot)
    if not matched_movie_id:
        return row
    row["id"] = matched_movie_id
    row["movie_id"] = matched_movie_id
    row["movie_exists"] = True
    try:
        with conn.transaction():
            with conn.cursor() as cur:
                if kind == "watchlist" and row.get("watchlist_item_id"):
                    cur.execute(
                        "SELECT id FROM watchlist_items WHERE user_id=%s AND movie_id=%s LIMIT 1",
                        (row.get("list_user_id"), matched_movie_id),
                    )
                    if not cur.fetchone():
                        cur.execute(
                            "UPDATE watchlist_items SET movie_id=%s WHERE id=%s AND movie_id IS NULL",
                            (matched_movie_id, row.get("watchlist_item_id")),
                        )
                elif kind == "watched" and row.get("watch_history_id"):
                    cur.execute(
                        "UPDATE watch_history SET movie_id=%s WHERE id=%s AND movie_id IS NULL",
                        (matched_movie_id, row.get("watch_history_id")),
                    )
    except Exception:
        current_app.logger.warning("Unable to relink personal list snapshot", exc_info=True)
    return row


def finalize_personal_list_rows(conn, rows: list[dict[str, Any]], *, kind: str) -> list[dict[str, Any]]:
    finalized: list[dict[str, Any]] = []
    for row in rows:
        with_preview = with_preview_media_urls(row)
        apply_personal_list_snapshot_fallback(with_preview)
        relink_personal_list_snapshot(conn, with_preview, kind=kind)
        apply_personal_list_snapshot_fallback(with_preview)
        finalized.append(with_preview)
    return finalized


def personal_movie_state(conn, movie_id: UUID, user_id: UUID | str | None) -> dict[str, Any]:
    state: dict[str, Any] = {
        "onWatchlist": False,
        "watchlistAddedAt": None,
        "lastWatched": None,
        "watchCount": 0,
        "history": [],
        "tags": [],
        "activeLoan": None,
        "loanRequest": None,
        "incomingLoanRequests": 0,
        "ownerUserId": None,
        "isOwnMovie": False,
        "canRequestBorrow": False,
    }
    if not user_id:
        return state
    if table_exists(conn, "watchlist_items"):
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT added_at, snapshot
                FROM watchlist_items
                WHERE user_id=%s AND movie_id=%s
                """,
                (user_id, movie_id),
            )
            row = cur.fetchone()
        if row:
            state["onWatchlist"] = True
            state["watchlistAddedAt"] = row.get("added_at")
    if table_exists(conn, "watch_history"):
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT id, watched_at, created_at
                FROM watch_history
                WHERE user_id=%s AND movie_id=%s
                ORDER BY watched_at DESC, created_at DESC
                LIMIT 50
                """,
                (user_id, movie_id),
            )
            rows = cur.fetchall()
        state["history"] = rows
        state["watchCount"] = len(rows)
        state["lastWatched"] = rows[0].get("watched_at") if rows else None
    if table_exists(conn, "movie_tags") and table_exists(conn, "tags"):
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT t.id, t.name, t.slug, t.color, mt.id AS assignment_id
                FROM movie_tags mt
                JOIN tags t ON t.id = mt.tag_id
                WHERE mt.user_id=%s AND mt.movie_id=%s
                ORDER BY t.name
                """,
                (user_id, movie_id),
            )
            tag_rows = cur.fetchall()
        state["tags"] = [
            {
                "id": str(r.get("id")),
                "name": r.get("name"),
                "slug": r.get("slug"),
                "color": r.get("color"),
                "assignmentId": str(r.get("assignment_id")),
            }
            for r in tag_rows
        ]
    if table_exists(conn, "loans"):
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT id, movie_id, snapshot, borrower_name, borrower_user_id,
                       loaned_at, due_at, returned_at, note, created_at
                FROM loans
                WHERE user_id=%s AND movie_id=%s AND returned_at IS NULL
                ORDER BY loaned_at DESC
                LIMIT 1
                """,
                (user_id, movie_id),
            )
            loan_row = cur.fetchone()
        if loan_row:
            state["activeLoan"] = _loan_row_entity(loan_row)
    if table_exists(conn, "loan_requests"):
        request_state = personal_movie_loan_request_state(conn, movie_id, user_id)
        state["loanRequest"] = request_state.get("outgoing")
        state["incomingLoanRequests"] = request_state.get("incomingPending") or 0
    # Authoritative ownership / borrow-eligibility flags. The frontend cannot rely on
    # a bare owner_id comparison because movies created via the sync/import path carry
    # a NULL owner_id, which would make every viewer look like the owner. Compute the
    # decision here where group membership is known.
    actor = {"id": user_id}
    owner_id = resolve_movie_owner_id(conn, movie_id, viewer_id=user_id)
    state["ownerUserId"] = str(owner_id) if owner_id else None
    state["isOwnMovie"] = bool(owner_id) and str(owner_id) == str(user_id)
    state["canRequestBorrow"] = movie_borrowable_from_other(conn, actor, movie_id)
    return state


def watchlist_sync_entity(conn, user_id, movie_id) -> dict[str, Any] | None:
    """Serialize one watchlist row for the per-user sync stream, or None."""
    if not table_exists(conn, "watchlist_items"):
        return None
    with conn.cursor() as cur:
        cur.execute(
            """
            SELECT movie_id, added_at, snapshot
            FROM watchlist_items
            WHERE user_id=%s AND movie_id=%s
            """,
            (user_id, movie_id),
        )
        row = cur.fetchone()
    if not row:
        return None
    movie = row.get("movie_id")
    return {
        "movieId": str(movie) if movie else None,
        "addedAt": row.get("added_at"),
        "snapshot": row.get("snapshot") or {},
    }


