def movie_owner_id(conn, movie_id: UUID) -> UUID | None:
    """Return the owner_id for a movie, or None when the movie/column is absent."""
    if not table_exists(conn, "movies"):
        return None
    with conn.cursor() as cur:
        cur.execute("SELECT owner_id FROM movies WHERE id=%s", (movie_id,))
        row = cur.fetchone()
    return row.get("owner_id") if row else None


def resolve_movie_owner_id(conn, movie_id: UUID, *, viewer_id: Any = None) -> UUID | None:
    """Best-effort owner of a movie for lending / borrow-request attribution.

    Prefers the explicit ``movies.owner_id``. When that is NULL -- e.g. discs created
    via the device sync/import path, which runs without an authenticated actor and so
    never stamps an owner -- fall back to the person who shared the disc into a media
    group: the per-share ``added_by`` recorded in ``media_group_movies.metadata`` when
    present, otherwise the group's ``created_by``. Groups the viewer belongs to are
    preferred so a borrow request is routed to a collection the viewer can actually
    see. Returns None only when no owner can be attributed at all.
    """
    owner = movie_owner_id(conn, movie_id)
    if owner is not None:
        return owner
    if not table_exists(conn, "media_group_movies") or not table_exists(conn, "media_groups"):
        return None
    with conn.cursor() as cur:
        cur.execute(
            """
            SELECT mgm.metadata->>'added_by' AS added_by,
                   g.created_by            AS created_by
            FROM media_group_movies mgm
            JOIN media_groups g ON g.id = mgm.group_id
            LEFT JOIN media_group_members mem
                ON mem.group_id = mgm.group_id AND mem.user_id = %s
            WHERE mgm.movie_id = %s
            ORDER BY (mem.user_id IS NOT NULL) DESC, mgm.created_at ASC
            """,
            (viewer_id, movie_id),
        )
        rows = cur.fetchall() or []
    for row in rows:
        added_by = row.get("added_by")
        if added_by:
            try:
                return added_by if isinstance(added_by, UUID) else UUID(str(added_by))
            except (ValueError, AttributeError, TypeError):
                pass
        created_by = row.get("created_by")
        if created_by:
            try:
                return created_by if isinstance(created_by, UUID) else UUID(str(created_by))
            except (ValueError, AttributeError, TypeError):
                pass
    return None


def movie_borrowable_from_other(conn, actor: dict[str, Any] | None, movie_id: UUID) -> bool:
    """True when the actor can see this movie via a shared group but is NOT its owner.

    This is the predicate for showing the "Ask to borrow" control instead of the
    owner-only "Lend" form: you cannot lend someone else's disc, so a group member
    viewing another member's movie may raise a borrow request instead. Ownership is
    resolved authoritatively (see ``resolve_movie_owner_id``) so a NULL-owner disc
    whose group the actor created is correctly treated as the actor's own.
    """
    actor_id = (actor or {}).get("id")
    if not actor_id:
        return False
    owner = resolve_movie_owner_id(conn, movie_id, viewer_id=actor_id)
    if owner is not None and str(owner) == str(actor_id):
        return False
    return movie_is_shared_with_actor(conn, actor, movie_id)


def _loan_request_row_entity(row: dict[str, Any]) -> dict[str, Any]:
    movie = row.get("movie_id")
    requester = row.get("requester_user_id")
    owner = row.get("owner_user_id")
    resulting_loan = row.get("resulting_loan_id")
    borrow_from = row.get("borrow_from")
    return_by = row.get("return_by")
    decided_at = row.get("decided_at")
    return {
        "id": str(row.get("id")),
        "movieId": str(movie) if movie else None,
        "snapshot": row.get("snapshot") or {},
        "requesterUserId": str(requester) if requester else None,
        "requesterDisplayName": (
            row.get("requester_display_name") or row.get("requester_username") or None
        ),
        "requesterUsername": row.get("requester_username"),
        "ownerUserId": str(owner) if owner else None,
        "ownerDisplayName": row.get("owner_display_name") or row.get("owner_username") or None,
        "ownerUsername": row.get("owner_username"),
        "borrowFrom": borrow_from.isoformat() if hasattr(borrow_from, "isoformat") else borrow_from,
        "returnBy": return_by.isoformat() if hasattr(return_by, "isoformat") else return_by,
        "status": row.get("status"),
        "note": row.get("note"),
        "resultingLoanId": str(resulting_loan) if resulting_loan else None,
        "decidedAt": decided_at,
        "createdAt": row.get("created_at"),
        "updatedAt": row.get("updated_at"),
    }


def _loan_request_select(join_users: bool) -> tuple[str, str]:
    """Return (extra_select, joins) that resolve requester/owner display names."""
    if not join_users:
        extra = (
            "NULL AS requester_username, NULL AS requester_display_name, "
            "NULL AS owner_username, NULL AS owner_display_name"
        )
        return extra, ""
    extra = (
        "requester.username AS requester_username, "
        "requester.display_name AS requester_display_name, "
        "owner.username AS owner_username, "
        "owner.display_name AS owner_display_name"
    )
    joins = (
        "LEFT JOIN users requester ON requester.id = lr.requester_user_id "
        "LEFT JOIN users owner ON owner.id = lr.owner_user_id"
    )
    return extra, joins


def loan_request_entity(conn, request_id: UUID) -> dict[str, Any] | None:
    if not table_exists(conn, "loan_requests"):
        return None
    extra, joins = _loan_request_select(table_exists(conn, "users"))
    with conn.cursor() as cur:
        cur.execute(
            f"""
            SELECT lr.id, lr.movie_id, lr.requester_user_id, lr.owner_user_id, lr.snapshot,
                   lr.borrow_from, lr.return_by, lr.status, lr.note, lr.resulting_loan_id,
                   lr.decided_at, lr.created_at, lr.updated_at,
                   {extra}
            FROM loan_requests lr
            {joins}
            WHERE lr.id=%s
            """,
            (request_id,),
        )
        row = cur.fetchone()
    return _loan_request_row_entity(row) if row else None


def all_loan_requests(conn, user_id: UUID | str, *, role: str = "incoming") -> list[dict[str, Any]]:
    """List loan requests where the user is the owner ('incoming') or requester ('outgoing')."""
    if not user_id or not table_exists(conn, "loan_requests"):
        return []
    column = "owner_user_id" if role == "incoming" else "requester_user_id"
    extra, joins = _loan_request_select(table_exists(conn, "users"))
    with conn.cursor() as cur:
        cur.execute(
            f"""
            SELECT lr.id, lr.movie_id, lr.requester_user_id, lr.owner_user_id, lr.snapshot,
                   lr.borrow_from, lr.return_by, lr.status, lr.note, lr.resulting_loan_id,
                   lr.decided_at, lr.created_at, lr.updated_at,
                   {extra}
            FROM loan_requests lr
            {joins}
            WHERE lr.{column}=%s
            ORDER BY
                CASE WHEN lr.status='pending' THEN 0 ELSE 1 END,
                lr.created_at DESC
            """,
            (user_id,),
        )
        rows = cur.fetchall()
    return [_loan_request_row_entity(row) for row in rows]


def personal_movie_loan_request_state(
    conn, movie_id: UUID, user_id: UUID | str | None
) -> dict[str, Any]:
    """Borrow-request state for the movie-detail panel of a given viewer."""
    state: dict[str, Any] = {"outgoing": None, "incomingPending": 0}
    if not user_id or not table_exists(conn, "loan_requests"):
        return state
    extra, joins = _loan_request_select(table_exists(conn, "users"))
    with conn.cursor() as cur:
        cur.execute(
            f"""
            SELECT lr.id, lr.movie_id, lr.requester_user_id, lr.owner_user_id, lr.snapshot,
                   lr.borrow_from, lr.return_by, lr.status, lr.note, lr.resulting_loan_id,
                   lr.decided_at, lr.created_at, lr.updated_at,
                   {extra}
            FROM loan_requests lr
            {joins}
            WHERE lr.movie_id=%s AND lr.requester_user_id=%s
            ORDER BY lr.created_at DESC
            LIMIT 1
            """,
            (movie_id, user_id),
        )
        outgoing = cur.fetchone()
    if outgoing:
        state["outgoing"] = _loan_request_row_entity(outgoing)
    with conn.cursor() as cur:
        cur.execute(
            """
            SELECT COUNT(*)::int AS count
            FROM loan_requests
            WHERE movie_id=%s AND owner_user_id=%s AND status='pending'
            """,
            (movie_id, user_id),
        )
        state["incomingPending"] = int((cur.fetchone() or {}).get("count") or 0)
    return state


def create_loan_from_request(conn, request_row: dict[str, Any], actor: dict[str, Any] | None) -> UUID | None:
    """Materialize an outbound loan from an approved borrow request.

    The owner becomes the lender (loans.user_id), the requester the borrower, and
    the requested return date becomes the loan due date. Returns the new loan id.
    """
    if not table_exists(conn, "loans"):
        return None
    owner_id = request_row.get("owner_user_id")
    requester_id = request_row.get("requester_user_id")
    movie_id = request_row.get("movie_id")
    snapshot = request_row.get("snapshot") or {}
    return_by = request_row.get("return_by")
    created_by = (actor or {}).get("id") or owner_id
    with conn.cursor() as cur:
        cur.execute(
            """
            INSERT INTO loans
                (user_id, movie_id, snapshot, borrower_user_id, due_at, created_by_user_id)
            VALUES (%s, %s, %s, %s, %s, %s)
            RETURNING id
            """,
            (owner_id, movie_id, Jsonb(snapshot), requester_id, return_by, created_by),
        )
        loan_id = (cur.fetchone() or {}).get("id")
    if loan_id is not None:
        emit_loan_change(conn, owner_id, loan_id, operation="upsert", movie_id=movie_id)
    return loan_id


def personal_list_movie_entities(conn, user_id: UUID | str, *, kind: str, limit: int = 200) -> list[dict[str, Any]]:
    if not user_id or not table_exists(conn, "movies"):
        return []
    limit = min(max(int(limit or 200), 1), 500)
    media_join = table_exists(conn, "entity_media") and table_exists(conn, "media_assets")
    poster_select = (
        """
                poster_asset.id AS poster_asset_id,
                poster_asset.storage_backend AS poster_asset_storage_backend,
                poster_asset.storage_key AS poster_asset_storage_key,
                poster_asset.source_url AS poster_asset_source_url,
                backdrop_asset.id AS backdrop_asset_id,
                backdrop_asset.storage_backend AS backdrop_asset_storage_backend,
                backdrop_asset.storage_key AS backdrop_asset_storage_key,
                backdrop_asset.source_url AS backdrop_asset_source_url,
        """
        if media_join
        else """
                NULL AS poster_asset_id,
                NULL AS poster_asset_storage_backend,
                NULL AS poster_asset_storage_key,
                NULL AS poster_asset_source_url,
                NULL AS backdrop_asset_id,
                NULL AS backdrop_asset_storage_backend,
                NULL AS backdrop_asset_storage_key,
                NULL AS backdrop_asset_source_url,
        """
    )
    poster_join = (
        """
            LEFT JOIN LATERAL (
                SELECT ma.id, ma.storage_backend, ma.storage_key, ma.source_url
                FROM entity_media em
                JOIN media_assets ma ON ma.id = em.media_id
                WHERE em.entity_type='movie'
                  AND em.entity_id=m.id
                  AND em.deleted_at IS NULL
                  AND ma.kind='poster'
                ORDER BY em.is_primary DESC, em.sort_order, ma.created_at
                LIMIT 1
            ) poster_asset ON true
            LEFT JOIN LATERAL (
                SELECT ma.id, ma.storage_backend, ma.storage_key, ma.source_url
                FROM entity_media em
                JOIN media_assets ma ON ma.id = em.media_id
                WHERE em.entity_type='movie'
                  AND em.entity_id=m.id
                  AND em.deleted_at IS NULL
                  AND ma.kind='backdrop'
                ORDER BY em.is_primary DESC, em.sort_order, ma.created_at
                LIMIT 1
            ) backdrop_asset ON true
        """
        if media_join
        else ""
    )
    base_select = f"""
                m.id,
                m.public_id,
                m.barcode,
                m.title,
                m.sort_title,
                m.original_title,
                m.year,
                m.format,
                m.edition,
                m.edition_type,
                m.metadata,
                m.metadata->>'poster_url' AS poster_url,
                m.metadata->>'backdrop_url' AS backdrop_url,
{poster_select}
                m.created_at,
                m.updated_at
    """
    if kind == "watchlist":
        if not table_exists(conn, "watchlist_items"):
            return []
        with conn.cursor() as cur:
            cur.execute(
                f"""
                SELECT
                    w.id AS watchlist_item_id,
                    w.user_id AS list_user_id,
                    w.movie_id AS list_movie_id,
                    w.snapshot,
{base_select},
                    w.added_at AS watchlist_added_at,
                    true AS on_watchlist,
                    latest.watched_at AS last_watched,
                    m.id IS NOT NULL AS movie_exists
                FROM watchlist_items w
                LEFT JOIN movies m ON m.id = w.movie_id
                {poster_join}
                LEFT JOIN LATERAL (
                    SELECT MAX(watched_at) AS watched_at
                    FROM watch_history wh
                    WHERE wh.user_id=w.user_id AND wh.movie_id=w.movie_id
                ) latest ON true
                WHERE w.user_id=%s
                ORDER BY w.added_at DESC
                LIMIT %s
                """,
                (user_id, limit),
            )
            rows = finalize_personal_list_rows(conn, cur.fetchall(), kind="watchlist")
        return attach_movie_search_credits(
            conn,
            attach_media_group_availability(conn, attach_digital_availability(conn, rows)),
        )
    if kind == "watched":
        if not table_exists(conn, "watch_history"):
            return []
        with conn.cursor() as cur:
            cur.execute(
                f"""
                SELECT
                    wh.id AS watch_history_id,
                    wh.user_id AS list_user_id,
                    wh.movie_id AS list_movie_id,
                    wh.watched_at,
                    wh.created_at AS watch_history_created_at,
                    wh.snapshot,
{base_select},
                    EXISTS (
                        SELECT 1 FROM watchlist_items w
                        WHERE w.user_id=wh.user_id AND w.movie_id=wh.movie_id
                    ) AS on_watchlist,
                    wh.watched_at AS last_watched,
                    m.id IS NOT NULL AS movie_exists
                FROM watch_history wh
                LEFT JOIN movies m ON m.id = wh.movie_id
                {poster_join}
                WHERE wh.user_id=%s
                ORDER BY wh.watched_at DESC, wh.created_at DESC
                LIMIT %s
                """,
                (user_id, limit),
            )
            rows = finalize_personal_list_rows(conn, cur.fetchall(), kind="watched")
        return attach_movie_search_credits(conn, attach_media_group_availability(conn, attach_digital_availability(conn, rows)))
    return []


def movie_digital_item_entities(conn, movie_id: UUID) -> list[dict[str, Any]]:
    if not table_exists(conn, "digital_media_items") or not table_exists(conn, "digital_media_sources"):
        return []
    with conn.cursor() as cur:
        cur.execute(
            """
            WITH ranked AS (
                SELECT
                    dmi.id,
                    dmi.external_id,
                    dmi.media_type,
                    dmi.title,
                    dmi.year,
                    dmi.tmdb_id,
                    dmi.imdb_id,
                    dmi.playback_url,
                    dmi.metadata,
                    dmi.synced_at,
                    dms.plugin_id,
                    dms.name AS source_name,
                    dms.source_type,
                    dms.base_url,
                    COUNT(*) OVER (
                        PARTITION BY dms.id, dmi.matched_movie_id
                    )::int AS variant_count,
                    ROW_NUMBER() OVER (
                        PARTITION BY dms.id, dmi.matched_movie_id
                        ORDER BY
                            CASE
                                WHEN dmi.playback_url IS NULL OR dmi.playback_url = '' THEN 1
                                ELSE 0
                            END,
                            dmi.synced_at DESC,
                            dmi.title,
                            dmi.external_id
                    ) AS source_rank
                FROM digital_media_items dmi
                JOIN digital_media_sources dms ON dms.id = dmi.source_id
                WHERE dmi.matched_movie_id=%s
            )
            SELECT
                id,
                external_id,
                media_type,
                title,
                year,
                tmdb_id,
                imdb_id,
                playback_url,
                metadata,
                synced_at,
                plugin_id,
                source_name,
                source_type,
                base_url,
                variant_count
            FROM ranked
            WHERE source_rank = 1
            ORDER BY source_name, title
            """,
            (movie_id,),
        )
        return cur.fetchall()


def digital_source_entities(conn) -> list[dict[str, Any]]:
    if not table_exists(conn, "digital_media_sources"):
        return []
    with conn.cursor() as cur:
        cur.execute(
            """
            SELECT
                dms.id,
                dms.plugin_id,
                dms.name,
                dms.source_type,
                dms.base_url,
                dms.machine_id,
                dms.enabled,
                dms.last_synced_at,
                dms.item_count,
                dms.last_status,
                dms.last_error,
                dms.metadata,
                dms.created_at,
                dms.updated_at,
                COUNT(dmi.id)::int AS stored_item_count,
                COUNT(dmi.matched_movie_id)::int AS matched_item_count
            FROM digital_media_sources dms
            LEFT JOIN digital_media_items dmi ON dmi.source_id = dms.id
            GROUP BY dms.id
            ORDER BY lower(dms.name), dms.plugin_id
            """
        )
        rows = []
        for row in cur.fetchall():
            row["itemCount"] = int(row.get("stored_item_count") or row.get("item_count") or 0)
            row["matchedItemCount"] = int(row.get("matched_item_count") or 0)
            rows.append(row)
        return rows


def media_group_entities(conn, *, limit: int = 200, actor: dict[str, Any] | None = None) -> list[dict[str, Any]]:
    if not table_exists(conn, "media_groups"):
        return []
    params: list[Any] = []
    where = ""
    if actor and not actor_has_any_permission(actor, ("collection.view_all", "groups.view_all", "groups.manage", "users.view")):
        actor_id = actor.get("id")
        if not actor_id:
            return []
        where = """
            WHERE mg.created_by=%s
               OR EXISTS (
                    SELECT 1
                    FROM media_group_members scope_mgm
                    WHERE scope_mgm.group_id=mg.id
                      AND scope_mgm.user_id=%s
               )
        """
        params.extend([actor_id, actor_id])
    with conn.cursor() as cur:
        cur.execute(
            f"""
            SELECT
                mg.id,
                mg.public_id,
                mg.name,
                mg.created_by,
                creator.username AS created_by_username,
                creator.display_name AS created_by_display_name,
                mg.hide_digital,
                mg.metadata,
                mg.created_at,
                mg.updated_at,
                (
                    SELECT COUNT(*)::int
                    FROM media_group_members mgm
                    WHERE mgm.group_id = mg.id
                ) AS member_count,
                (
                    SELECT COUNT(*)::int
                    FROM media_group_movies mgmv
                    WHERE mgmv.group_id = mg.id
                ) AS movie_count,
                (
                    SELECT COUNT(*)::int
                    FROM media_group_invites mgi
                    WHERE mgi.group_id = mg.id AND mgi.status = 'pending'
                ) AS pending_invite_count
            FROM media_groups mg
            LEFT JOIN users creator ON creator.id = mg.created_by
            {where}
            ORDER BY lower(mg.name), mg.created_at
            LIMIT %s
            """,
            (*params, limit),
        )
        groups = cur.fetchall()
    if not groups or not table_exists(conn, "media_group_members") or not table_exists(conn, "users"):
        return groups

    group_ids = [group["id"] for group in groups]
    members_by_group: dict[str, list[dict[str, Any]]] = {str(group_id): [] for group_id in group_ids}
    with conn.cursor() as cur:
        cur.execute(
            """
            SELECT
                mgm.group_id,
                mgm.user_id,
                mgm.role,
                mgm.created_at,
                u.username,
                u.display_name,
                u.status
            FROM media_group_members mgm
            JOIN users u ON u.id = mgm.user_id
            WHERE mgm.group_id = ANY(%s)
            ORDER BY lower(u.username)
            """,
            (group_ids,),
        )
        for member in cur.fetchall():
            members_by_group.setdefault(str(member["group_id"]), []).append(member)
    for group in groups:
        group["members"] = members_by_group.get(str(group["id"]), [])
    return groups


def media_group_movie_entities(
    conn,
    group_id: UUID,
    *,
    limit: int = 200,
    actor: dict[str, Any] | None = None,
) -> list[dict[str, Any]]:
    if not table_exists(conn, "media_group_movies") or not table_exists(conn, "movies"):
        return []
    visibility_where, visibility_params = visible_movie_where_sql(conn, actor, "m") if actor else ("TRUE", [])
    if table_exists(conn, "entity_media") and table_exists(conn, "media_assets"):
        with conn.cursor() as cur:
            cur.execute(
                f"""
                SELECT
                    m.id,
                    m.public_id,
                    m.barcode,
                    m.title,
                    m.sort_title,
                    m.original_title,
                    m.year,
                    m.format,
                    m.edition,
                    COALESCE(m.metadata->>'poster_url', poster_asset.source_url) AS poster_url,
                    COALESCE(m.metadata->>'backdrop_url', backdrop_asset.source_url) AS backdrop_url,
                    poster_asset.id AS poster_asset_id,
                    poster_asset.storage_backend AS poster_asset_storage_backend,
                    poster_asset.storage_key AS poster_asset_storage_key,
                    poster_asset.source_url AS poster_asset_source_url,
                    backdrop_asset.id AS backdrop_asset_id,
                    backdrop_asset.storage_backend AS backdrop_asset_storage_backend,
                    backdrop_asset.storage_key AS backdrop_asset_storage_key,
                    backdrop_asset.source_url AS backdrop_asset_source_url,
                    mgm.metadata AS group_metadata,
                    mgm.created_at AS group_linked_at,
                    mgm.updated_at AS group_updated_at,
                    m.created_at,
                    m.updated_at
                FROM media_group_movies mgm
                JOIN movies m ON m.id = mgm.movie_id
                LEFT JOIN LATERAL (
                    SELECT ma.id, ma.storage_backend, ma.storage_key, ma.source_url
                    FROM entity_media em
                    JOIN media_assets ma ON ma.id = em.media_id
                    WHERE em.entity_type='movie'
                  AND em.entity_id=m.id
                  AND em.deleted_at IS NULL
                  AND ma.kind='poster'
                    ORDER BY em.is_primary DESC, em.sort_order, ma.created_at
                    LIMIT 1
                ) poster_asset ON true
                LEFT JOIN LATERAL (
                    SELECT ma.id, ma.storage_backend, ma.storage_key, ma.source_url
                    FROM entity_media em
                    JOIN media_assets ma ON ma.id = em.media_id
                    WHERE em.entity_type='movie'
                  AND em.entity_id=m.id
                  AND em.deleted_at IS NULL
                  AND ma.kind='backdrop'
                    ORDER BY em.is_primary DESC, em.sort_order, ma.created_at
                    LIMIT 1
                ) backdrop_asset ON true
                WHERE mgm.group_id=%s
                  AND {visibility_where}
                ORDER BY lower(COALESCE(m.sort_title, m.title)), m.year NULLS LAST
                LIMIT %s
                """,
                (group_id, *visibility_params, limit),
            )
            rows = [with_preview_media_urls(row) for row in cur.fetchall()]
    else:
        with conn.cursor() as cur:
            cur.execute(
                f"""
                SELECT
                    m.id,
                    m.public_id,
                    m.barcode,
                    m.title,
                    m.sort_title,
                    m.original_title,
                    m.year,
                    m.format,
                    m.edition,
                    m.metadata->>'poster_url' AS poster_url,
                    m.metadata->>'backdrop_url' AS backdrop_url,
                    mgm.metadata AS group_metadata,
                    mgm.created_at AS group_linked_at,
                    mgm.updated_at AS group_updated_at,
                    m.created_at,
                    m.updated_at
                FROM media_group_movies mgm
                JOIN movies m ON m.id = mgm.movie_id
                WHERE mgm.group_id=%s
                  AND {visibility_where}
                ORDER BY lower(COALESCE(m.sort_title, m.title)), m.year NULLS LAST
                LIMIT %s
                """,
                (group_id, *visibility_params, limit),
            )
            rows = cur.fetchall()
    return attach_media_group_availability(conn, attach_digital_availability(conn, rows))


def media_group_detail_entity(conn, group_id: UUID, actor: dict[str, Any] | None = None) -> dict[str, Any] | None:
    if not table_exists(conn, "media_groups"):
        return None
    if actor and not actor_can_view_media_group(conn, actor, group_id):
        return None
    with conn.cursor() as cur:
        cur.execute(
            """
            SELECT
                mg.id,
                mg.public_id,
                mg.name,
                mg.created_by,
                creator.username AS created_by_username,
                creator.display_name AS created_by_display_name,
                mg.hide_digital,
                mg.metadata,
                mg.created_at,
                mg.updated_at,
                (
                    SELECT COUNT(*)::int
                    FROM media_group_members mgm
                    WHERE mgm.group_id = mg.id
                ) AS member_count,
                (
                    SELECT COUNT(*)::int
                    FROM media_group_movies mgmv
                    WHERE mgmv.group_id = mg.id
                ) AS movie_count,
                (
                    SELECT COUNT(*)::int
                    FROM media_group_invites mgi
                    WHERE mgi.group_id = mg.id AND mgi.status = 'pending'
                ) AS pending_invite_count
            FROM media_groups mg
            LEFT JOIN users creator ON creator.id = mg.created_by
            WHERE mg.id=%s
            """,
            (group_id,),
        )
        group = cur.fetchone()
    if not group:
        return None
    group["members"] = []
    if table_exists(conn, "media_group_members") and table_exists(conn, "users"):
        with conn.cursor() as cur:
            cur.execute(
                """
                SELECT
                    mgm.user_id,
                    mgm.role,
                    mgm.created_at,
                    u.username,
                    u.display_name,
                    u.status
                FROM media_group_members mgm
                JOIN users u ON u.id = mgm.user_id
                WHERE mgm.group_id=%s
                ORDER BY lower(u.username)
                """,
                (group_id,),
            )
            group["members"] = cur.fetchall()
    group["movies"] = media_group_movie_entities(conn, group_id, limit=500, actor=actor)
    return group


