    @flask_app.post("/api/next/containers")
    def create_container():
        body = request.get_json(silent=True) or {}
        if not isinstance(body, dict):
            raise NextApiError("Container request body must be an object", 400)
        container_type = normalize_container_type(body.get("containerType", body.get("container_type")))
        payload = container_payload(body)
        container_uuid = uuid.uuid4()
        public_id = clean_text(body.get("publicId") or body.get("public_id")) or f"next-container-{container_uuid.hex[:12]}"
        if len(public_id) > 160:
            raise NextApiError("publicId must be 160 characters or fewer", 400)
        with connect() as conn:
            actor = require_next_permission(conn, "containers.edit")
            if not table_exists(conn, "containers"):
                raise NextApiError("Container table is not available", 503)
            with conn.transaction():
                with conn.cursor() as cur:
                    cur.execute("SELECT id FROM containers WHERE public_id=%s", (public_id,))
                    if cur.fetchone():
                        raise NextApiError("A container with this public id already exists", 409)
                    if container_type == "box_set" and payload["barcode"]:
                        cur.execute(
                            "SELECT id FROM containers WHERE barcode=%s AND container_type='box_set' LIMIT 1",
                            (payload["barcode"],),
                        )
                        if cur.fetchone():
                            raise NextApiError("A box-set with this barcode already exists", 409)
                    cur.execute(
                        """
                        INSERT INTO containers (
                            id, public_id, container_type, title, barcode, badge_label, year, description, location_id, metadata, created_at, updated_at
                        )
                        VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, now(), now())
                        """,
                        (
                            container_uuid,
                            public_id,
                            container_type,
                            payload["title"],
                            payload["barcode"],
                            payload["badge_label"],
                            payload["year"],
                            payload["description"],
                            payload["location_id"],
                            Jsonb(json_ready(payload["metadata"])),
                        ),
                    )
                audit_event(
                    conn,
                    event_type="container.created",
                    category="admin",
                    actor=actor,
                    target_type="container",
                    target_id=container_uuid,
                    summary=f"Created {container_type} {payload['title']}",
                    metadata={
                        "containerType": container_type,
                        "publicId": public_id,
                        "title": payload["title"],
                        "barcode": payload["barcode"],
                        "year": payload["year"],
                        "badgeLabel": payload["badge_label"],
                    },
                )
                emit_container_change(conn, container_uuid, operation="upsert")
            detail = container_detail_entity(conn, container_uuid)
        return response({"status": "ok", "detail": detail}, 201)

    @flask_app.patch("/api/next/containers/<container_id>")
    def update_container(container_id: str):
        container_uuid = parse_uuid(container_id, "containerId")
        if not container_uuid:
            raise NextApiError("containerId is required", 400)
        body = request.get_json(silent=True) or {}
        if not isinstance(body, dict):
            raise NextApiError("Container request body must be an object", 400)
        with connect() as conn:
            actor = require_next_permission(conn, "containers.edit")
            existing = container_entity(conn, container_uuid)
            if not existing:
                raise NextApiError("Container not found", 404)
            payload = container_payload(body, existing=existing)
            primary_provided = "primaryMovieId" in body or "primary_movie_id" in body
            primary_movie_uuid = None
            if primary_provided:
                raw_primary = body.get("primaryMovieId", body.get("primary_movie_id"))
                if raw_primary in (None, "", False):
                    primary_movie_uuid = None
                else:
                    primary_movie_uuid = parse_uuid(raw_primary, "primaryMovieId")
                    if not primary_movie_uuid:
                        raise NextApiError("primaryMovieId must be a valid movie id", 400)
                    if not table_exists(conn, "container_movies"):
                        raise NextApiError("Container members are not available", 503)
                    with conn.cursor() as cur:
                        cur.execute(
                            "SELECT 1 FROM container_movies WHERE container_id=%s AND movie_id=%s LIMIT 1",
                            (container_uuid, primary_movie_uuid),
                        )
                        if not cur.fetchone():
                            raise NextApiError("Cover movie must be a member of this box-set", 400)
            receiver_payload = container_receiver_payload(conn, existing, payload)
            receiver_summary: dict[str, Any] = {"skipped": True, "reason": "no_receiver_fields_changed"}
            with conn.transaction():
                with conn.cursor() as cur:
                    cur.execute(
                        """
                        UPDATE containers
                        SET title=%s,
                            barcode=%s,
                            badge_label=%s,
                            year=%s,
                            description=%s,
                            location_id=%s,
                            metadata=%s,
                            updated_at=now()
                        WHERE id=%s
                        """,
                        (
                            payload["title"],
                            payload["barcode"],
                            payload["badge_label"],
                            payload["year"],
                            payload["description"],
                            payload["location_id"],
                            Jsonb(json_ready(payload["metadata"])),
                            container_uuid,
                        ),
                    )
                if primary_provided:
                    with conn.cursor() as cur:
                        cur.execute(
                            "UPDATE containers SET primary_movie_id=%s, updated_at=now() WHERE id=%s",
                            (primary_movie_uuid, container_uuid),
                        )
                audit_event(
                    conn,
                    event_type="container.updated",
                    category="admin",
                    actor=actor,
                    target_type="container",
                    target_id=container_uuid,
                    summary=f"Updated container {payload['title']}",
                    metadata={
                        "containerType": existing.get("container_type"),
                        "publicId": existing.get("public_id"),
                        "title": payload["title"],
                        "previousTitle": existing.get("title"),
                        "barcode": payload["barcode"],
                        "previousBarcode": existing.get("barcode"),
                        "year": payload["year"],
                        "badgeLabel": payload["badge_label"],
                    },
                )
                if receiver_payload:
                    try:
                        receiver_summary = push_receiver_payload_to_receivers(conn, payload=receiver_payload, actor=actor)
                    except Exception as exc:
                        receiver_summary = {"status": "error", "error": str(exc)}
                    audit_event(
                        conn,
                        event_type="metadata.receiver_pushed",
                        category="metadata",
                        actor=actor,
                        target_type="container",
                        target_id=container_uuid,
                        summary=f"Pushed box-set edit to receiver plugins for {payload['title']}",
                        metadata={
                            "containerType": existing.get("container_type"),
                            "title": payload["title"],
                            "barcode": payload["barcode"],
                            "changedFields": (receiver_payload.get("metadata") or {}).get("changedFields") or [],
                            "receiverSummary": receiver_summary,
                        },
                    )
                emit_container_change(conn, container_uuid, operation="upsert")
            detail = container_detail_entity(conn, container_uuid)
        return response({"status": "ok", "detail": detail, "receiverSummary": receiver_summary})

    @flask_app.put("/api/next/containers/<container_id>/artwork-locks")
    def set_container_artwork_locks(container_id: str):
        container_uuid = parse_uuid(container_id, "containerId")
        if not container_uuid:
            raise NextApiError("containerId is required", 400)
        body = request.get_json(silent=True) or {}
        if not isinstance(body, dict):
            raise NextApiError("Artwork lock request body must be an object", 400)
        updates: dict[str, bool] = {}
        alias = {
            "poster": "poster_locked",
            "posterLocked": "poster_locked",
            "poster_locked": "poster_locked",
            "backdrop": "backdrop_locked",
            "backdropLocked": "backdrop_locked",
            "backdrop_locked": "backdrop_locked",
        }
        for key, value in body.items():
            target = alias.get(key)
            if not target:
                continue
            updates[target] = bool(value)
        if not updates:
            raise NextApiError("No poster/backdrop lock values provided", 400)
        with connect() as conn:
            actor = require_next_permission(conn, "containers.edit")
            existing = container_entity(conn, container_uuid)
            if not existing:
                raise NextApiError("Container not found", 404)
            with conn.transaction():
                with conn.cursor() as cur:
                    cur.execute(
                        "UPDATE containers SET metadata=COALESCE(metadata, '{}'::jsonb) || %s, updated_at=now() WHERE id=%s",
                        (Jsonb(json_ready(updates)), container_uuid),
                    )
                audit_event(
                    conn,
                    event_type="container.updated",
                    category="admin",
                    actor=actor,
                    target_type="container",
                    target_id=container_uuid,
                    summary=f"Updated artwork locks for container {existing.get('title')}",
                    metadata={
                        "containerType": existing.get("container_type"),
                        "title": existing.get("title"),
                        "artworkLocks": updates,
                    },
                )
                emit_container_change(conn, container_uuid, operation="upsert")
            detail = container_detail_entity(conn, container_uuid)
        return response({"status": "ok", "detail": detail, "artworkLocks": updates})

