    def metadata_box_set_proposal_key(proposal: dict[str, Any], result: dict[str, Any] | None = None) -> str:
        result = result or {}
        provider = (clean_text(
            proposal.get("provider")
            or proposal.get("source")
            or proposal.get("member_source")
            or result.get("pluginId")
            or result.get("provider")
            or result.get("plugin_id")
        ) or "").casefold()
        title = (clean_text(proposal.get("title") or proposal.get("name")) or "").casefold()
        discriminator = (clean_text(
            proposal.get("barcode")
            or proposal.get("movievault_id")
            or proposal.get("movievaultId")
            or proposal.get("detailUrl")
            or proposal.get("detail_url")
            or proposal.get("sourceUrl")
            or proposal.get("source_url")
        ) or "").casefold()
        return f"{provider}::{title}::{discriminator}"

    def box_set_proposal_members(proposal: dict[str, Any]) -> list[dict[str, Any]]:
        return box_set_proposal_member_list(proposal)

    def metadata_value_looks_like_box_set(value: Any) -> bool:
        if not isinstance(value, dict):
            return False
        entity_type = (
            clean_text(
                value.get("entityType")
                or value.get("entity_type")
                or value.get("containerType")
                or value.get("container_type")
                or value.get("kind")
                or value.get("type")
                or value.get("releaseType")
                or value.get("release_type")
                or value.get("category")
                or value.get("objectType")
                or value.get("object_type")
            )
            or ""
        ).casefold()
        entity_key = re.sub(r"[-\s]+", "_", entity_type)
        explicit_box_set = (
            "box_set" in entity_key
            or "boxset" in entity_key
            or ("box" in entity_key and ("set" in entity_key or "collection" in entity_key))
            or value.get("isBoxSetCandidate") is True
            or value.get("is_box_set_candidate") is True
            or value.get("isBoxSet") is True
            or value.get("is_box_set") is True
        )
        for key in ("boxSetProposal", "box_set_proposal", "boxSet", "box_set", "boxSetCandidate", "box_set_candidate"):
            proposal = value.get(key)
            if isinstance(proposal, dict):
                return True
        if explicit_box_set and len(box_set_proposal_members(value)) >= 2:
            return True
        return explicit_box_set

    def metadata_result_looks_like_box_set(result: Any) -> bool:
        if not isinstance(result, dict):
            return False
        if metadata_value_looks_like_box_set(result):
            return True
        raw = result.get("raw") if isinstance(result.get("raw"), dict) else {}
        if metadata_value_looks_like_box_set(raw):
            return True
        for key in ("movie", "details", "release", "boxSetProposal", "box_set_proposal"):
            if metadata_value_looks_like_box_set(result.get(key)):
                return True
            if metadata_value_looks_like_box_set(raw.get(key)):
                return True
        for key in ("boxSetProposals", "box_set_proposals"):
            for item in (result.get(key) if isinstance(result.get(key), list) else []):
                if isinstance(item, dict) and (metadata_value_looks_like_box_set(item) or len(box_set_proposal_members(item)) >= 2):
                    return True
            for item in (raw.get(key) if isinstance(raw.get(key), list) else []):
                if isinstance(item, dict) and (metadata_value_looks_like_box_set(item) or len(box_set_proposal_members(item)) >= 2):
                    return True
        return False

    def metadata_box_set_proposals(metadata_result: dict[str, Any]) -> list[dict[str, Any]]:
        if not isinstance(metadata_result, dict):
            return []
        proposals: list[dict[str, Any]] = []
        seen: set[str] = set()
        query = metadata_result.get("query") if isinstance(metadata_result.get("query"), dict) else {}
        query_barcode = clean_text(query.get("externalBarcode") or query.get("barcode"))
        for result in metadata_result.get("results") or []:
            if not isinstance(result, dict):
                continue
            raw = result.get("raw") if isinstance(result.get("raw"), dict) else {}
            proposal = (
                result.get("boxSetProposal")
                or result.get("box_set_proposal")
                or raw.get("boxSetProposal")
                or raw.get("box_set_proposal")
            )
            proposal_candidates = []
            if isinstance(proposal, dict):
                proposal_candidates.append(proposal)
            for key in ("boxSetProposals", "box_set_proposals"):
                value = result.get(key)
                if isinstance(value, list):
                    proposal_candidates.extend(item for item in value if isinstance(item, dict))
                raw_value = raw.get(key)
                if isinstance(raw_value, list):
                    proposal_candidates.extend(item for item in raw_value if isinstance(item, dict))
            for key in ("candidates", "items", "matches"):
                value = result.get(key)
                if isinstance(value, list):
                    proposal_candidates.extend(item for item in value if isinstance(item, dict) and metadata_value_looks_like_box_set(item))
                raw_value = raw.get(key)
                if isinstance(raw_value, list):
                    proposal_candidates.extend(item for item in raw_value if isinstance(item, dict) and metadata_value_looks_like_box_set(item))
            for proposal_candidate in proposal_candidates:
                if box_set_proposal_is_upcitemdb(proposal_candidate):
                    continue
                members = box_set_proposal_members(proposal_candidate)
                if len(members) < 2:
                    continue
                normalized = dict(proposal_candidate)
                normalized["members"] = members
                normalized["movies"] = members
                normalized.setdefault(
                    "provider",
                    clean_text(
                        result.get("pluginId")
                        or result.get("provider")
                        or proposal_candidate.get("provider")
                        or proposal_candidate.get("source")
                    ),
                )
                evidence = box_set_proposal_evidence(normalized)
                if query_barcode and clean_text(normalized.get("barcode")) == query_barcode:
                    evidence = {**evidence, "barcodeMatch": True}
                if evidence:
                    normalized["boxSetEvidence"] = evidence
                    normalized["box_set_evidence"] = evidence
                key = metadata_box_set_proposal_key(normalized, result)
                if key in seen:
                    continue
                seen.add(key)
                normalized["_proposalKey"] = key
                proposals.append(normalized)
        return sorted(proposals, key=box_set_proposal_sort_key)

    def metadata_box_set_proposal(metadata_result: dict[str, Any], selected_key: str = "") -> dict[str, Any]:
        proposals = metadata_box_set_proposals(metadata_result)
        selected_key = (clean_text(selected_key) or "").casefold()
        if selected_key:
            for proposal in proposals:
                if (clean_text(proposal.get("_proposalKey")) or "").casefold() == selected_key:
                    return proposal
        return proposals[0] if proposals else {}

    def metadata_box_set_artwork_value(*values: Any) -> str:
        for value in values:
            if isinstance(value, list):
                image = metadata_box_set_artwork_value(*value)
                if image:
                    return image
                continue
            if isinstance(value, dict):
                media_updates = value.get("mediaUpdates") if isinstance(value.get("mediaUpdates"), dict) else {}
                poster_update = media_updates.get("poster") if isinstance(media_updates.get("poster"), dict) else {}
                plugin_media_source_url = value.get("sourceUrl") if clean_text(value.get("kind")) == "poster" else ""
                image = metadata_box_set_artwork_value(
                    value.get("posterUrl"),
                    value.get("poster_url"),
                    value.get("poster"),
                    value.get("coverUrl"),
                    value.get("cover_url"),
                    value.get("image"),
                    poster_update.get("sourceUrl"),
                    poster_update.get("source_url"),
                    plugin_media_source_url,
                )
                if image:
                    return image
                continue
            image = server_usable_image(value)
            if image:
                return image
        return ""

    def metadata_box_set_artwork_sources(result: dict[str, Any]) -> list[dict[str, Any]]:
        raw = result.get("raw") if isinstance(result.get("raw"), dict) else {}
        sources = [
            result,
            result.get("movie"),
            result.get("details"),
            result.get("release"),
            result.get("boxSetProposal"),
            result.get("box_set_proposal"),
            raw,
            raw.get("movie"),
            raw.get("details"),
            raw.get("release"),
            raw.get("boxSetProposal"),
            raw.get("box_set_proposal"),
        ]
        for key in ("candidates", "items", "matches"):
            value = result.get(key)
            if isinstance(value, list):
                sources.extend(value)
            raw_value = raw.get(key)
            if isinstance(raw_value, list):
                sources.extend(raw_value)
        return [item for item in sources if isinstance(item, dict)]

    def metadata_box_set_artwork_matches(source: dict[str, Any], proposal_title: str, input_title: str) -> bool:
        source_title = (clean_text(
            source.get("title")
            or source.get("name")
            or source.get("releaseTitle")
            or source.get("boxSetTitle")
            or source.get("box_set_title")
        ) or "").casefold()
        if not source_title:
            return False
        proposal_title = (proposal_title or "").casefold()
        input_title = (input_title or "").casefold()
        candidates = [item for item in (proposal_title, input_title) if item]
        return any(item in source_title or source_title in item for item in candidates)

    def enrich_box_set_proposal_artwork(
        proposal: dict[str, Any],
        metadata_result: dict[str, Any],
        body: dict[str, Any],
    ) -> dict[str, Any]:
        if not isinstance(proposal, dict):
            return proposal
        enriched = dict(proposal)
        existing_poster = metadata_box_set_artwork_value(
            enriched.get("posterUrl"),
            enriched.get("poster_url"),
            enriched.get("poster"),
            enriched.get("coverUrl"),
            enriched.get("cover_url"),
        )
        existing_backdrop = metadata_box_set_artwork_value(
            enriched.get("backdropUrl"),
            enriched.get("backdrop_url"),
            enriched.get("backdrop"),
        )
        if existing_poster and existing_backdrop:
            return enriched
        proposal_title = clean_text(enriched.get("title") or enriched.get("name"))
        input_title = clean_text(body.get("title") or body.get("query"))
        fallback_poster = ""
        fallback_backdrop = ""
        providers: list[str] = []
        for result in metadata_result.get("results") or []:
            if not isinstance(result, dict):
                continue
            for source in metadata_box_set_artwork_sources(result):
                if not metadata_box_set_artwork_matches(source, proposal_title, input_title):
                    continue
                if not fallback_poster:
                    fallback_poster = metadata_box_set_artwork_value(source)
                    if fallback_poster:
                        providers.append(clean_text(result.get("pluginId") or result.get("provider") or source.get("provider") or source.get("source")))
                if not fallback_backdrop:
                    fallback_backdrop = metadata_box_set_artwork_value(
                        source.get("backdropUrl"),
                        source.get("backdrop_url"),
                        source.get("backdrop"),
                    )
                if (existing_poster or fallback_poster) and (existing_backdrop or fallback_backdrop):
                    break
            if (existing_poster or fallback_poster) and (existing_backdrop or fallback_backdrop):
                break
        if not existing_poster and fallback_poster:
            enriched["posterUrl"] = fallback_poster
            enriched["poster_url"] = fallback_poster
            enriched["poster"] = fallback_poster
        if not existing_backdrop and fallback_backdrop:
            enriched["backdropUrl"] = fallback_backdrop
            enriched["backdrop_url"] = fallback_backdrop
            enriched["backdrop"] = fallback_backdrop
        if providers:
            fallbacks = enriched.get("metadata_plugin_fallbacks") if isinstance(enriched.get("metadata_plugin_fallbacks"), list) else []
            enriched["metadata_plugin_fallbacks"] = [
                *fallbacks,
                {"kind": "box_set_artwork", "providers": [item for item in providers if item]},
            ]
        return enriched

    def synthetic_box_set_member_barcode(box_set_title: str, parent_barcode: str, index: int) -> str:
        base = clean_text(parent_barcode) or clean_text(box_set_title) or "box-set"
        clean = re.sub(r"[^A-Za-z0-9]+", "_", base).strip("_").upper()[:48] or "BOXSET"
        return f"IMPORT-{clean}-BOX-{index:02d}"

    def physical_format_key(value: Any) -> str:
        text = (clean_text(value) or "").casefold().replace("-", " ").replace("_", " ").replace("/", " ")
        text = " ".join(text.split())
        if not text:
            return ""
        if "ultra hd" in text or "uhd" in text or "4k" in text:
            return "ultra_hd_blu_ray"
        if "blu ray" in text or "bluray" in text or text == "bd":
            return "blu_ray"
        if text in {"dvd", "dvd video"}:
            return "dvd"
        if "hd dvd" in text or "hddvd" in text:
            return "hd_dvd"
        if "laserdisc" in text or "laser disc" in text:
            return "laserdisc"
        if "svcd" in text or "vcd" in text:
            return "vcd_svcd"
        return text

    def compatible_box_set_member_format(candidate: Any, expected: Any) -> bool:
        candidate_key = physical_format_key(candidate)
        expected_key = physical_format_key(expected)
        return not candidate_key or not expected_key or candidate_key == expected_key

    def box_set_member_identifiers(member: dict[str, Any]) -> dict[str, str]:
        identifiers: dict[str, str] = {}
        tmdb_id = clean_text(member.get("tmdbId") or member.get("tmdb_id"))
        imdb_id = clean_text(member.get("imdbId") or member.get("imdb_id"))
        if tmdb_id:
            identifiers["tmdb"] = tmdb_id
        if imdb_id:
            identifiers["imdb"] = imdb_id
        return identifiers

    def existing_movie_row_matches_box_set_member(row: dict[str, Any], member: dict[str, Any]) -> bool:
        member_title = clean_text(member.get("title") or member.get("originalTitle") or member.get("original_title"))
        member_year = clean_text(member.get("year"))
        member_format = clean_text(member.get("format"))
        row_title_values = [
            clean_text(row.get("title")),
            clean_text(row.get("original_title")),
            clean_text(row.get("sort_title")),
        ]
        if member_title:
            member_title_key = member_title.casefold()
            if not any(value and value.casefold() == member_title_key for value in row_title_values):
                return False
        if member_year and clean_text(row.get("year")) and clean_text(row.get("year")) != member_year:
            return False
        if member_format and clean_text(row.get("format")) and not compatible_box_set_member_format(row.get("format"), member_format):
            return False
        return True

    def existing_movie_for_box_set_member(conn, member: dict[str, Any]) -> UUID | None:
        barcode = clean_text(member.get("barcode"))
        title = clean_text(member.get("title") or member.get("originalTitle") or member.get("original_title"))
        year = clean_text(member.get("year"))
        with conn.cursor() as cur:
            if barcode:
                cur.execute("SELECT id FROM movies WHERE barcode=%s", (barcode,))
                row = cur.fetchone()
                if row:
                    return row["id"]
            identifiers = box_set_member_identifiers(member)
            if identifiers and table_exists(conn, "movie_identifiers"):
                for provider, identifier in identifiers.items():
                    cur.execute(
                        """
                        SELECT m.id, m.title, m.original_title, m.sort_title, m.year, m.format
                        FROM movie_identifiers mi
                        JOIN movies m ON m.id = mi.movie_id
                        WHERE mi.provider_id=%s AND mi.identifier_type='movie_id' AND mi.identifier=%s
                        ORDER BY m.updated_at DESC
                        """,
                        (provider, identifier),
                    )
                    for row in cur.fetchall():
                        if existing_movie_row_matches_box_set_member(row, member):
                            return row["id"]
            if title and year:
                cur.execute(
                    """
                    SELECT id, title, original_title, sort_title, year, format
                    FROM movies
                    WHERE (
                        lower(COALESCE(sort_title, '')) = lower(%s)
                        OR lower(COALESCE(title, '')) = lower(%s)
                        OR lower(COALESCE(original_title, '')) = lower(%s)
                    )
                      AND COALESCE(year, '') = %s
                    ORDER BY updated_at DESC
                    """,
                    (title, title, title, year),
                )
                for row in cur.fetchall():
                    if existing_movie_row_matches_box_set_member(row, member):
                        return row["id"]
        return None

    def normalized_box_set_members_from_body(body: dict[str, Any]) -> list[dict[str, Any]]:
        raw_members = body.get("boxSetMembers") or body.get("box_set_members")
        if not isinstance(raw_members, list):
            return []
        members = []
        for index, item in enumerate(raw_members[:50], start=1):
            if not isinstance(item, dict):
                continue
            if (clean_text(item.get("action")) or "").casefold() == "skip":
                continue
            title = clean_text(item.get("title") or item.get("originalTitle") or item.get("original_title"))
            if not title:
                continue
            member = dict(item)
            member["title"] = title
            member["year"] = clean_text(member.get("year"))
            member["format"] = clean_text(member.get("format"))
            member["sortOrder"] = index
            member["memberConfidence"] = clean_text(member.get("memberConfidence") or member.get("member_confidence") or "manual")
            members.append(member)
        return members

    def merge_box_set_member_enrichment(member: dict[str, Any], metadata_result: dict[str, Any], fallback_format: str) -> dict[str, Any]:
        proposal = metadata_result.get("proposal") if isinstance(metadata_result, dict) else {}
        if not isinstance(proposal, dict):
            return member
        movie_updates = proposal.get("movieUpdates") or {}
        metadata_updates = proposal.get("metadataUpdates") or {}
        technical_updates = proposal.get("technicalUpdates") or {}
        media_updates = proposal.get("mediaUpdates") or {}
        identifiers = proposal.get("identifiers") or {}
        enriched = dict(member)

        def fill(target: str, *values: Any, overwrite: bool = False) -> None:
            if not overwrite and enriched.get(target) not in (None, "", [], {}):
                return
            for value in values:
                if value not in (None, "", [], {}):
                    enriched[target] = value
                    return

        discovered_format = (
            movie_updates.get("format")
            or technical_updates.get("format")
            or metadata_updates.get("format")
            or ""
        )
        # Keep imported box-set members on the selected parent edition format.
        # A DVD box-set must not silently receive 4K members from a broad
        # metadata hit; those hits can still fill identifiers and artwork.
        if discovered_format and compatible_box_set_member_format(discovered_format, fallback_format) and (
            not enriched.get("format") or clean_text(enriched.get("format")) == clean_text(fallback_format)
        ):
            enriched["format"] = discovered_format
        if fallback_format and (
            not enriched.get("format") or not compatible_box_set_member_format(enriched.get("format"), fallback_format)
        ):
            enriched["format"] = fallback_format

        fill("overview", movie_updates.get("overview"), metadata_updates.get("overview"), metadata_updates.get("plot"))
        fill("plot", metadata_updates.get("plot"), movie_updates.get("overview"))
        fill("releaseDate", movie_updates.get("release_date"), metadata_updates.get("release_date"))
        fill("release_date", movie_updates.get("release_date"), metadata_updates.get("release_date"))
        fill("runtimeMinutes", movie_updates.get("runtime_minutes"), metadata_updates.get("runtime_minutes"))
        fill("runtime", movie_updates.get("runtime_minutes"), metadata_updates.get("runtime_minutes"))
        fill("genre", metadata_updates.get("genre"))
        fill("director", metadata_updates.get("director"))
        fill("actor", metadata_updates.get("actor"))
        fill("producer", metadata_updates.get("producer"))
        fill("studios", metadata_updates.get("studios"))

        poster_update = media_updates.get("poster") if isinstance(media_updates.get("poster"), dict) else {}
        backdrop_update = media_updates.get("backdrop") if isinstance(media_updates.get("backdrop"), dict) else {}
        poster_url = metadata_updates.get("poster_url") or poster_update.get("sourceUrl")
        backdrop_url = metadata_updates.get("backdrop_url") or backdrop_update.get("sourceUrl")
        fill("poster", poster_url)
        fill("posterUrl", poster_url)
        fill("poster_url", poster_url)
        fill("backdrop", backdrop_url)
        fill("backdropUrl", backdrop_url)
        fill("backdrop_url", backdrop_url)
        fill("backdropUrls", metadata_updates.get("backdrop_urls"))
        fill("backdrop_urls", metadata_updates.get("backdrop_urls"))

        if identifiers.get("tmdb") and not (enriched.get("tmdbId") or enriched.get("tmdb_id")):
            enriched["tmdbId"] = str(identifiers["tmdb"])
            enriched["tmdb_id"] = str(identifiers["tmdb"])
        if identifiers.get("imdb") and not (enriched.get("imdbId") or enriched.get("imdb_id")):
            enriched["imdbId"] = str(identifiers["imdb"])
            enriched["imdb_id"] = str(identifiers["imdb"])

        if technical_updates:
            enriched["technicalSpecs"] = {**(enriched.get("technicalSpecs") or {}), **technical_updates}
        source_summary = [
            item
            for item in (metadata_result.get("sourceSummary") or [])
            if item.get("state") in {"applied", "hit"}
        ]
        if source_summary:
            enriched["metadataPluginEnrichment"] = [
                {
                    "pluginId": item.get("pluginId"),
                    "state": item.get("state"),
                    "reason": item.get("reason"),
                }
                for item in source_summary
            ]
        return {key: value for key, value in enriched.items() if value not in (None, "", [], {})}

    def enrich_box_set_member_for_import(
        conn,
        member: dict[str, Any],
        *,
        proposal: dict[str, Any],
        body: dict[str, Any],
        actor: dict[str, Any],
        fallback_format: str,
    ) -> dict[str, Any]:
        title = clean_text(member.get("title") or member.get("originalTitle") or member.get("original_title"))
        if not title and not (member.get("tmdbId") or member.get("tmdb_id") or member.get("imdbId") or member.get("imdb_id")):
            return member
        lookup_payload = {
            "title": title,
            "year": clean_text(member.get("year")),
            "tmdbId": clean_text(member.get("tmdbId") or member.get("tmdb_id")),
            "imdbId": clean_text(member.get("imdbId") or member.get("imdb_id")),
            "barcode": clean_text(member.get("barcode")),
            "format": clean_text(member.get("format") or fallback_format),
            "parentBoxSets": [
                {
                    "title": clean_text(proposal.get("title") or proposal.get("name")),
                    "barcode": clean_text(proposal.get("barcode") or body.get("barcode")),
                    "format": clean_text(body.get("format") or proposal.get("format") or fallback_format),
                }
            ],
        }
        try:
            metadata_result = lookup_metadata_sources(conn, lookup_payload, actor)
        except Exception as exc:
            return {
                **member,
                "metadataPluginWarning": str(exc),
            }
        return merge_box_set_member_enrichment(member, metadata_result, fallback_format)

    def box_set_member_import_payload(member: dict[str, Any], *, box_set_title: str, fallback_format: str, barcode: str) -> dict[str, Any]:
        metadata = {}
        for key in (
            "genre",
            "director",
            "actor",
            "producer",
            "studios",
            "poster_url",
            "posterUrl",
            "backdrop_url",
            "backdropUrl",
            "backdrop_urls",
            "backdropUrls",
            "identifiedBy",
            "memberConfidence",
            "metadataPluginEnrichment",
            "metadataPluginWarning",
            "sourceRef",
        ):
            value = member.get(key)
            if value not in (None, "", [], {}):
                metadata[key] = value
        metadata["box_set"] = box_set_title
        return {
            "barcode": barcode,
            "title": clean_text(member.get("title")),
            "originalTitle": clean_text(member.get("originalTitle") or member.get("original_title")),
            "year": clean_text(member.get("year")),
            "releaseDate": clean_text(member.get("releaseDate") or member.get("release_date")),
            "format": clean_text(member.get("format")) or fallback_format,
            "overview": clean_text(member.get("overview") or member.get("plot")),
            "runtimeMinutes": member.get("runtimeMinutes") or member.get("runtime_minutes") or member.get("runtime"),
            "country": clean_text(member.get("country")),
            "language": clean_text(member.get("language")),
            "rating": clean_text(member.get("rating")),
            "metadata": metadata,
        }

    def box_set_member_metadata_proposal(member: dict[str, Any]) -> dict[str, Any]:
        movie_updates = {}
        member_format = clean_text(member.get("format"))
        if member_format:
            movie_updates["format"] = member_format
        metadata_updates = {}
        for source, target in (
            ("genre", "genre"),
            ("director", "director"),
            ("actor", "actor"),
            ("producer", "producer"),
            ("studios", "studios"),
            ("posterUrl", "poster_url"),
            ("poster_url", "poster_url"),
            ("backdropUrl", "backdrop_url"),
            ("backdrop_url", "backdrop_url"),
            ("backdropUrls", "backdrop_urls"),
            ("backdrop_urls", "backdrop_urls"),
        ):
            value = member.get(source)
            if value not in (None, "", [], {}):
                metadata_updates[target] = value
        media_updates = {}
        poster_url = clean_text(member.get("posterUrl") or member.get("poster_url") or member.get("poster"))
        backdrop_url = clean_text(member.get("backdropUrl") or member.get("backdrop_url") or member.get("backdrop"))
        if poster_url:
            media_updates["poster"] = {
                "kind": "poster",
                "sourceUrl": poster_url,
                "options": [poster_url],
                "providerId": "movievault",
                "sourceLabel": "MovieVault",
                "sourceRef": clean_text(member.get("sourceRef")),
            }
        if backdrop_url:
            media_updates["backdrop"] = {
                "kind": "backdrop",
                "sourceUrl": backdrop_url,
                "options": [backdrop_url],
                "providerId": "movievault",
                "sourceLabel": "MovieVault",
                "sourceRef": clean_text(member.get("sourceRef")),
            }
        raw_technical = member.get("technicalSpecs") if isinstance(member.get("technicalSpecs"), dict) else {}
        technical_updates = {}
        for source, target in (
            ("hdr", "hdr"),
            ("packaging", "packaging"),
            ("screen_ratios", "screen_ratios"),
            ("screenRatios", "screen_ratios"),
            ("audio_tracks", "audio_tracks"),
            ("audioTracks", "audio_tracks"),
            ("subtitles", "subtitles"),
            ("regions", "regions"),
            ("content_ratings", "content_ratings"),
            ("contentRatings", "content_ratings"),
        ):
            value = member.get(source)
            if value in (None, "", [], {}):
                value = raw_technical.get(source)
            if value not in (None, "", [], {}):
                technical_updates[target] = value
        return {
            "movieUpdates": movie_updates,
            "metadataUpdates": metadata_updates,
            "technicalUpdates": technical_updates,
            "identifiers": box_set_member_identifiers(member),
            "mediaUpdates": media_updates,
        }

    def import_box_set_proposal(conn, proposal: dict[str, Any], body: dict[str, Any], actor: dict[str, Any]) -> dict[str, Any]:
        if not table_exists(conn, "containers") or not table_exists(conn, "container_movies"):
            raise NextApiError("Container tables are not available", 503)
        title = clean_text(proposal.get("title") or proposal.get("name") or body.get("title"))
        override_members = normalized_box_set_members_from_body(body)
        proposal_members = box_set_proposal_members(proposal)
        members = override_members or proposal_members
        if not title or len(members) < 2:
            raise NextApiError("Box-set proposal requires a title and at least two members.", 422)
        fallback_format = clean_text(body.get("format") or proposal.get("format") or proposal.get("mediaType") or proposal.get("media_type"))
        if fallback_format:
            for member in members:
                if not clean_text(member.get("format")) or not compatible_box_set_member_format(member.get("format"), fallback_format):
                    member["format"] = fallback_format
        barcode = clean_text(proposal.get("barcode") or body.get("barcode"))
        provider_label = clean_text(
            proposal.get("provider")
            or proposal.get("source")
            or proposal.get("member_source")
            or "metadata plugin"
        )
        member_source = clean_text(proposal.get("memberSource") or proposal.get("member_source") or provider_label)
        member_confidence = clean_text(proposal.get("memberConfidence") or proposal.get("member_confidence"))
        container_metadata = {
            "source": provider_label,
            "import_source": "plugin_box_set",
            "provider": provider_label,
            "format": fallback_format,
            "media_format": fallback_format,
            "box_set_proposal_key": proposal.get("_proposalKey"),
            "movievault_id": proposal.get("movievault_id"),
            "member_source": member_source,
            "member_confidence": member_confidence,
            "metadata_plugin_fallbacks": proposal.get("metadata_plugin_fallbacks") or [],
            "poster_url": proposal.get("poster_url") or proposal.get("poster"),
            "backdrop_url": proposal.get("backdrop_url") or proposal.get("backdrop"),
            "backdrop_urls": proposal.get("backdrop_urls") or proposal.get("backdropUrls") or [],
        }
        existing_container = None
        with conn.cursor() as cur:
            if barcode:
                cur.execute(
                    "SELECT id FROM containers WHERE container_type='box_set' AND barcode=%s LIMIT 1",
                    (barcode,),
                )
                existing_container = cur.fetchone()
            if not existing_container and not barcode:
                cur.execute(
                    """
                    SELECT id, barcode, metadata
                    FROM containers
                    WHERE container_type='box_set'
                      AND lower(title)=lower(%s)
                    ORDER BY updated_at DESC
                    LIMIT 10
                    """,
                    (title,),
                )
                for candidate in cur.fetchall():
                    if should_reuse_box_set_container_for_import(
                        candidate,
                        incoming_barcode=barcode,
                        incoming_format=fallback_format,
                    ):
                        existing_container = candidate
                        break
        container_created = False
        if existing_container:
            container_uuid = existing_container["id"]
            with conn.cursor() as cur:
                cur.execute(
                    """
                    UPDATE containers
                    SET title=COALESCE(NULLIF(title, ''), %s),
                        barcode=COALESCE(NULLIF(barcode, ''), %s),
                        year=COALESCE(NULLIF(year, ''), %s),
                        description=COALESCE(NULLIF(description, ''), %s),
                        metadata=COALESCE(metadata, '{}'::jsonb) || %s,
                        updated_at=now()
                    WHERE id=%s
                    """,
                    (
                        title,
                        barcode or None,
                        clean_text(proposal.get("year") or proposal.get("year_range")) or None,
                        clean_text(proposal.get("description")) or None,
                        Jsonb(json_ready(container_metadata)),
                        container_uuid,
                    ),
                )
        else:
            container_uuid = uuid.uuid4()
            container_public_id = f"import-box-set-{container_uuid.hex[:12]}"
            container_created = True
            with conn.cursor() as cur:
                cur.execute(
                    """
                    INSERT INTO containers (
                        id, public_id, container_type, title, barcode, badge_label, year, description, metadata, created_at, updated_at
                    )
                    VALUES (%s, %s, 'box_set', %s, %s, NULL, %s, %s, %s, now(), now())
                    """,
                    (
                        container_uuid,
                        container_public_id,
                        title,
                        barcode or None,
                        clean_text(proposal.get("year") or proposal.get("year_range")),
                        clean_text(proposal.get("description")),
                        Jsonb(json_ready(container_metadata)),
                    ),
                )

        imported_movies = []
        applied_members = []
        receiver_member_overrides: list[dict[str, Any]] = []
        metadata_refresh_movie_ids: list[str] = []
        decision_counts = {
            "created": 0,
            "linkedExisting": 0,
            "skipped": 0,
            "memberLinksReplaced": 0,
            "metadataRefreshQueued": 0,
            "containerCreated": 1 if container_created else 0,
            "containerEnriched": 0 if container_created else 1,
        }
        if override_members:
            with conn.cursor() as cur:
                cur.execute("DELETE FROM container_movies WHERE container_id=%s", (container_uuid,))
                decision_counts["memberLinksReplaced"] = max(int(cur.rowcount or 0), 0)
        for index, member in enumerate(members[:50], start=1):
            original_confidence = clean_text(member.get("memberConfidence") or member.get("member_confidence") or member_confidence)
            member = enrich_box_set_member_for_import(
                conn,
                member,
                proposal=proposal,
                body=body,
                actor=actor,
                fallback_format=fallback_format,
            )
            existing_id = existing_movie_for_box_set_member(conn, member)
            member_barcode = clean_text(member.get("barcode")) or synthetic_box_set_member_barcode(title, barcode, index)
            payload = box_set_member_import_payload(
                member,
                box_set_title=title,
                fallback_format=fallback_format,
                barcode=member_barcode,
            )
            if existing_id:
                movie_id = existing_id
                import_action = "linked_existing"
                decision_counts["linkedExisting"] += 1
            else:
                mutation_id = f"import-box-set-member-{uuid.uuid4()}"
                upsert = apply_movie_upsert(
                    conn,
                    client_id="next-import-center",
                    idem_key=f"next-import-center:{mutation_id}",
                    mutation={
                        "clientMutationId": mutation_id,
                        "entityType": "movie",
                        "operation": "upsert",
                        "payload": payload,
                    },
                )
                movie_id = upsert["entityId"]
                import_action = "created"
                decision_counts["created"] += 1
            applied = apply_metadata_proposal(conn, movie_id, box_set_member_metadata_proposal(member), actor=actor)
            with conn.cursor() as cur:
                cur.execute(
                    """
                    INSERT INTO container_movies (container_id, movie_id, sort_order, created_at)
                    VALUES (%s, %s, %s, now())
                    ON CONFLICT (container_id, movie_id) DO UPDATE SET sort_order=EXCLUDED.sort_order
                    """,
                    (container_uuid, movie_id, index),
                )
            detail = movie_detail_entity(conn, movie_id)
            imported_movie = detail.get("movie") if detail else {"id": str(movie_id), "title": payload.get("title")}
            imported_movies.append(imported_movie)
            receiver_member = receiver_member_payload_from_raw(
                {
                    **member,
                    "title": payload.get("title"),
                    "originalTitle": payload.get("originalTitle") or member.get("originalTitle") or member.get("original_title"),
                    "year": payload.get("year") or member.get("year"),
                    "format": payload.get("format") or member.get("format"),
                    "barcode": payload.get("barcode") or member.get("barcode"),
                    "publicId": imported_movie.get("public_id") or imported_movie.get("publicId"),
                    "posterUrl": (
                        member.get("posterUrl")
                        or member.get("poster_url")
                        or (payload.get("metadata") or {}).get("poster_url")
                        or (payload.get("metadata") or {}).get("posterUrl")
                    ),
                    "sourceUrl": member.get("sourceUrl") or member.get("source_url"),
                    "sourceRef": member.get("sourceRef") or member.get("source_ref"),
                },
                sort_order=index,
            )
            if receiver_member:
                receiver_member_overrides.append(receiver_member)
            applied_members.append(
                {
                    "movieId": str(movie_id),
                    "title": payload.get("title"),
                    "action": import_action,
                    "confidence": original_confidence,
                    "source": clean_text(member.get("source") or member_source),
                    "applied": applied,
                }
            )
            metadata_refresh_movie_ids.append(str(movie_id))

        queued_jobs = []
        if metadata_refresh_movie_ids:
            for movie_id in dict.fromkeys(metadata_refresh_movie_ids):
                job = queue_movie_metadata_refresh_job(
                    conn,
                    movie_id,
                    actor=actor,
                    reason="box_set_member_full_refresh",
                    source=provider_label,
                    extra={
                        "boxSetTitle": title,
                        "boxSetBarcode": barcode,
                    },
                )
                if job:
                    queued_jobs.append(job)
            decision_counts["metadataRefreshQueued"] = len(queued_jobs)

        audit_event(
            conn,
            event_type="box_set.imported",
            category="import",
            actor=actor,
            target_type="container",
            target_id=container_uuid,
            summary=f"{'Imported' if container_created else 'Enriched'} box-set {title}",
            metadata={
                "barcode": barcode,
                "members": len(imported_movies),
                "containerCreated": container_created,
                "source": provider_label,
                "memberSource": member_source,
                "memberConfidence": member_confidence,
                "proposalKey": proposal.get("_proposalKey"),
                "decisionCounts": decision_counts,
                "memberOverridesApplied": bool(override_members),
                "appliedMembers": applied_members,
                "queuedMetadataRefreshJobs": [str(job.get("id")) for job in queued_jobs],
            },
        )
        emit_container_change(conn, container_uuid, operation="upsert")
        emit_container_membership_change(conn, container_uuid)
        return {
            "container": container_detail_entity(conn, container_uuid),
            "movies": imported_movies,
            "appliedMembers": applied_members,
            "receiverMembers": receiver_member_overrides,
            "queuedMetadataRefreshJobs": queued_jobs,
            "decisionCounts": decision_counts,
            "containerId": str(container_uuid),
            "containerCreated": container_created,
            "memberSelectionReplaced": bool(override_members),
        }

    def metadata_import_candidate(metadata_result: dict[str, Any]) -> dict[str, Any]:
        def as_list(value: Any) -> list[Any]:
            return value if isinstance(value, list) else []

        def candidate_values(result: dict[str, Any]) -> list[dict[str, Any]]:
            raw = result.get("raw") if isinstance(result.get("raw"), dict) else {}
            values = [
                result,
                result.get("movie"),
                result.get("details"),
                result.get("release"),
                raw,
                raw.get("movie"),
                raw.get("details"),
                raw.get("release"),
            ]
            values.extend(as_list(result.get("candidates")))
            values.extend(as_list(raw.get("candidates")))
            values.extend(as_list(raw.get("items")))
            return [item for item in values if isinstance(item, dict)]

        def first_value(result: dict[str, Any], *keys: str) -> str:
            for source in candidate_values(result):
                for key in keys:
                    value = clean_text(source.get(key))
                    if value:
                        return value
            return ""

        for result in metadata_result.get("results") or []:
            if not isinstance(result, dict):
                continue
            if metadata_result_looks_like_box_set(result):
                continue
            movie_updates = result.get("movieUpdates") if isinstance(result.get("movieUpdates"), dict) else {}
            metadata_updates = result.get("metadataUpdates") if isinstance(result.get("metadataUpdates"), dict) else {}
            media_updates = result.get("mediaUpdates") if isinstance(result.get("mediaUpdates"), dict) else {}
            poster_update = media_updates.get("poster") if isinstance(media_updates.get("poster"), dict) else {}
            title = (
                clean_text(movie_updates.get("title") or movie_updates.get("original_title"))
                or first_value(result, "title", "originalTitle", "original_title", "name", "movieTitle", "movie_title")
            )
            if not title:
                continue
            return {
                "title": title,
                "year": clean_text(movie_updates.get("year")) or first_value(result, "year", "releaseYear", "release_year", "movieYear", "movie_year"),
                "format": clean_text(movie_updates.get("format")) or first_value(result, "format", "mediaFormat", "media_format", "releaseFormat", "release_format"),
                "poster_url": (
                    clean_text(metadata_updates.get("poster_url") or metadata_updates.get("posterUrl") or metadata_updates.get("poster"))
                    or clean_text(poster_update.get("sourceUrl") or poster_update.get("source_url"))
                    or first_value(result, "posterUrl", "poster_url", "poster", "coverUrl", "cover_url")
                ),
                "overview": clean_text(movie_updates.get("overview") or metadata_updates.get("overview") or metadata_updates.get("plot"))
                or first_value(result, "overview", "plot", "description"),
            }
        return {}

    def metadata_result_from_import_body(body: dict[str, Any]) -> dict[str, Any]:
        raw = (
            body.get("metadataPreview")
            or body.get("metadata_preview")
            or body.get("metadataResult")
            or body.get("metadata_result")
        )
        if not isinstance(raw, dict):
            return {}
        candidate = raw.get("metadata") if isinstance(raw.get("metadata"), dict) else raw
        if not isinstance(candidate, dict):
            return {}
        normalized = dict(candidate)
        for key in ("proposal", "query", "summary", "proposalStats"):
            if key in normalized and not isinstance(normalized.get(key), dict):
                normalized.pop(key, None)
        for key in ("results", "sources", "executions", "sourceOrder", "sourceSummary", "boxSetProposals", "box_set_proposals"):
            if key in normalized and not isinstance(normalized.get(key), list):
                normalized.pop(key, None)
        if any(key in candidate for key in ("proposal", "results", "sources", "executions", "summary", "boxSetProposals")):
            return normalized
        return {}

    def metadata_lookup_audit_payload(body: dict[str, Any], result: dict[str, Any]) -> dict[str, Any]:
        query = result.get("query") if isinstance(result.get("query"), dict) else {}
        proposal = result.get("proposal") if isinstance(result.get("proposal"), dict) else {}
        executions = result.get("executions") if isinstance(result.get("executions"), list) else []
        results = result.get("results") if isinstance(result.get("results"), list) else []
        box_set_proposals = metadata_box_set_proposals(result)
        return {
            "query": {
                "title": query.get("title") or clean_text(body.get("title") or body.get("query")),
                "year": query.get("year") or clean_text(body.get("year")),
                "barcode": query.get("externalBarcode") or query.get("barcode") or clean_text(body.get("barcode")),
                "format": query.get("format") or clean_text(body.get("format") or body.get("mediaFormat")),
                "detectBoxSets": bool(query.get("detectBoxSets") or body.get("detectBoxSets") or body.get("detect_box_sets")),
                "previewMode": bool(query.get("previewMode") or body.get("previewMode") or body.get("preview_mode")),
            },
            "sourceOrder": result.get("sourceOrder") or [],
            "sourceSummary": result.get("sourceSummary") or [],
            "executions": [
                {
                    "pluginId": item.get("pluginId"),
                    "entrypoint": item.get("entrypoint"),
                    "status": item.get("status"),
                    "state": item.get("state"),
                    "resultStatus": item.get("resultStatus"),
                    "candidateCount": item.get("candidateCount"),
                    "elapsedMs": item.get("elapsedMs"),
                    "error": item.get("error"),
                }
                for item in executions
                if isinstance(item, dict)
            ],
            "providerResults": [metadata_result_summary(item) for item in results if isinstance(item, dict)],
            "previewEnrichment": result.get("previewEnrichment") or {},
            "proposalStats": result.get("proposalStats") or {},
            "acceptedFields": proposal.get("provenance") or [],
            "skippedFields": proposal.get("skipped") or [],
            "selectedBoxSetProposal": box_set_proposal_audit_summary(box_set_proposals[0]) if box_set_proposals else {},
            "boxSetProposals": [box_set_proposal_audit_summary(item) for item in box_set_proposals],
        }

    @flask_app.post("/api/next/metadata/lookup")
    def metadata_lookup():
        body = request.get_json(silent=True) or {}
        if not isinstance(body, dict):
            raise NextApiError("Metadata lookup body must be an object", 400)
        with connect() as conn:
            actor = require_any_next_permission(
                conn,
                ("metadata.search", "collection.import", "collection.add", "collection.add_own", "collection.edit_all"),
            )
            if not table_exists(conn, "plugins"):
                raise NextApiError("Plugin registry table is not available", 503)
            result = lookup_metadata_sources(conn, body, actor)
            audit_event(
                conn,
                event_type="metadata.lookup",
                category="metadata",
                actor=actor,
                target_type="metadata_lookup",
                target_id=None,
                summary="Metadata lookup executed",
                metadata=metadata_lookup_audit_payload(body, result),
            )
        return response({"status": "ok", "metadata": result})

    @flask_app.post("/api/next/import/movie")
    def import_movie_from_metadata():
        body = request.get_json(silent=True) or {}
        if not isinstance(body, dict):
            raise NextApiError("Movie import body must be an object", 400)
        barcode = clean_text(body.get("barcode")) or ""
        title = clean_text(body.get("title") or body.get("query")) or ""
        if not barcode and not title:
            raise NextApiError("barcode or title is required", 400)
        target_container_id_raw = clean_text(body.get("targetContainerId") or body.get("target_container_id"))
        target_container_uuid = parse_uuid(target_container_id_raw, "targetContainerId") if target_container_id_raw else None
        import_mode = (clean_text(body.get("importMode") or body.get("import_mode")) or "").casefold().replace("_", "-")
        wants_movie_import = import_mode == "movie"
        wants_box_set_import = import_mode in {"box-set", "boxset"}
        provided_metadata_result = metadata_result_from_import_body(body)
        selected_box_set_key_from_body = clean_text(body.get("boxSetProposalKey") or body.get("box_set_proposal_key"))
        provided_box_set_body = body.get("boxSetProposal") or body.get("box_set_proposal")
        if not isinstance(provided_box_set_body, dict):
            provided_box_set_body = None
        selected_box_set_candidate_body = body.get("selectedBoxSetCandidate") or body.get("selected_box_set_candidate")
        selected_movie_candidate_body = body.get("selectedMovieCandidate") or body.get("selected_movie_candidate")
        selected_candidate_body = selected_box_set_candidate_body if isinstance(selected_box_set_candidate_body, dict) else selected_movie_candidate_body
        selected_candidate_is_box_set = (
            isinstance(selected_box_set_candidate_body, dict)
            and (
                metadata_value_looks_like_box_set(selected_box_set_candidate_body)
                or len(box_set_proposal_members(selected_box_set_candidate_body)) >= 2
            )
        )
        preview_box_set_proposal = metadata_box_set_proposal(provided_metadata_result, selected_box_set_key_from_body)
        explicit_movie_candidate_selected = (
            wants_movie_import
            and isinstance(selected_candidate_body, dict)
            and not selected_candidate_is_box_set
            and bool(
                clean_text(selected_candidate_body.get("candidateKey") or selected_candidate_body.get("title") or selected_candidate_body.get("name"))
                or clean_text(body.get("selectedMovieCandidateKey") or body.get("selected_movie_candidate_key"))
            )
        )
        if selected_candidate_is_box_set:
            provided_box_set_body = provided_box_set_body or selected_candidate_body
            wants_box_set_import = True
            wants_movie_import = False
        elif (
            preview_box_set_proposal
            and not explicit_movie_candidate_selected
            and box_set_proposal_auto_importable(preview_box_set_proposal)
        ):
            provided_box_set_body = provided_box_set_body or preview_box_set_proposal
            wants_box_set_import = True
            wants_movie_import = False
        elif wants_movie_import:
            provided_box_set_body = None
        has_provided_box_set = isinstance(provided_box_set_body, dict)
        explicit_box_set_import = import_mode in {"box-set", "boxset"} or selected_candidate_is_box_set
        if not wants_movie_import and not wants_box_set_import:
            wants_box_set_import = has_provided_box_set or bool(body.get("detectBoxSets") or body.get("detect_box_sets"))

        # When a target box-set/vault is pinned, every scan is a member of that
        # container: force a plain movie import and suppress box-set auto-detection.
        if target_container_uuid:
            wants_movie_import = True
            wants_box_set_import = False
            provided_box_set_body = None
            has_provided_box_set = False
            explicit_box_set_import = False

        with connect() as conn:
            actor = require_any_next_permission(
                conn,
                ("collection.add", "collection.add_own", "collection.import", "collection.edit_all"),
            )
            if not table_exists(conn, "movies"):
                raise NextApiError("Movie table is not available", 503)
            if not table_exists(conn, "plugins"):
                raise NextApiError("Plugin registry table is not available", 503)

            target_container_type: str | None = None
            if target_container_uuid:
                if not table_exists(conn, "container_movies"):
                    raise NextApiError("Container movie links are not available yet", 503)
                target_container_type = container_type_for_id(conn, target_container_uuid)
                if target_container_type not in {"box_set", "vault"}:
                    raise NextApiError("Target container must be a box-set or vault", 400)
                if not actor_has_any_permission(
                    actor,
                    ("containers.edit", "collection.edit_all", "collection.bulk_edit", "collection.import"),
                ):
                    raise NextApiError("You do not have permission to edit this container", 403)

            if wants_box_set_import and barcode and not has_provided_box_set:
                with conn.cursor() as cur:
                    cur.execute(
                        "SELECT id FROM containers WHERE barcode=%s AND container_type='box_set'",
                        (barcode,),
                    )
                    existing_box_set = cur.fetchone()
                if existing_box_set:
                    detail = container_detail_entity(conn, existing_box_set["id"])
                    audit_event(
                        conn,
                        event_type="box_set.import_skipped",
                        category="import",
                        actor=actor,
                        target_type="container",
                        target_id=existing_box_set["id"],
                        summary="Import skipped because the box-set already exists",
                        metadata={"barcode": barcode, "title": title},
                    )
                    return response(
                        {
                            "status": "ok",
                            "state": "already_exists",
                            "boxSet": detail,
                            "movies": detail.get("memberMovies") if detail else [],
                        }
                    )

            if barcode and not has_provided_box_set:
                with conn.cursor() as cur:
                    cur.execute("SELECT id FROM movies WHERE barcode=%s", (barcode,))
                    existing = cur.fetchone()
                if existing:
                    link_result = None
                    if target_container_uuid:
                        link_result = link_movie_into_container(conn, target_container_uuid, existing["id"], actor=actor)
                    detail = movie_detail_entity(conn, existing["id"])
                    audit_event(
                        conn,
                        event_type="movie.import_skipped",
                        category="import",
                        actor=actor,
                        target_type="movie",
                        target_id=existing["id"],
                        summary="Import skipped because the movie already exists",
                        metadata={
                            "barcode": barcode,
                            "title": title,
                            "targetContainerId": str(target_container_uuid) if target_container_uuid else None,
                        },
                    )
                    existing_payload: dict[str, Any] = {
                        "status": "ok",
                        "state": "already_exists",
                        "movie": detail.get("movie") if detail else None,
                        "detail": detail,
                    }
                    if target_container_uuid:
                        existing_payload["linkedToContainer"] = str(target_container_uuid)
                        existing_payload["containerType"] = target_container_type
                        existing_payload["linkChanged"] = link_result["changed"] if link_result else 0
                        existing_payload["container"] = container_detail_entity(conn, target_container_uuid)
                    return response(existing_payload)

            with conn.transaction():
                selected_box_set_key = clean_text(body.get("boxSetProposalKey") or body.get("box_set_proposal_key"))
                metadata_result: dict[str, Any] = dict(provided_metadata_result)
                box_set_proposal: dict[str, Any] = {}
                provided_proposal = provided_box_set_body
                if wants_box_set_import and isinstance(provided_proposal, dict):
                    candidate = dict(provided_proposal)
                    candidate.setdefault("provider", clean_text(candidate.get("provider") or candidate.get("source") or body.get("boxSetProvider")))
                    candidate.setdefault("title", clean_text(candidate.get("title") or candidate.get("name") or title))
                    if selected_box_set_key:
                        candidate["_proposalKey"] = selected_box_set_key
                    else:
                        candidate["_proposalKey"] = metadata_box_set_proposal_key(candidate)
                    candidate_members = box_set_proposal_members(candidate)
                    body_members = normalized_box_set_members_from_body(body)
                    if body_members:
                        candidate["members"] = body_members
                        candidate["movies"] = body_members
                        candidate_members = body_members
                    if clean_text(candidate.get("title")) and len(candidate_members) >= 2:
                        candidate["members"] = candidate_members
                        candidate["movies"] = candidate_members
                        box_set_proposal = candidate
                if wants_box_set_import and not box_set_proposal and not metadata_result:
                    metadata_result = lookup_metadata_sources(conn, {**body, "detectBoxSets": True}, actor)
                if wants_box_set_import and not box_set_proposal:
                    box_set_proposal = metadata_box_set_proposal(metadata_result, selected_box_set_key)
                if wants_box_set_import and not box_set_proposal:
                    if explicit_box_set_import:
                        raise NextApiError("No confirmed box-set proposal with at least two members was found.", 422)
                    # Box-set import was only inferred (e.g. a collection was detected while
                    # adding a single film); fall back to importing the movie instead of failing.
                    wants_box_set_import = False
                if wants_box_set_import and box_set_proposal:
                    body_members = normalized_box_set_members_from_body(body)
                    explicit_review_payload = has_provided_box_set or bool(body_members) or bool(selected_box_set_key)
                    if box_set_proposal_is_candidate_only(box_set_proposal) and not explicit_review_payload:
                        raise NextApiError("Box-set candidate members require review before import.", 422)
                    box_set_proposal = enrich_box_set_proposal_artwork(box_set_proposal, metadata_result, body)
                    box_set_import = import_box_set_proposal(conn, box_set_proposal, body, actor)
                    box_set_receiver_summary: dict[str, Any] = {"skipped": True, "reason": "no_receiver_payload"}
                    box_set_detail = box_set_import.get("container") if isinstance(box_set_import.get("container"), dict) else {}
                    imported_container = box_set_detail.get("container") if isinstance(box_set_detail.get("container"), dict) else {}
                    if imported_container:
                        receiver_payload = container_receiver_payload(
                            conn,
                            imported_container,
                            imported_container,
                            force_members=True,
                            member_overrides=box_set_import.get("receiverMembers") or [],
                            replace_members=bool(box_set_import.get("memberSelectionReplaced")),
                            source_label="DiscVault box-set import",
                            source_provider="discvault_box_set_import",
                        )
                        if receiver_payload:
                            box_set_receiver_summary = queue_receiver_payload_to_receivers(
                                conn,
                                payload=receiver_payload,
                                actor=actor,
                                reason="box_set_import",
                            )
                            audit_event(
                                conn,
                                event_type="metadata.receiver_queued",
                                category="metadata",
                                actor=actor,
                                target_type="container",
                                target_id=parse_uuid(imported_container.get("id"), "containerId"),
                                summary=f"Queued imported box-set receiver payload for {imported_container.get('title')}",
                                metadata={
                                    "containerType": imported_container.get("container_type"),
                                    "title": imported_container.get("title"),
                                    "barcode": imported_container.get("barcode"),
                                    "memberCount": len(receiver_payload.get("payload", {}).get("members") or []),
                                    "changedFields": (receiver_payload.get("metadata") or {}).get("changedFields") or [],
                                    "receiverSummary": box_set_receiver_summary,
                                },
                            )
                    first_movie = (box_set_import.get("movies") or [{}])[0]
                    box_set_state = "box_set_created" if box_set_import.get("containerCreated") else "already_exists"
                    return response(
                        {
                            "status": "ok",
                            "state": box_set_state,
                            "movie": first_movie,
                            "detail": movie_detail_entity(conn, first_movie.get("id")) if first_movie.get("id") else None,
                            "boxSet": box_set_import.get("container"),
                            "movies": box_set_import.get("movies") or [],
                            "metadata": metadata_result,
                            "applied": {"boxSet": box_set_import.get("appliedMembers") or []},
                            "queuedMetadataRefreshJobs": box_set_import.get("queuedMetadataRefreshJobs") or [],
                            "decisionCounts": box_set_import.get("decisionCounts") or {},
                            "receiverSummary": box_set_receiver_summary,
                        },
                        201,
                    )
                if not metadata_result:
                    metadata_result = lookup_metadata_sources(conn, {**body, "detectBoxSets": False}, actor)
                proposal = metadata_result.get("proposal") if isinstance(metadata_result.get("proposal"), dict) else {}
                selected_movie_candidate = selected_import_movie_candidate_from_body(body)
                if selected_movie_candidate:
                    proposal = merge_selected_import_movie_candidate(proposal, selected_movie_candidate)
                movie_updates = proposal.get("movieUpdates") if isinstance(proposal.get("movieUpdates"), dict) else {}
                metadata_updates = proposal.get("metadataUpdates") if isinstance(proposal.get("metadataUpdates"), dict) else {}
                fallback_candidate = metadata_import_candidate(metadata_result)
                if selected_movie_candidate:
                    fallback_candidate = {**fallback_candidate, **selected_movie_candidate}
                import_title = clean_text(
                    movie_updates.get("title")
                    or movie_updates.get("original_title")
                    or fallback_candidate.get("title")
                    or title
                )
                if not import_title:
                    raise NextApiError("No movie title was found for this import.", 422)

                payload = dict(movie_updates)
                payload["title"] = import_title
                if selected_movie_candidate.get("barcode") and not barcode:
                    barcode = clean_text(selected_movie_candidate.get("barcode"))
                if barcode:
                    payload["barcode"] = barcode
                if fallback_candidate.get("year") and not payload.get("year"):
                    payload["year"] = fallback_candidate["year"]
                if fallback_candidate.get("format") and not payload.get("format"):
                    payload["format"] = fallback_candidate["format"]
                if fallback_candidate.get("overview") and not payload.get("overview"):
                    payload["overview"] = fallback_candidate["overview"]
                if fallback_candidate.get("poster_url") and not metadata_updates.get("poster_url"):
                    metadata_updates = {**metadata_updates, "poster_url": fallback_candidate["poster_url"]}
                if metadata_updates:
                    payload["metadata"] = metadata_updates
                if body.get("format") and not payload.get("format"):
                    payload["format"] = clean_text(body.get("format"))
                if body.get("year") and not payload.get("year"):
                    payload["year"] = clean_text(body.get("year"))

                mutation_id = f"import-movie-{uuid.uuid4()}"
                upsert = apply_movie_upsert(
                    conn,
                    client_id="next-import-center",
                    idem_key=f"next-import-center:{mutation_id}",
                    mutation={
                        "clientMutationId": mutation_id,
                        "entityType": "movie",
                        "operation": "upsert",
                        "payload": payload,
                    },
                )
                movie_id = upsert["entityId"]
                applied = apply_metadata_proposal(conn, movie_id, proposal, actor=actor)
                detail = movie_detail_entity(conn, movie_id)
                metadata_refresh_job = queue_movie_metadata_refresh_job(
                    conn,
                    movie_id,
                    actor=actor,
                    reason="import_center_full_refresh",
                    source="import_center",
                    extra={
                        "barcode": barcode,
                        "title": import_title,
                    },
                )
                audit_event(
                    conn,
                    event_type="movie.imported",
                    category="import",
                    actor=actor,
                    target_type="movie",
                    target_id=movie_id,
                    summary=f"Imported movie {import_title}",
                    metadata={
                        "barcode": barcode,
                        "title": import_title,
                        "sources": metadata_result.get("sources") or [],
                        "selectedCandidate": selected_movie_candidate,
                        "applied": applied,
                        "metadataRefreshQueued": bool(metadata_refresh_job),
                        "metadataJobId": str(metadata_refresh_job.get("id")) if metadata_refresh_job else None,
                        "targetContainerId": str(target_container_uuid) if target_container_uuid else None,
                    },
                )
                target_link_result = None
                target_container_detail = None
                if target_container_uuid:
                    target_link_result = link_movie_into_container(conn, target_container_uuid, movie_id, actor=actor)
                    target_container_detail = container_detail_entity(conn, target_container_uuid)

        created_payload: dict[str, Any] = {
            "status": "ok",
            "state": "created",
            "movie": detail.get("movie") if detail else upsert.get("entity"),
            "detail": detail,
            "metadata": metadata_result,
            "applied": applied,
            "metadataRefreshQueued": bool(metadata_refresh_job),
            "metadataJob": metadata_refresh_job,
        }
        if target_container_uuid:
            created_payload["linkedToContainer"] = str(target_container_uuid)
            created_payload["containerType"] = target_container_type
            created_payload["linkChanged"] = target_link_result["changed"] if target_link_result else 0
            created_payload["container"] = target_container_detail
        return response(created_payload, 201)

    @flask_app.post("/api/next/import/source/inspect")
    def inspect_import_source():
        body = request.get_json(silent=True) or {}
        if not isinstance(body, dict):
            raise NextApiError("Import source inspect body must be an object", 400)
        plugin_id = clean_text(body.get("importSourceId") or body.get("import_source_id") or body.get("pluginId"))
        if not plugin_id:
            raise NextApiError("importSourceId is required", 400)
        source_path = clean_text(body.get("sourcePath") or body.get("source_path") or body.get("path"))
        column_mapping = normalize_import_column_mapping(body.get("columnMapping") or body.get("column_mapping"))
        payload = import_source_payload_for_path(plugin_id, source_path, column_mapping)
